@use "../default/variables" as *; // Importing all the variables
@use "../default/extend" as *; // Importing all the extend
@use "../default/mixins" as *; // Importing all the mixins

.rbt-blog-details-area {

    .rbt-blog-thumbnail {
        padding: 24px;
        background: var(--color-white);
        border-radius: var(--radius-big);
        margin-bottom: 40px;
    }

    .rbt-blog-details-content {
        p {
            margin-bottom: 20px;

            &:last-child {
                margin-bottom: 0;
            }
        }

        hr {
            margin: 20px 0;
            background-color: var(--color-gray-100);
        }

        td,
        tfoot td {
            border-color: var(--color-gray-100);
        }

        pre {
            background: var(--color-brand-50);
            border-radius: var(--radius);
            font-family: var(--font-primary);
            color: var(--color-gray-600);
        }
    }

    blockquote {
        position: relative;
        padding: 32px 112px 32px 32px;
        background: var(--color-brand-100);
        border-radius: var(--radius-12);
        color: var(--color-gray-700);
        font-family: var(--font-primary);
        font-size: var(--h4);
        font-style: normal;
        font-weight: var(--f-regular);
        line-height: var(--line-height-b4);

        @media #{$md-layout} {
            padding: 32px 56px 32px 32px;
        }
        @media #{$sm-layout} {
            padding: 32px;
        }

        &::after {
            content: "";
            position: absolute;
            top: 36px;
            right: 32px;
            background-image: url(../images/blog-details/blockquote.svg);
            background-repeat: no-repeat, repeat;
            width: 52px;
            height: 44px;

            @media #{$sm-layout} {
                top: 5px;
                right: 0px;
            }
        }

        p {
            color: inherit;
            font-size: inherit;
            font-weight: inherit;
            line-height: inherit;
            margin: 0;
        }
    }

    .rbt-blog-categories-share {
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        justify-content: space-between;

        .rbt-blog-categories {
            .rbt-blog-categories-list {
                list-style: none;
                display: flex;
                flex-wrap: wrap;
                gap: 16px;
                padding: 0;
                margin: 20px 0;

                li {
                    margin: 0;
                    padding: 0;

                    a {
                        display: inline-block;
                        padding: 6px 12px 6px 28px;
                        border: 2px solid var(--color-gray-200);
                        border-radius: var(--radius);
                        position: relative;

                        &::before {
                            content: "";
                            position: absolute;
                            left: 12px;
                            top: 50%;
                            transform: translateY(-50%);
                            width: 6px;
                            height: 6px;
                            background: var(--color-primary);
                            border-radius: var(--radius-full);
                            transition: .3s;
                        }

                        &:hover {
                            &::before {
                                scale: 1.3;
                            }
                        }
                    }
                }
            }
        }
    }


    // sidebar content styles
    .rbt-recent-blog-single {
        display: flex;
        gap: 16px;
        align-items: center;
        margin-bottom: 16px;

        &+.rbt-recent-blog-single {
            border-top: 2px solid var(--color-gray-100);
            padding-top: 16px;
        }

        .rbt-recent-blog-single-thumb {
            height: 80px;
            width: 80px;
            min-width: 80px;
            border-radius: var(--radius-md);
            overflow: hidden;
        }

        .rbt-blog-post-meta {
            margin-bottom: 8px;

            .rbt-blog-details-meta-list {
                li {
                    color: var(--color-gray-400);
                    font-family: var(--font-primary);
                    font-size: var(--font-size-b4);
                    line-height: var(--line-height-b4);
                    font-weight: var(--f-medium);
                }
            }
        }

        .rbt-recent-blog-title {
            color: var(--color-heading);
            font-family: var(--font-primary);
            font-size: var(--font-size-b3);
            line-height: var(--line-height-b3);
            font-weight: var(--f-medium);
            margin-bottom: 0;

            a {
                transition: var(--transition);
            }
        }
    }

    .rbt-blog-details-categories {
        .rbt-blog-category-single {
            a {
                display: flex;
                align-items: center;
                justify-content: space-between;
                color: var(--color-gray-500);
                font-family: var(--font-primary);
                font-size: var(--font-size-b3);
                line-height: var(--line-height-b3);
                font-weight: var(--f-medium);
                transition: var(--transition);

                &:hover {
                    color: var(--color-primary);
                }
            }
        }
    }

    .rbt-sidebar-widget-img {
        max-width: 274px;
    }
}

