// recent blog post style
.rbt-recent-blog-posted-area {

    .rbt-blog-post-card {
        .rbt-blog-thumbnail {
            display: inline-block;
            position: relative;
            border-radius: var(--radius-12) 0 var(--radius-12) var(--radius-12);
            overflow: hidden;
            img {
                transition: var(--transition);
            }
            .rbt-thumb-top-right-shape {
                display: inline-block;
                width: 50%;
                height: 32px;
                background: var(--color-gray-light);
                position: absolute;
                top: 0;
                right: 0;
                border-radius: 0 0 0 var(--radius-big);

                &::before {
                    content: "";
                    position: absolute;
                    width: 30px;
                    height: 30px;
                    background: transparent;
                    border-radius: var(--radius-full);
                    top: 0px;
                    left: -30px;
                    box-shadow: 16px -16px 0px 4px var(--color-gray-light);
                }

                &::after {
                    content: '';
                    width: 30px;
                    height: 30px;
                    background: transparent;
                    border-radius: var(--radius-full);
                    position: absolute;
                    right: 0;
                    bottom: -30px;
                    box-shadow: 16px -16px 0px 4px var(--color-gray-light);
                }
            }
        }

        .rbt-blog-details-meta {
            margin: 8px 0;

            .rbt-blog-details-meta-list {
                list-style: none;
                padding: 0;
                margin: 0;
                display: flex;
                flex-wrap: wrap;
                align-items: center;

                li {
                    margin: 0;
                    padding: 0;

                    &+li {
                        margin-left: 8px;

                        &::before {
                            content: '/';
                            margin-right: 4px;
                        }
                    }
                }
            }
        }

        .rbt-blog-title {
            font-size: var(--font-size-b1);
            line-height: var(--line-height-b1);
            margin-bottom: 0;
        }
        &:hover {
            .rbt-blog-thumbnail{
                img {
                    scale: 1.05;
                }
            }
        }
    }
}

// comment styles
.rbt-comment-list {
    @extend %liststyle;

    ul {
        &.rbt-child-comment {
            @extend %liststyle;
            padding-left: 75px;

            @media #{$sm-layout} {
                padding-left: 20px;
            }
        }
    }

    .comment {
        margin-top: 0;
        margin-bottom: 0;
        border-top: 1px solid var(--color-gray-100);

        &:first-child {
            border-top: transparent;
        }
        &:last-child {
            border-bottom: 0;
        }

        .rbt-child-comment {
            .comment {
                border-top: 1px solid var(--color-gray-100);
            }
        }

        .single-comment {
            padding: 20px 0;
            display: flex;

            @media #{$large-mobile} {
                display: block;
            }

            .comment-img {
                margin-bottom: 15px;
                min-width: 48px;
                max-width: 48px;
                margin-right: 20px;

                img {
                    border-radius: 100%;
                    width: 100%;
                    background: var(--color-white);
                    padding: 4px;
                    border: 2px solid var(--color-brand-200);
                }
            }
        }

        .commenter {
            margin-bottom: 4px;

            a {
                color: var(--color-heading);
                font-family: var(--font-primary);
                font-size: var(--font-size-b1);
                font-weight: var(--f-medium);
                line-height: var(--line-height-b1);

                &:hover {
                    color: var(--color-primary);
                }

                .hover-flip-item {
                    span {
                        &::before {
                            color: var(--color-heading);
                        }

                        &::after {
                            color: var(--color-primary);
                        }
                    }
                }
            }
        }

        .comment-meta {
            display: flex;
            align-items: center;
            margin-bottom: 12px;
            flex-wrap: wrap;
        }

        .time-spent {
            color: var(--color-gray-600);
            font-family: var(--font-primary);
            font-size: var(--font-size-b3);
            font-weight: var(--f-regular);
            line-height: var(--line-height-b3);
        }

        .reply-edit {
            a {
                &.comment-reply-link {
                    font-size: var(--font-size-b3);
                    line-height: var(--line-height-b3);
                    margin-top: 4px;
                    display: flex;
                    color: var(--color-primary);
                    position: relative;
                    font-weight: var(--f-medium);
                    overflow: visible;
                    @extend %transition;

                    .hover-flip-item {
                        span {
                            &::before {
                                color: var(--color-heading);
                            }

                            &::after {
                                color: var(--color-primary);
                            }
                        }
                    }

                    &:hover {
                        color: var(--color-primary);
                    }
                }
            }
        }

        .comment-text {
            p {
                color: var(--color-tertiary);
            }
        }
        .rbt-commented-img-list{
            display: flex;
            @extend %liststyle;
            gap: 16px;
            flex-wrap: wrap;
            li{
                a{
                    display: block;
                    position: relative;
                    overflow: hidden;
                    border-radius: 4px;
                    max-width: 100px;
                    img{
                        max-width: 100%;
                        height: auto;
                        transition: var(--transition);  
                        object-fit: cover;
                        z-index: revert-layer;
                    }
                    .text{
                        position: absolute;
                        top: 50%;
                        left: 50%;
                        color: var(--color-white);
                        transform: translate(-50%, -50%);
                        font-size: var(--font-size-b2);
                        max-width: 80%;
                        line-height: var(--line-height-b2);
                        text-align: center;
                    }
                    &:hover{
                        opacity: 0.8;
                        img{
                            scale: 1.05;
                        }
                    }
                }
            }
        }
    }
}


