@use "../default/variables" as *; // Importing all the variables
@use "../default/extend" as *; // Importing all the extend
@use "../default/mixins" as *; // Importing all the mixins

:root {
    --splash-shadow: 0px 8px 100px 0px #EAEAEA;
}

.splash-section-gap {
    padding: 120px 0;

    @media #{$md-layout} {
        padding: 80px 0;
    }

    @media #{$sm-layout} {
        padding: 48px 0;
    }
}

.splash-section-gapTop {
    padding-top: 120px;

    @media #{$md-layout} {
        padding-top: 80px;
    }

    @media #{$sm-layout} {
        padding-top: 48px;
    }
}

.splash-section-gapBottom {
    padding-bottom: 120px;

    @media #{$md-layout} {
        padding-bottom: 80px;
    }

    @media #{$sm-layout} {
        padding-bottom: 48px;
    }
}

.splash-section-gap2 {
    padding: 100px 0;

    @media #{$md-layout} {
        padding: 80px 0;
    }

    @media #{$sm-layout} {
        padding: 48px 0;
    }
}

.splash-section-gap2Top {
    padding-top: 100px;

    @media #{$md-layout} {
        padding-top: 80px;
    }

    @media #{$sm-layout} {
        padding-top: 48px;
    }
}

.splash-section-gap2Bottom {
    padding-bottom: 100px;

    @media #{$md-layout} {
        padding-bottom: 80px;
    }

    @media #{$sm-layout} {
        padding-bottom: 48px;
    }
}

.rbt-splash-common-sec-bg {
    background: #EFF1F4;
}

.rbt-splash-common-sec-bg-2 {
    background: #F9F9F9;
}

.splash-page-bg {
    background-color: #F9F9F9;
}

// sticky section
.rbt-sticky-section {
    --stickyheader-height: 112px;
    margin: 0 auto;
    position: sticky;
    top: calc(var(--stickyheader-height) + 0);
    transition: margin 0.3s ease;

    &.sticky-sec-1 {
        top: calc(var(--stickyheader-height) + 24px);
    }

    &.sticky-sec-2 {
        top: calc(var(--stickyheader-height) + 48px);
    }

    &.sticky-sec-3 {
        top: calc(var(--stickyheader-height) + 72px);
    }

    @media #{$sm-layout} {
        position: static;
    }
}

.rbt-splash-section-title {
    margin-bottom: 40px;
    position: relative;

    .icons {
        font-size: 32px;
        display: flex;
        gap: 24px;
        margin-bottom: 24px;
    }

    .subtitle {
        font-size: 20px;
        display: inline-block;
        margin-bottom: 8px;
        color: var(--color-black);
        font-family: var(--font-primary);
        position: relative;
        z-index: 2;
    }

    .rbt-title {
        font-size: 52px;
        color: var(--color-black);
        line-height: 1;
        position: relative;
        z-index: 1;

        @media #{$lg-layout} {
            font-size: 44px;
        }

        @media #{$sm-layout, $md-layout} {
            font-size: 32px;
        }

        .rbt-title-sm-text {
            font-size: 40px;
            font-weight: var(--f-regular);

            @media #{$lg-layout} {
                font-size: 36px;
            }

            @media #{$sm-layout, $md-layout} {
                font-size: 28px;
            }
        }

        // overlay text variation
        .rbt-overlay-text {
            font-size: 280px;
            font-weight: 700;
            padding: 6px 0;
            position: absolute;
            left: 50%;
            transform: translateX(-50%);
            top: -54%;
            line-height: 0.7;
            z-index: -1;
            white-space: nowrap;
            user-select: none;

            &.overlay-sm {
                font-size: 112px;
            }

            &.overlay-text-color-var-2 {
                background: linear-gradient(180deg, #D8E8FF 0%, #EFF1F4 100%);
                background-clip: text;
                -webkit-background-clip: text;
                -webkit-text-fill-color: transparent;
            }

            &.overlay-text-color-var-3 {
                background: linear-gradient(180deg, #FFF 0%, rgba(255, 255, 255, 0) 100%);
                background-clip: text;
                -webkit-background-clip: text;
                -webkit-text-fill-color: transparent;
                opacity: 0.1;
            }

            @media #{$md-layout} {
                font-size: 160px;
            }

            @media #{$sm-layout} {
                font-size: 110px;
            }

            @media #{$small-mobile} {
                font-size: 80px;
            }
        }

        .rbt-text-sm {
            font-size: 40px;
            font-weight: 400;

            @media #{$sm-layout} {
                font-size: 30px;
            }
        }
    }

    p {
        color: #333;
    }

    .rbt-input-field {
        max-width: 580px;
        position: relative;
        margin: 0 auto;

        .rbt-icon {
            position: absolute;
            left: 16px;
            top: 50%;
            transform: translateY(-50%);
            line-height: 1;
        }

        input {
            border-radius: 100px;
            padding-left: 36px;
            color: var(--color-heading);
            box-shadow: none;

            &::placeholder {
                color: var(--color-body);
            }
        }
    }
}

// overlay counter
.rbt-overlay-counter {
    font-size: 280px;
    line-height: 1;
    font-weight: 700;
    user-select: none;

    @media #{$md-layout} {
        font-size: 160px;
    }

    @media #{$sm-layout} {
        font-size: 110px;
    }

    @media #{$small-mobile} {
        font-size: 50px;
    }

    .odometer {
        .odometer-digit {
            .odometer-value {
                background: linear-gradient(180deg, rgba(33, 90, 218, 0.3) 0%, rgba(239, 241, 244, 0.3) 87.5%);
                background-clip: text;
                -webkit-background-clip: text;
                -webkit-text-fill-color: transparent;
            }
        }
    }

    .counter-suffix {
        background: linear-gradient(180deg, rgba(33, 90, 218, 0.3) 0%, rgba(239, 241, 244, 0.3) 87.5%);
        background-clip: text;
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
    }

    &.counter-sm {
        font-size: 112px;
    }

    &.counter-md {
        font-size: 180px;

        .counter-suffix {
            margin-left: -46px;
        }
    }

    &.color-variation-2 {
        .odometer {
            .odometer-digit {
                .odometer-value {
                    background: linear-gradient(180deg, rgba(33, 90, 218, 0.6) 0%, rgba(0, 0, 0, 0.6) 87.5%);
                    background-clip: text;
                    -webkit-background-clip: text;
                    -webkit-text-fill-color: transparent;
                }
            }
        }

        .counter-suffix {
            background: linear-gradient(180deg, rgba(33, 90, 218, 0.6) 0%, rgba(0, 0, 0, 0.6) 87.5%);
            background-clip: text;
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
        }
    }
}

.rbt-splash-gradient-text {
    background: linear-gradient(to left, #4BE53E, #302AEF);
    background-clip: text;
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

// light shape
.rbt-splash-bg-light {
    position: absolute;
    width: 262px;
    height: 262px;
    background: var(--color-primary);
    filter: blur(150px);
    border-radius: var(--radius-full);

    @media #{$sm-layout, $md-layout} {
        width: 188px;
        height: 188px;
    }

    &.bg-light-sm {
        width: 134px;
        height: 134px;
    }

    &.light-center-left {
        left: 0;
        top: 50%;
        transform: translateY(-50%);
    }

    &.light-center-right {
        right: 0;
        top: 50%;
        transform: translateY(-50%);
    }

    &.light-top-right {
        top: 20%;
        right: 0;
    }

    &.light-top-left {
        top: 20%;
        left: 0;
    }

    &.light-bottom-left {
        bottom: 20%;
        left: 0;
    }

    &.light-bottom-right {
        bottom: 10%;
        right: 0;
    }
}



/**************************************
            header style
***************************************/
.splash-header-campaign-area {
    .icon-close {
        &.position-right {
            right: 16px;
        }
    }
}

.rbt-splash-header-area {
    .header-transparent {
        background: transparent;
        position: absolute;
        width: 100%;
    }

    &.rbt-header {
        .header-transparent {
            .rbt-mainmenu-nav {
                .mainmenu {
                    &>li {
                        &>a {
                            color: var(--color-white);
                        }
                    }
                }
            }

            .rbt-header-common-sticky-activation {
                .rbt-mainmenu-nav {
                    .mainmenu {
                        li {
                            >a {
                                color: var(--color-heading);
                            }
                        }
                    }
                }
            }
        }
    }
}


/**************************************
            Intro video
***************************************/
.rbt-intro-video-box {
    position: absolute;
    top: -12%;
    left: 50%;
    transform: translateX(-50%);
    z-index: 1;
    width: 688px;
    height: 530px;

    @media #{$laptop-device} {
        top: -5%;
    }

    @media #{$lg-layout} {
        top: 24px;
    }

    @media #{$md-layout} {
        top: 24px;
        width: 568px;
        height: 504px;
    }

    @media #{$sm-layout} {
        top: 24px;
        width: 300px;
        height: 284px;
    }

    @media #{$large-mobile} {
        width: 285px;
        height: 227px;
    }

    .desktop {
        width: 100%;
        height: 398px;
        padding: 16px;
        background: linear-gradient(216deg, #B3B3B3, #A8A8A8);
        border-radius: 6px;
        position: absolute;
        top: 2px;
        left: 50%;
        transform: translateX(-50%);

        @media #{$sm-layout} {
            height: 228px;
            padding: 8px;
        }

        @media #{$large-mobile} {
            height: 170px;
            padding: 4px;
        }

        img,
        video {
            display: block;
            width: 100%;
            height: 100%;
        }

        .play-btn {
            display: flex;
            align-items: center;
            justify-content: center;
            height: 124px;
            width: 124px;
            border: 2px solid #E53E3E;
            border-radius: 50%;
            font-size: 40px;
            color: #E53E3E;
            background: rgba(255, 255, 255, 0.5);
            backdrop-filter: blur(3px);
            position: absolute;
            top: 36%;
            left: 42%;

            @media #{$sm-layout, $md-layout} {
                font-size: 24px;
                height: 80px;
                width: 80px;
            }

            @media #{$large-mobile} {
                top: 27%;
                left: 39%;
            }
        }
    }

    .desktop-stand {
        position: absolute;
        bottom: 0;
    }

    .desktop-shadow {
        position: absolute;
        top: calc(100% - 22px);
        left: 50%;
        transform: translateX(-50%);
        z-index: -1;

        @media #{$sm-layout} {
            top: calc(100% - 10px);
        }
    }

    .mini-pc {
        position: absolute;
        right: 0;
        bottom: 0;

        @media #{$sm-layout} {
            max-width: 72px;
        }
    }
}



/**************************************
            Feature Area
***************************************/
.rbt-splash-feature-area {
    padding-top: 348px;
    background: url(../images/splash/section/section-bg-line.webp);

    @media #{$sm-layout} {
        padding-top: 290px;
    }

    .rbt-splash-section-title {
        @media #{$sm-layout} {
            margin-bottom: 0;
        }

        .section-indicator {
            right: auto;
            left: -130px;
            top: -80px;

            @media #{$sm-layout} {
                left: 0;
                top: -32px !important;
                z-index: 0;
            }

            @media #{$lg-layout, $laptop-device} {
                display: none;
            }
        }
    }
}

.rbt-key-features {
    position: relative;
    z-index: 1;

    @media #{$laptop-device} {
        margin-top: 184px;
    }

    @media #{$md-layout, $lg-layout} {
        margin-top: 252px;
    }

    @media #{$sm-layout} {
        margin-top: 24px;
        gap: 12px;
    }

    .single-feature {
        // flex-basis: 23%;
        width: fit-content;
        font-size: 20px;
        color: var(--color-black);
        max-height: 260px;
        min-width: 170px;
        width: 100%;
        text-align: center;
        position: relative;

        &::before {
            content: '';
            position: absolute;
            width: calc(100% + 4px);
            height: 100%;
            background: linear-gradient(180deg, #2158da00, #f9f9f900);
            border-radius: 14px;
            top: -1px;
            left: 50%;
            transform: translateX(-50%);
            z-index: -1;
            opacity: 0;
            transition: var(--transition);
        }

        .inner {
            padding: 56px 16px;
            background: linear-gradient(180deg, #E9F1FC 0%, #F9F9F9 100%);
            border-radius: 12px;
            height: 100%;

            @media #{$sm-layout, $md-layout} {
                padding: 24px 16px 32px;
            }
        }

        &:nth-child(even) {
            margin-top: -24px;
        }

        &:hover {
            &::before {
                top: -2px;
                opacity: 1;
                width: calc(100% + 4px);
                background: linear-gradient(180deg, #215ADA, #F9F9F9);
            }

            &:hover {
                .hover-icon {
                    opacity: 1;
                    visibility: visible;
                }

                .default-icon {
                    opacity: 0;
                    visibility: hidden;
                }
            }
        }

        .icon {
            height: 72px;
            width: 72px;
            background: var(--color-white);
            display: flex;
            align-items: center;
            justify-content: center;
            border-radius: 50%;
            font-size: 32px;
            color: var(--color-primary);
            margin: 0 auto;
            margin-bottom: 12px;
            overflow: hidden;
            position: relative;

            @media #{$sm-layout, $md-layout} {
                height: 52px;
                width: 52px;
                font-size: 20px;
            }

            .default-icon {
                transition: var(--transition);
            }

            .hover-icon {
                max-width: 44px;
                opacity: 0;
                visibility: hidden;
                position: absolute;
                top: 50%;
                left: 50%;
                transform: translate(-50%, -50%);
                transition: var(--transition);
            }

            &.icon-1 {
                img {
                    max-width: 68px;
                }
            }

            &.icon-2 {
                img {
                    width: 60px;
                }
            }

            &.icon-3 {
                img {
                    max-width: 44px;
                }
            }

            &.icon-4 {
                img {
                    max-width: 44px;
                }
            }
        }

        .rbt-description {
            font-size: 20px;
            color: var(--color-black);
            margin-bottom: 0;
        }
    }
}


.rbt-key-features {
    .rbt-single-key-feature-card {
        border-radius: var(--radius-12);
        background: #EFF6FF;
        box-shadow: 0px 8px 100px 0px #EAEAEA;
        position: relative;

        &::after {
            content: "";
            position: absolute;
            height: calc(100% + 2px);
            width: calc(100% + 2px);
            top: -1px;
            left: -1px;
            border-radius: var(--radius-12);
            z-index: -1;
        }

        .rbt-inner {
            position: relative;
            z-index: 1;
            border-radius: var(--radius-12);
        }

        .rbt-content {
            padding: 24px 0 24px 24px;

            .rbt-pre-title {
                color: var(--color-black);
                font-size: var(--font-size-b1);
                margin-bottom: 4px;
            }

            .rbt-key-feature-list {
                padding: 0;
                margin: 0;
                display: flex;
                gap: 10px;
                flex-wrap: wrap;

                li {
                    padding: 4px 10px;
                    margin: 0;
                    display: flex;
                    gap: 4px;
                    align-items: center;
                    font-size: var(--font-size-b4);
                    line-height: 1.86;
                    font-weight: var(--f-semi-bold);
                    color: var(--color-black);
                    background: rgba(219, 235, 255, 0.61);
                    border-radius: 100px;

                    i {
                        color: var(--color-primary);
                    }

                    .rbt-marquee {
                        overflow: hidden;
                        position: relative;
                        max-width: 72px;
                        white-space: nowrap;
                        font-weight: var(--f-regular);

                        &:before {
                            content: "";
                            position: absolute;
                            left: 0;
                            top: 0;
                            height: 100%;
                            width: 20px;
                            background: linear-gradient(to right, #e3f0ff, rgba(255, 255, 255, 0));
                            z-index: 2;
                        }

                        &:after {
                            content: "";
                            position: absolute;
                            right: 0;
                            top: 0;
                            height: 100%;
                            width: 20px;
                            background: linear-gradient(to left, #e3f0ff, rgba(255, 255, 255, 0));
                            z-index: 1;
                        }

                        span {
                            display: inline-flex;
                            position: relative;
                            z-index: 1;
                            line-height: 1.2;
                            font-weight: var(--f-regular);
                            animation: btnTxtMarqueeX 5s linear infinite;

                            &::after {
                                content: attr(data-text);
                                position: absolute;
                                white-space: nowrap;
                                top: 50%;
                                left: 100%;
                                transform: translate(15%, -50%);
                            }
                        }
                    }
                }
            }
        }

        .rbt-key-feature-thumb {
            position: relative;
            border-radius: 0 0 var(--radius-12) var(--radius-12);
            overflow: hidden;
        }

        &.rbt-card-var-1 {
            background: url(../images/splash/feature/bg-dot-line1.svg), #EFF6FF;
            background-position: center;
            background-repeat: no-repeat;

            &::after {
                background: linear-gradient(150deg, rgb(33, 90, 218, 0.5) 0%, rgb(235, 255, 245, 0) 52%);
            }

            .rbt-content {
                .rbt-title {
                    background: linear-gradient(87deg, #000 0.54%, #0039BA 61.46%, #215ADA 87%);
                    background-clip: text;
                    -webkit-background-clip: text;
                    -webkit-text-fill-color: transparent;
                }
            }
        }

        &.rbt-card-var-2 {
            background: url(../images/splash/feature/bg-dot-line3.svg), #EBFFF5;
            background-position: center;
            background-repeat: no-repeat;

            &::after {
                background: linear-gradient(150deg, rgb(29, 191, 115, 0.5) 0%, rgb(235, 255, 245, 0) 52%);
            }

            .rbt-content {
                .rbt-title {
                    background: linear-gradient(90deg, #030303 37.5%, #009D50 73.49%, #00FF82 85.25%);
                    background-clip: text;
                    -webkit-background-clip: text;
                    -webkit-text-fill-color: transparent;
                }

                .rbt-key-feature-list {
                    li {
                        background: rgba(204, 245, 225, 0.51);

                        i {
                            color: #1DBF73;
                        }

                        .rbt-marquee {
                            &:before {
                                background: linear-gradient(to right, #dbfaeb, rgba(255, 255, 255, 0));
                            }

                            &:after {
                                background: linear-gradient(to left, #dbfaeb, rgba(255, 255, 255, 0));
                            }
                        }
                    }
                }
            }
        }

        &.rbt-card-var-3 {
            background: url(../images/splash/feature/bg-dot-line2.svg), #FFF7EF;
            background-position: 0px 176px;
            background-repeat: no-repeat;

            &::after {
                background: linear-gradient(150deg, rgb(247, 131, 31, 0.5) 0%, rgb(235, 255, 245, 0) 52%);
            }

            .rbt-content {
                .rbt-title {
                    background: linear-gradient(90deg, #030303 37.5%, #EA1802 73.49%, #FCA211 85.25%);
                    background-clip: text;
                    -webkit-background-clip: text;
                    -webkit-text-fill-color: transparent;
                }

                .rbt-key-feature-list {
                    li {
                        background: #FED;

                        i {
                            color: #F7831F;
                        }

                        .rbt-marquee {
                            &:before {
                                background: linear-gradient(to right, #ffeedd, rgba(255, 255, 255, 0));
                            }

                            &:after {
                                background: linear-gradient(to left, #ffeedd, rgba(255, 255, 255, 0));
                            }
                        }
                    }
                }
            }
        }

        &.rbt-card-var-4 {
            background: url(../images/splash/feature/bg-dot-line4.svg), var(--color-white);
            background-position: 0 180px;
            background-repeat: no-repeat;
            overflow: hidden;
            position: relative;
            padding: 24px;
            height: calc(100% - 32px);

            .rbt-gradient-animation-colors {
                height: 50px;
                width: 118%;
                position: absolute;
                top: 0%;
                left: 50%;
                transform: translateX(-50%);

                .rbt-color-1 {
                    width: 50%;
                    height: 80%;
                    position: absolute;
                    top: -10px;
                    left: 0;
                    border-radius: 0px 0px 100px 100px;
                    background: #4186FD;
                    filter: blur(30px);
                }

                .rbt-color-2 {
                    width: 50%;
                    height: 100%;
                    position: absolute;
                    top: -5px;
                    left: 50px;
                    border-radius: 0px 0px 100px 100px;
                    background: #FF3F98;
                    filter: blur(30px);
                }

                .rbt-color-3 {
                    width: 50%;
                    height: 100%;
                    position: absolute;
                    top: -5px;
                    right: 37px;
                    border-radius: 0px 0px 100px 100px;
                    background: #E9A5FF;
                    filter: blur(30px);
                }

                .rbt-color-4 {
                    width: 50%;
                    height: 80%;
                    position: absolute;
                    top: -10px;
                    right: 0;
                    border-radius: 0px 0px 100px 100px;
                    background: #FD8C1F;
                    filter: blur(30px);
                }
            }

            .rbt-inner {
                height: 100%;
            }

            .rbt-content {
                position: relative;
                z-index: 2;
                padding: 0;
            }
        }
    }
}

.rbt-feature-capsule-list-wrapper {
    padding: 24px;
    pointer-events: none;
    width: 100%;
    min-height: 250px;

    .rbt-feature-capsule-list {
        position: absolute;
        bottom: 0;
        left: 0;
        width: 100%;
        height: 100%;
        cursor: grab;

        .rbt-capsule-item {
            padding: 0;
            margin: 0;
            position: absolute;
            display: inline-block;
            left: 0;
            top: 0;
            user-select: none;
            pointer-events: auto;
            transition: none;

            span {
                display: inline-block;
                font-size: var(--font-size-b3);
                line-height: 1.97;
                font-weight: 500;
                border-radius: 100px;
                padding: 3px 12px;
                background: var(--color-brand-50);
                color: var(--color-black);
            }

            &.rbt-capsule-highlight {
                span {
                    background: linear-gradient(270deg, #FD998E 0%, #AB4FA9 50.52%, #4D3FAE 100%);
