.rbt-feature-slide-active {
    height: 115px;
    width: 95px;
    position: absolute;
    right: 20px;
    top: 20px;

    &::before {
        content: "";
        position: absolute;
        top: 0;
        right: 0;
        width: 60%;
        height: 40px;
        background: linear-gradient(to bottom, #fff2e4c2, #fff1e300);
        z-index: 2;
        pointer-events: none;
    }

    &::after {
        content: "";
        position: absolute;
        bottom: 0;
        right: 0;
        width: 60%;
        height: 50px;
        background: linear-gradient(to top, #fff2e4c2, #fff1e300);
        z-index: 1;
        pointer-events: none;
    }

    .swiper-slide {
        width: fit-content;
        margin-left: auto;
        transition: var(--transition);
        height: 15px;

        .rbt-slide {
            height: 100%;

            img {
                height: 100%;
            }
        }

        &.swiper-slide-prev,
        &.swiper-slide-next {
            transform-origin: right;
            transform: scale(1.25);
        }

        &.swiper-slide-prev {
            margin-top: -3px;
        }

        &.swiper-slide-next {
            margin-top: -3px;

            &+.swiper-slide {
                margin-top: -3px;
            }
        }

        &.swiper-slide-active {
            transform-origin: right;
            transform: scale(1.5);
            margin-bottom: 13px !important;
        }
    }
}


