            }
        }

        .ele-layout-display .ele-image {
            margin-top: 0;
        }
    }

    &:hover {
        .ele-layout-display {

            img,
            video {
                transform: translateY(0);
            }
        }
    }
}

.rbt-header-group {
    display: flex;
    gap: 40px;
    flex-direction: column;

    @media #{$sm-layout} {
        gap: 24px;
    }

    .rbt-single-header {
        box-shadow: 0px 1.781px 26.712px 3.562px #E1E1E1;
        border-radius: var(--radius-md);
    }
}

.rbt-splash-megamenu-slider-active {
    .swiper-slide {
        width: fit-content;
    }

    .rbt-element {
        width: fit-content;
        box-shadow: 0px 0px 18.376px 4.594px rgba(0, 0, 0, 0.10);

        img {
            width: 100%;
            max-height: 244px;
        }
    }
}

.rbt-megamenu-presentation-area {
    .splash-element-presentation-wrapper {
        position: relative;

        &::after {
            content: "";
            position: absolute;
            width: 100%;
            height: 100%;
            background: linear-gradient(180deg, rgba(239, 241, 244, 0.00) 59.6%, #EFF1F4 100%);
            bottom: 0;
            z-index: 1;
        }
    }
}

// splash buttons
.splash-btn {

    @media #{$lg-layout} {
        font-size: var(--font-size-b1);
        padding: 0 28px;
        height: 44px;
        line-height: 44px;
    }

    @media #{$sm-layout, $md-layout} {
        font-size: var(--font-size-b1);
        padding: 0 20px;
        height: 40px;
        line-height: 40px !important;
    }

    &.icon-reverse-left {
        .icon-left {
            margin-left: -24px;
            opacity: 0;
            transition: opacity 0.6s cubic-bezier(0.68, -0.55, 0.27, 1.55), margin 0.6s cubic-bezier(0.68, -0.55, 0.27, 1.55);
        }

        .icon-right {
            margin-right: 0;
            transition: opacity 0.6s cubic-bezier(0.68, -0.55, 0.27, 1.55), margin 0.6s cubic-bezier(0.68, -0.55, 0.27, 1.55);
        }

        &:hover,
        &:focus {
            .icon-left {
                opacity: 1;
                margin-left: 0;
            }

            .icon-right {
                margin-right: -24px;
                opacity: 0;
            }
        }
    }

    &.icon-reverse-right {
        .icon-left {
            transition: var(--transition);
            transition: opacity 0.6s cubic-bezier(0.68, -0.55, 0.27, 1.55), margin 0.6s cubic-bezier(0.68, -0.55, 0.27, 1.55);
        }

        .icon-right {
            margin-right: -24px;
            opacity: 0;
            transition: var(--transition);
            transition: opacity 0.6s cubic-bezier(0.68, -0.55, 0.27, 1.55), margin 0.6s cubic-bezier(0.68, -0.55, 0.27, 1.55);
        }

        &:hover,
        &:focus {
            .icon-left {
                margin-left: -24px;
                opacity: 0;
            }

            .icon-right {
                margin-right: 0;
                opacity: 1;
            }
        }
    }

    &+.splash-btn {
        &.rbt-btn-border {

            &:hover,
            &:focus {
                background: transparent;
            }
        }
    }

    &:hover,
    &:focus {
        transform: translate3d(0, -2px, 0);
        box-shadow: var(--shadow-7);
        color: var(--color-white);

        &.icon-hover {
            .btn-text {
                transform: translateX(-5px);
            }

            .btn-icon {
                i {
                    opacity: 1;
                    transform: translateX(5px);
                }
            }
        }
    }
}