@use "../default/variables" as *; // Importing all the variables
@use "../default/extend" as *; // Importing all the extend
@use "../default/mixins" as *; // Importing all the mixins

.rbt-product-card {
    height: unset;
    overflow: visible;
    transition: var(--transition);

    .rbt-card-img {
        border-radius: 8px 8px 0 0;

        @media #{$sm-layout} {
            border-radius: 4px 4px 0 0;
        }

        &.rbt-card-img-bg-blue {
            background-color: var(--color-element-bg-blue);
        }

        &.rbt-card-img-bg-yellow {
            background-color: var(--color-element-bg-yellow);
        }

        &.rbt-card-img-bg-green {
            background-color: var(--color-extra-six);
        }

        .rbt-btn {
            --margin-width: 16px;
            margin: 0 var(--margin-width);
            width: calc(100% - (2 * var(--margin-width)));

            &.bottom-position {
                position: absolute;
                bottom: 16px;
                left: 0;
            }
        }

        .hover-appear-element {
            opacity: 0;
            visibility: hidden;
            transition: var(--transition);
        }

        &.rbt-bg-color-default {
            background: var(--color-brand-100);
        }

        &.top-rounded-md {
            border-radius: 12px 12px 0 0;
        }

        &.rbt-has-hover-img {
            position: relative;
            transition: opacity 0.4s ease, transform 0.6s cubic-bezier(0, 0, 0.34, 0.54);

            .rbt-hover-img {
                opacity: 0;
                visibility: hidden;
                position: absolute;
                top: 0;
                left: 0;
                transition: opacity 0.4s ease, transform 0.6s cubic-bezier(0, 0, 0.34, 0.54);
            }

            &:hover {
                .rbt-hover-img {
                    opacity: 1;
                    visibility: visible;
                    transform: scale(1.04);
                }

                .rbt-prd-img {
                    opacity: 0;
                    visibility: hidden;
                }
            }
        }

        &.rbt-has-hover-video {
            position: relative;
            transition: opacity 0.4s ease, transform 0.6s cubic-bezier(0, 0, 0.34, 0.54);

            .rbt-hover-video {
                opacity: 0;
                visibility: hidden;
                position: absolute;
                top: 0;
                left: 0;
                transition: opacity 0.4s ease, transform 0.6s cubic-bezier(0, 0, 0.34, 0.54);
                height: 100%;

                video {
                    object-fit: cover;
                }
            }

            &:hover {
                .rbt-hover-video {
                    opacity: 1;
                    visibility: visible;
                    transform: scale(1.04);
                }

                .rbt-prd-img {
                    opacity: 0;
                    visibility: hidden;
                }
            }
        }

        &.rbt-card-img-h-md {
            img {
                min-height: 312px;

                @media #{$sm-layout} {
                    min-height: 200px;
                }
            }
        }
    }

    .rbt-card-video {
        height: 100%;
        width: 100%;
        transition: var(--transition);
        position: relative;
        border-radius: 8px 8px 0 0;
        overflow: hidden;

        video {
            object-fit: cover;
            height: 100%;
            width: 100%;
            transition: var(--transition);
            border-radius: 8px 8px 0 0;
        }
    }

    &:hover {
        .rbt-quick-btn-grp {
            &.hover-variation-one {
                .rbt-quick-btn {
                    i {
                        background: var(--color-brand-300);

                        &:hover {
                            background: var(--color-primary);
                        }
                    }
                }

                .rbt-quick-btn+.rbt-quick-btn::before {
                    background: url(../images/icons/card-inner-svg/icon-layout-01-brand-color.svg);
                }
            }

            &.hover-variation-one {
                .rbt-quick-btn {
                    opacity: 1;
                    visibility: visible;

                    i {
                        background: var(--color-brand-300);
                        color: var(--color-primary);

                        &:hover {
                            background: var(--color-primary);
                            color: var(--color-white);
                        }
                    }
                }
            }
        }

        .hover-appear-element {
            opacity: 1;
            visibility: visible;
        }
    }

    .rbt-prd-qty-area {
        p {
            margin-bottom: 0;
            color: var(--color-gray-500);

            strong {
                color: var(--color-black);
                font-weight: 600;
            }
        }

        .progress {
            margin-top: 8px;
            border-radius: 50px;
            background: #E5FAE5;
            height: 6px;

            @media #{$sm-layout} {
                margin-top: 4px;
            }

            .progress-bar {
                background: #24BD25;
                border-radius: 5px;
            }
        }
    }

    .prd-btn-grp {
        margin-top: 16px;
        display: flex;
        flex-direction: column;
        gap: 8px;

        @media #{$small-mobile} {
            margin-top: 12px;
            gap: 4px;
        }

        .rbt-btn {
            text-align: center;
            border-width: 1px;
            color: var(--color-primary);

            &.rbt-btn-border.rbt-btn-sm {
                line-height: 34px;

                @media #{$small-mobile} {
                    line-height: 28px;
                }
            }

            &.has-left-icon {
                i {
                    margin-right: 4px;
                }
            }

            &.rbt-btn-primary {
                color: var(--color-white);
            }

            i {
                font-size: var(--font-size-b2);
                line-height: 15px;
            }

            &:hover,
            &:focus {
                color: var(--color-white) !important;
            }

            &.rbt-btn-transparent {
                border: none;
                color: var(--color-gray-700);

                &:hover {
                    color: var(--color-white);
                }
            }

            &.rbt-compare-btn-activation {
                &.added-compare {
                    background: var(--color-primary);
                    color: var(--color-white);

                    .fa-file-plus-minus {
                        &::before {
                            content: "\f00c";
                        }
                    }
                }
            }
        }
    }

    .rbt-product-switch-area {
        display: flex;
        align-items: center;
        gap: 4px 12px;
        flex-wrap: wrap;

        @media #{$small-mobile} {
            gap: 4px 8px;
        }

        .rbt-switcher-product-list {
            display: flex;
            align-items: center;
            justify-content: center;
            margin: 0;
            padding: 0;
            list-style: none;
            gap: 8px;

            @media #{$sm-layout} {
                gap: 4px;
            }

            li {
                display: block;
                width: 40px;
                transition: all 0.6s cubic-bezier(0, 0, 0.34, 0.54);
                border: 1px solid var(--color-gray-200);
                border-radius: 8px;
                padding: 2px;
                margin: 0;

                @media #{$small-mobile} {
                    width: 24px;
                    padding: 1px;
                }

                .rbt-switcher--prd {
                    display: block;
                    position: relative;
                    overflow: hidden;
                    border-radius: 6px;

                    img {
                        object-fit: cover;
                        width: 100%;
                        transform: scale(1);
                        transition: all 0.4s cubic-bezier(0, 0, 0.34, 0.54);
                    }
                }

                &.active {
                    border-color: var(--color-primary);

                    .rbt-switcher--prd {
                        img {
                            transform: scale(1.2);
                        }
                    }
                }
            }
        }

        .prd-link-text {
            font-size: var(--font-size-b4);
            line-height: var(--line-height-b4);

            @media #{$small-mobile} {
                font-size: 8px;
            }
        }
    }

    .rbt-product-feature-badge {
        border-radius: 40px;
        background: linear-gradient(90deg, #FEEDDE 0%, rgba(254, 237, 222, 0.00) 100%);
        padding: 4px 8px;
        margin-top: 8px;
        font-size: var(--font-size-b4);
        line-height: var(--line-height-b4);
        font-weight: 600;
        display: inline-block;
        color: #CD6E00;
    }

    .inner {
        padding: 8px;
        border-radius: 12px;
        border: 2px solid var(--color-gray-200);
        background: var(--color-white);
        transition: var(--transition);

        @media #{$sm-layout} {
            padding: 4px;
            border-radius: var(--radius);
        }
    }

    .rbt-quick-btn-grp {
        opacity: 0;
        visibility: hidden;
        transition: opacity 0.4s ease, transform 0.4s cubic-bezier(0, 0, 0.34, 0.54);
        z-index: 2;

        .rbt-quick-btn {
            position: relative;
            padding: 0;
            background: 0 !important;
            display: block;
            border: 0;

            & i {
                border-radius: var(--radius-full);
                height: 36px;
                width: 36px;
                background: var(--color-white);
                color: var(--color-primary);
                font-size: 16px;
                display: flex;
                justify-content: center;
                align-items: center;
                position: relative;
                z-index: 2;
                transition: var(--transition);

                @media #{$small-mobile} {
                    height: 28px;
                    width: 28px;
                    font-size: 14px;
                }
            }

            &+.rbt-quick-btn {
                margin-top: 6px;

                &::before {
                    content: "";
                    position: absolute;
                    top: -15px;
                    left: 50%;
                    transform: translateX(-50%);
                    height: 24px;
                    width: 15px;
                    background: url(../images/icons/card-inner-svg/icon-layout-01.svg);
                    background-size: cover;
                    background-repeat: no-repeat;
                    background-position: bottom;
                }
            }

            &:hover {
                & i {
                    background: var(--color-primary);
                    color: var(--color-white);
                }
            }

            &.added-wishlist,
            &.added-compare {
                background: transparent;

                & i {
                    background: var(--color-primary);
                    color: var(--color-white);
                }

                &:hover {
                    & i {
                        background: var(--color-primary);
                        color: var(--color-white);
                    }
                }
            }

            &.rbt-stockout-btn {
                &:hover {
                    & i {
                        background: var(--color-gray-400);
                        color: var(--color-white);
                    }

                    &.tooltips span {
                        background: var(--color-gray-400);
                        color: var(--color-white);

                        &::after {
                            border-left-color: var(--color-gray-400);
                        }
                    }
                }
            }
        }

        &.rbt-top-right--position {
            position: absolute;
            top: 16px;
            right: 16px;
            transform: translateX(10px);

            @media #{$small-mobile} {
                top: 8px;
                right: 8px;
            }
        }

        &.bottom-right--position {
            position: absolute;
            bottom: 12px;
            right: 12px;
            transform: translateX(10px);

            @media #{$small-mobile} {
                bottom: 8px;
                right: 8px;
            }
        }

        &.hover-variation-one {
            opacity: 1;
            visibility: visible;
            transform: translate(0);

            .rbt-quick-btn {
                opacity: 0;
                visibility: hidden;

                i {
                    transition: var(--transition);
                    background: rgba(255, 255, 255, 0.5);
                    color: var(--color-gray-300);
                }

                &:first-child {
                    opacity: 1;
                    visibility: visible;
                }

                &.bg-light-one {
                    background: none;

                    i {
                        background: var(--color-brand-300);
                        color: var(--color-primary);
                    }

                    &.added-wishlist,
                    &.added-compare {
                        & i {
                            background: var(--color-primary);
                            color: var(--color-white);
                        }

                        &:hover {
                            & i {
                                background: var(--color-primary);
                                color: var(--color-white);
                            }
                        }
                    }
                }
            }

            .rbt-quick-btn+.rbt-quick-btn::before {
                background: url(../images/icons/card-inner-svg/icon-layout-01-brand-color.svg);
            }
        }
    }

    &:hover {
        .rbt-quick-btn-grp {
            opacity: 1;
            visibility: visible;
            transform: translate(0);
        }
    }

    .rbt-product-badge {
        &.rbt-badge-top-left--position {
            position: absolute;
            top: 16px;
            left: 16px;

            @media #{$small-mobile} {
                top: 8px;
                left: 8px;
            }

            &+.rbt-badge-top-left--position {
                margin-top: 28px;

                @media #{$small-mobile} {
                    margin-top: 18px;
                }
            }
        }
    }

    .rbt-card-body {
        padding: 8px;
        padding-top: 16px;
        text-align: left;

        @media #{$small-mobile} {
            padding: 4px;
            padding-top: 12px;
        }

        .rbt-card-subtitle {
            margin-top: 16px;

            @media #{$small-mobile} {
                margin-top: 8px !important;
            }
        }

        >*:nth-child(1) {
            margin-top: 0 !important;

            *:nth-child(1) {
                margin-top: 0 !important;
            }
        }

        .pricing-part {
            margin-top: 8px;
            flex-wrap: nowrap;

            @media #{$small-mobile} {
                margin-top: 4px;
                flex-wrap: wrap;
            }

            @media #{$xl-layout} {
                flex-wrap: wrap;
            }
        }

        .rbt-card-top-content {
            &.has-two-align {
                padding: 0;
                display: flex;
                justify-content: space-between;
                align-items: center;
                flex-wrap: nowrap;
                gap: 8px 16px;

                @media #{$small-mobile} {
                    flex-direction: column;
                    align-items: flex-start;
                    gap: 4px 8px;
                }

                .right-part {
                    @media #{$small-mobile} {
                        align-items: flex-start;
                    }

                    .bottom-part {
                        @media #{$small-mobile} {
                            text-align: left;
                        }
                    }
                }
            }
        }

        .rbt-card-footer {
            &.footer-content-btn {
                margin-top: 18px;
                gap: 8px;

                @media #{$sm-layout} {
                    margin-top: 12px;
                }

                .rbt-quick-btn-grp {
                    flex-basis: 14%;
                    display: flex;

                    .rbt-quick-btn {
                        i {
                            background: var(--color-brand-300);
                        }

                        &:hover {
                            i {
                                background: var(--color-primary);
                            }
                        }

                        &.added-compare,
                        &.added-wishlist {
                            i {
                                background: var(--color-green);
                                color: var(--color-white);
                            }

                            &:hover {
                                i {
                                    background: var(--color-green);
                                    color: var(--color-white);
                                }
                            }
                        }

                        &+.rbt-quick-btn {
                            margin-top: 0;
                            margin-left: 6px;

                            &::before {
                                top: 50%;
                                transform: translateY(-50%) rotate(90deg);
                                width: 15px;
                                right: calc(100% + -5px);
                                left: unset;
                                background: url(../images/icons/card-inner-svg/icon-layout-01-brand-color.svg);
                            }
                        }
                    }
                }

                .rbt-btn {
                    flex-basis: 85%;
                    text-align: center;
                }
            }
        }

        .right-part {
            text-align: end;
            display: flex;
            flex-direction: column;
            align-items: end;
        }

        &.has-two-align {
            display: flex;
            justify-content: space-between;
            align-items: center;

            @media #{$sm-layout} {
                flex-wrap: wrap;
            }
        }

        &.rbt-card-body-center-align {
            text-align: center;
            justify-content: center;

            .rbt-card-subtitle,
            .rbt-card-rating,
            .pricing-part {
                justify-content: center;
            }
        }
    }

    .rating-digit {
        margin-bottom: 0;
    }

    .rbt-card-rating {
        gap: 8px;

        @media #{$small-mobile} {
            gap: 4px;
        }

        .rbt-text-group {
            font-size: var(--font-size-b4);
            height: 24px;
            line-height: 24px;

            @media #{$small-mobile} {
                height: 16px;
                line-height: 16px;
            }
        }

        .icon {
            color: var(--color-heading);

            @media #{$small-mobile} {
                font-size: var(--font-size-b4);
                line-height: 1;
            }
        }
    }

    .rbt-countdown-one {
        margin-top: 16px;

        @media #{$small-mobile} {
            margin-top: 8px;
        }

        .countdown {
            @media #{$small-mobile} {
                gap: 4px;
            }

            .countdown-container {
                @media #{$small-mobile} {
                    padding: 4px 8px;
                    width: 32px;
                }

                .countdown-value {
                    @media #{$sm-layout} {
                        font-size: 12px;
                    }
                }
            }
        }
    }

    .rbt-prd-qty-area {
        margin-top: 12px;

        @media #{$sm-layout} {
            margin-top: 8px;
        }
    }

    .prd-details-area {
        position: absolute;
        width: 100%;
        top: calc(100% - 16px);
        left: 0;
        height: auto;
        opacity: 0;
        visibility: hidden;
        padding: 16px;
        padding-top: 16px;
        clip: rect(0px, 200vw, 0, 0px);
        transform: translateZ(0);
        background: var(--color-white);
        border-radius: 0 0 10px 10px;
        border: 2px solid var(--color-gray-200);
        border-top: 0;
        z-index: 7;
        box-shadow: var(--shadow-product-item);
        transition: all 0.4s cubic-bezier(0, 0, 0.34, 0.54);

        @media #{$small-mobile} {
            padding: 4px;
            padding-top: 8px;
            top: calc(100% - 8px);
        }

        .wrapper {
            padding-top: 16px;
            border-top: 1px solid var(--color-border);
            padding-bottom: 16px;

            @media #{$small-mobile} {
                padding-top: 8px;
                padding-bottom: 8px;
            }
        }

        .product-details-list {
            margin: 0;
            padding: 0;
            padding-left: 26px;
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: 10px;

            @media #{$small-mobile} {
                padding-left: 8px;
                gap: 4px;
            }

            li {
                margin: 0;
                position: relative;
                font-size: var(--font-size-b3);
                line-height: var(--line-height-b3);
                color: var(--color-gray-500);

                @media #{$small-mobile} {
                    font-size: var(--font-size-b4);
                    line-height: 1;
                }

                &::before {
                    content: '';
                    position: absolute;
                    left: -15px;
                    top: 8px;
                    height: 4px;
                    width: 4px;
                    background: var(--color-heading);
                    border-radius: var(--radius-full);

                    @media #{$small-mobile} {
                        left: -8px;
                        top: 7px;
                        height: 3px;
                        width: 3px;
                    }
                }

                .rbt-bold--text {
                    color: var(--color-heading);
                }

                .text {
                    color: var(--color-gray-400);
                }

                .shipment-quick-link {
                    font-size: var(--font-size-b3);
                    list-style: var(--line-height-b3);
                    color: var(--color-primary);
                }
            }

            &.shipment-details-list {
                margin-top: 12px;
                padding: 0;

                li {
                    display: flex;

                    &::before {
                        display: none;
                    }

                    .icon {
                        margin: 0 8px;
                    }
                }
            }
        }
    }

    .rbt-show-more-btn-area::before {
        @media #{$sm-layout} {
            height: 60px !important;
        }
    }

    .product-hover-slider-list {
        display: flex;
        margin: 0;
        padding: 0;
        position: absolute;
        height: 100%;
        width: 100%;
        list-style: none;
        top: 0;
        left: 0;
        gap: 5px;
        overflow: hidden;

        li {
            flex-basis: 25%;
            margin: 0;
            margin: 0;

            a {
                display: block;
                height: 100%;
                border-bottom: 4px solid var(--color-gray-200);

                &:hover,
                &:active,
                &:focus,
                &.active {
                    border-color: var(--color-primary);
                }
            }
        }
    }

    .rbt-btn:hover {
        box-shadow: none;
    }

    .rbt-countdown-wrap {
        transition: opacity 0.4s ease, transform 0.6s cubic-bezier(0, 0, 0.34, 0.54);
    }

    &.has-hover-box-shadow {
        .inner {
            transition: all 0.6s cubic-bezier(0, 0, 0.34, 0.54);
        }

        &:hover {
            .inner {
                z-index: 5;
                position: relative;
                border-color: transparent;
                box-shadow: 0px 10px 60px 0px rgba(0, 0, 0, 0.14);
            }
        }
    }

    &:hover {
        .prd-details-area {
            height: auto;
            opacity: 1;
            visibility: visible;
            clip: rect(0px, 100vw, 200vh, -30px);
            border-color: transparent;
        }

        .rbt-card-img {
            img {
                transform: scale(1.04);
                border-radius: 16px;
            }
        }

        .rbt-countdown-wrap {
            transform: translateX(-50%) translateY(50%);
            opacity: 0;
        }
    }

    &.rbt-list-view-variation {
        height: 100%;

        .inner {
            display: flex;
            height: 100%;
            gap: 12px;
            border: 0;
            padding: 0;
            align-items: center;
            background: transparent;

            @media #{$small-mobile} {
                flex-wrap: wrap;
                flex-direction: column-reverse;
            }
        }

        .rbt-card-body {
            padding: 0;

            @media #{$sm-layout} {
                padding: 0 !important;
            }
        }

        &.rbt-list-view-sm {
            .inner {
                @media #{$small-mobile} {
                    flex-wrap: nowrap;
                    flex-direction: row;
                }
            }

            &+.rbt-list-view-sm {
                margin-top: 16px;
                padding-top: 16px;
                border-top: 1px solid var(--color-border);
            }

            .rbt-card-title {
                font-size: var(--font-size-b4);
                line-height: var(--line-height-b4);
                margin: 0;
                margin-top: 4px;
            }

            .rbt-rating-icon-list li i {
                font-size: var(--font-size-b4);
                line-height: var(--line-height-b4);
            }

            .pricing-part {
                font-size: var(--font-size-b3);
                line-height: var(--line-height-b3);
                margin-top: 4px;

                del {
                    font-size: var(--font-size-b4);
                    line-height: var(--line-height-b4);
                }
            }

            .rbt-card-img {
                border-radius: 8px;
                flex-basis: 51%;
                width: 100%;
            }

            .rbt-card-body {
                flex-basis: 49%;
                width: 100%;
            }

            .rbt-card-rating {
                margin-top: 0;
            }

            &.rbt-prd-sing-add-card {
                justify-content: space-between;

                .rbt-card-img {
                    flex-basis: 25%;
                }

                .rbt-card-body {
                    flex-basis: 75%;

                    &.rbt-card-body-sm-wider {
                        flex-basis: 66%;
                    }
                }

                .rbt-card-title {
                    font-size: var(--font-size-b3);
