                    }
                }
            }
        }

        &.transform-variation-two {

            overflow: unset;
            --footer-h-sm: 96px;

            .rbt-card-body {
                padding: 16px;
            }

            .rbt-card-img {
                img {
                    transform: scale(1);
                }
            }

            .card-inner {
                overflow: hidden;
                border-radius: 12px;
            }

            .background-expand {
                display: block;
                position: absolute;
                height: 100%;
                width: 100%;
                background-color: var(--color-white);
                border-radius: 12px;
                transition: transform .4s cubic-bezier(.2, .75, .5, 1);
                pointer-events: none;
                z-index: -1;

                &::before {
                    content: '';
                    position: absolute;
                    z-index: -2;
                    width: 100%;
                    height: 100%;
                    top: 0;
                    left: 0;
                    transform-origin: center;
                    background-color: transparent;
                    background-color: transparent;
                    opacity: 0;
                    border-radius: 12px;
                    box-shadow: var(--shadow-1);
                    transition: opacity .4s cubic-bezier(.2, .75, .5, 1);
                }
            }

            &:hover {
                .background-expand {
                    transform: scale(1.04, 1.04) translateY(0px) translateZ(0px);

                    &::before {
                        opacity: 1;
                        pointer-events: all;
                    }
                }

                .rbt-card-img {
                    img {
                        transform: scale(0.96);
                    }
                }
            }
        }

        &:hover {
            .rbt-card-img {
                img {
                    transform: scale(1);
                }
            }

            .product-hover-slider-list {
                height: calc(100% - (var(--footer-h-sm)));
            }

            .rbt-card-body {
                transform: translateY(calc(-1 * var(--footer-h-sm)));

                &.no-footer-body {
                    transform: none;
