@use "../../default/variables" as *; // Importing all the variables
@use "../../default/extend" as *; // Importing all the extend
@use "../../default/mixins" as *; // Importing all the mixins

/*---------------------------
    Header Common Styles  
----------------------------*/
.logo {
    a {
        display: block;

        img {
            max-height: 32px;
            object-fit: cover;
        }
    }
}


.rbt-header-top {
    position: relative;
}

.rbt-header-middle {
    position: relative;
}


/*-----------------------------
    Header Space Between  
------------------------------*/
.header-space-between {
    padding-left: 150px;
    padding-right: 150px;

    @media #{$extra-device} {
        padding-left: 50px;
        padding-right: 50px;
    }

    @media #{$laptop-device} {
        padding-left: 30px;
        padding-right: 30px;
    }

    @media #{$lg-layout} {
        padding-left: 15px;
        padding-right: 15px;
    }

    @media #{$md-layout} {
        padding-left: 15px;
        padding-right: 15px;
    }

    @media #{$sm-layout} {
        padding-left: 15px;
        padding-right: 15px;
    }

    @media #{$large-mobile} {
        padding-left: 0;
        padding-right: 0;
        padding-top: 0;
        padding-bottom: 0;
    }
}

/*----------------------------
    Header Top Information 
-----------------------------*/
.rbt-information-list {
    display: flex;
    flex-direction: row;
    align-items: center;
    padding-left: 0;
    list-style: none;
    margin: 0;
    flex-wrap: wrap;

    @media #{$large-mobile} {
        margin-top: 8px;
    }

    li {
        margin: 2px 7px;
        color: var(--color-body);

        a {
            padding: 0;
            font-size: 14px;
            line-height: 22px;
            color: var(--color-body);
            display: flex;
            align-items: center;
            transition: 0.4s;
            font-weight: 400;

            i {
                margin-right: 10px;
                font-size: 14px;
                margin-top: 2px;
            }

            span {
                margin-left: 4px;
            }

            &:hover {
                color: var(--color-primary);
            }
        }
    }
}



/*--------------------------
    Dropdown Menu  
----------------------------*/

.rbt-dropdown-menu-elastic {
    @extend %liststyle;
    position: relative;

    li {
        margin: 0;
        list-style: none;

        a {
            @extend %transition-4;
            font-size: var(--font-size-b3);
            line-height: var(--line-height-b3);
            font-weight: var(--f-medium);
            display: inline-block;
            color: var(--color-heading);
            position: relative;

            .left-image {
                width: 16px;
                height: 16px;
                border-radius: var(--radius-full);
                margin-right: 5px;
            }

            span {
                display: inline-block;
            }

            .right-icon {
                @extend %transition-4;
                display: inline-block;
                font-size: var(--font-size-b4);
                line-height: 1;
                margin-left: 4px;

                @media #{$large-mobile} {
                    font-size: 10px;
                }
            }
        }

        &.has-child-menu {
            display: flex;
            align-items: center;
            cursor: pointer;
            position: relative;
            min-height: 49px;

            @media #{$sm-layout} {
                min-height: 24px;
            }
        }

        .sub-menu {
            border-top: 1px solid #e6e3f14f;
            background: #fff;
            box-shadow: var(--shadow-3);
            padding: 10px 0;
            margin: 0;
            list-style-type: none;
            z-index: 10;
            text-align: center;
            border-radius: var(--radius);
            min-width: 150px;
            padding-top: 35px;
            top: 5px;
            right: auto;
            left: 50%;
            transform: translateX(-50%);
            clip-path: inset(0% 0% 100% 0% round 6px);
            transition: clip-path 0.6s var(--transition), background-color 0.6s var(--transition) !important;
            backdrop-filter: blur(5px);
            border: 1px solid var(--color-border);
            @extend %rbt-dropdown-type-1;

            li {
                a {
                    margin: 2px 10px;
                    padding: 4px 12px;
                    background: transparent;
                    border-radius: var(--radius);
                    display: flex;
                    align-items: center;
                    justify-content: start;
                    font-size: var(--font-size-b3);
                    line-height: var(--line-height-b3);
                    font-weight: 400;
                    @extend %transition-4;

                    &:hover,
                    &.active {
                        color: var(--color-white);
                        background: var(--color-primary);
                    }
                }
            }
        }

        &.active-on-hover {
            &:hover {
                >a {
                    z-index: 25;

                    .right-icon {
                        transform: rotate(180deg);
                        margin-top: 2px;
                    }
                }

                .sub-menu {
                    @extend %rbt-hover-dropdown-type-1;
                    top: 5px;
                    background-color: rgb(255 255 255 / 80%);
                    clip-path: inset(-50% -50% -50% -50% round 6px);
                }
            }
        }

        &.active {
            >a {
                z-index: 25;

                .right-icon {
                    transform: rotate(180deg);
                    margin-top: 2px;
                }
            }

            .sub-menu {
                @extend %rbt-hover-dropdown-type-1;
                top: 5px;
                background-color: rgb(255 255 255 / 80%);
                clip-path: inset(-50% -50% -50% -50% round 6px);
            }
        }
    }
}

.rbt-header-common-sticky-activation {
    .rbt-mainmenu-nav .mainmenu>li>a {
        height: 80px;
        line-height: 80px;
    }
}

header {
    .rbt-round-btn {
        &::after {
            transform: scale(1);
        }

        &:hover {
            &::after {
                transform: scale(1.1);
            }
        }
    }
}

.rbt-bg-color-primary {
    .rbt-dropdown-menu li {
        a {
            color: var(--color-white) !important;

            &:hover {
                color: var(--color-white);
            }
        }

        &:hover {
            a {
                color: var(--color-white);
            }
        }

        .sub-menu li a {
            color: var(--color-primary) !important;

            &:hover {
                background-color: var(--color-brand-200) !important;
            }

            &.active {
                color: var(--color-white) !important;

                &:hover {
                    background-color: var(--color-primary) !important;
                }
            }
        }
    }

    .rbt-quick-access>li>.rbt-round-btn {
        color: var(--color-white) !important;
        background: transparent !important;

        &::after {
            background: rgba(255, 255, 255, 0.15) !important;
            transform: scale(1);
        }

        &:hover {
            &::after {
                transform: scale(1.1);
            }
        }
    }

    .rbt-round-btn.rbt-bg-static-gray {
        color: var(--color-white) !important;
        background: transparent !important;
    }

    .rbt-round-btn::after {
        background: rgba(255, 255, 255, 0.15) !important;
    }

    .rbt-quick-access>li:hover>.rbt-round-btn {
        color: var(--color-brand-300);
    }

    .rbt-access-box .content p,
    .rbt-access-box .content span {
        color: var(--color-brand-300);
    }

    .rbt-access-box .content a {
        color: var(--color-white);
    }

    .rbt-access-box .content a:hover {
        color: var(--color-brand-300);
    }

    .rbt-access-box.rbt-access-box-has-bg-hover .rbt-access-box-wrapper::before {
        background: rgba(255, 255, 255, 0.15) !important;
    }
}

.rbt-bg-color-gray-light,
.rbt-bg-color-white {

    .rbt-quick-access>li.rbt-contract-info .text-portion,
    .rbt-quick-access>li.rbt-contract-info .text-portion p,
    .rbt-quick-access>li.rbt-contract-info .link-portion {
        color: var(--color-black);
    }

    .rbt-quick-access>li.rbt-contract-info .link-portion {
        background: var(--color-gray-100);
    }
}

/*--------------------------
    Header Section
----------------------------*/

.rbt-header-sec {
    display: flex;

    @media #{$lgtolp-device} {
        height: 100%;
    }

    @media #{$lg-layout} {
        height: 100%;
    }

    .rbt-header-sec-col {
        flex-basis: 0;
        flex-grow: 1;
        max-width: 100%;

        .rbt-header-content {
            display: flex;
            align-items: center;
        }
    }

    .rbt-header-left {
        text-align: left;

        .rbt-header-content {
            justify-content: flex-start;
        }
    }

    .rbt-header-right {
        text-align: right;

        .rbt-header-content {
            justify-content: flex-end;
        }
    }

    .rbt-header-center {
        text-align: center;

        .rbt-header-content {
            justify-content: center;
        }
    }

    &.flex-row-reverse {
        .rbt-header-left {
            text-align: right;

            .rbt-header-content {
                justify-content: flex-end;
            }
        }

        .rbt-header-right {
            text-align: left;

            .rbt-header-content {
                justify-content: flex-start;
            }
        }
    }

}

.rbt-header-wrapper {
    .rbt-header-content {
        display: flex;
        align-items: center;
    }
}


/*--------------------------
    Header Quick Access
----------------------------*/

.rbt-quick-access {
    display: flex;
    align-items: center;
    padding: 0;
    gap: 16px;
    margin: 0;

    @media #{$smlg-device} {
        gap: 12px;
    }

    @media #{$small-mobile} {
        gap: 8px;
    }

    &.has-bigger-gap {
        gap: 24px;
    }

    &.has-smaller-gap {
        gap: 8px;
    }

    >li {
        margin: 0;
        display: flex;
        align-items: center;

        >a,
        >button {
            color: var(--color-heading);
            font-size: 14px;
            font-weight: var(--f-medium);
            transition: var(--transition);

        }

        .has-rbt-md-fsize {
            font-size: 18px;

            @media #{$smlg-device} {
                font-size: var(--font-size-b2);
            }
        }

        &.rbt-access-box {
            .rbt-round-btn {
                position: relative;
                z-index: 1;
                height: 36px;
                width: 36px;
                line-height: 36px;
                color: var(--color-heading);

                &.has-rbt-bg-black {
                    background: var(--color-black);
                    color: var(--color-white);
                }

                @media #{$small-mobile} {
                    height: 32px;
                    width: 32px;
                    line-height: 32px;
                }

                i {
                    margin-right: 0;
                }
            }

            &.rbt-access-box-var-light-white {
                .header-info+.header-info {
                    &::before {
                        background: rgba(255, 255, 255, 0.3) !important;
                    }
                }

                .rbt-dropdown-menu li .sub-menu li a {
                    color: var(--color-primary) !important;

                    &.active,
                    &.hover {
                        color: var(--color-white) !important;
                        background: var(--color-primary);
                    }
                }

                .rbt-dropdown-menu-elastic li.has-child-menu {
                    &:hover {
                        a {
                            color: var(--color-primary) !important;
                        }
                    }
                }
            }
        }

        &.rbt-contract-info {
            display: flex;
            gap: 12px;

            .text-portion {
                display: flex;
                align-items: center;
                gap: 4px;
                font-size: var(--font-size-b3);
                line-height: var(--line-height-b3);
                color: var(--color-white);
                font-weight: var(--f-medium);

                @media #{$laptop-device} {
                    font-size: var(--font-size-b4);
                    line-height: var(--line-height-b4);
                }

                p {
                    font-size: var(--font-size-b3);
                    line-height: var(--line-height-b3);
                    color: var(--color-white);

                    @media #{$laptop-device} {
                        font-size: var(--font-size-b4);
                        line-height: var(--line-height-b4);
                    }
                }

                i {
                    margin-top: 2px;
                }
            }

            .link-portion {
                padding: 4px 16px;
                border-radius: 40px;
                background: rgba(255, 255, 255, 0.15);
                color: var(--color-white);
                font-weight: 600;
                font-size: var(--font-size-b3);
                line-height: var(--line-height-b3);

                @media #{$laptop-device} {
                    font-size: var(--font-size-b4);
                    line-height: var(--line-height-b4);
                }

                &:hover {
                    background: rgba(255, 255, 255, 0.25);
                }
            }
        }

        .header-info+.header-info {
            margin-left: 41px;
            position: relative;

            &::before {
                content: '';
                position: absolute;
                top: 50%;
                left: -20px;
                transform: translateY(-50%);
                height: 16px;
                width: 1px;
                background: var(--color-gray-200);

                @media #{$laptop-device,$lg-layout} {
                    left: -8px;
                }

            }

            @media #{$laptop-device,$smlg-device} {
                margin-left: 16px !important;
            }
        }

        &.without-separator {
            .header-info+.header-info {
                margin-left: 32px;

                &::before {
                    display: none;
                }
            }
        }

        &.rbt-access-box-link {
            >a {
                display: flex;
                gap: 8px;
                font-size: var(--font-size-b1);
                line-height: var(--line-height-b1);
                align-items: center;
                color: var(--color-white);
                font-weight: var(--f-medium);

                i {
                    line-height: 24px;
                    font-size: var(--font-size-b2);
                }
            }
        }

        &:hover {
            .rbt-round-btn {
                &::before {
                    scale: 1;
                    opacity: 1;
                    visibility: visible;
                }
            }
        }
    }
}

.rbt-access-box-link {
    .header-info:hover {

        span,
        i {
            color: #FFF503;
        }
    }
}


.rbt-bg-color-primary .rbt-quick-access {
    &.rbt-quick-access-var-one {
        >li>a {
            background: transparent;
        }

        >li:hover>a {
            color: var(--color-white);
        }
    }
}

.rbt-access-box {
    &.rbt-access-box-has-bg-hover {
        .rbt-access-box-wrapper {
            cursor: pointer;
            background: none;
            position: relative;
            z-index: 1;

            @media #{$smlg-device} {
                padding: 0;
            }

            &::before {
                content: '';
                position: absolute;
                top: 50%;
                left: 50%;
                transform: translate(-50%, -50%) scale(1);
                height: 100%;
                width: 100%;
                background: var(--color-gray-100);
                transition: var(--transition);
                border-radius: 60px;
                opacity: 0;
                visibility: hidden;
                z-index: -1;
            }

            &:hover {
                &::before {
                    transform: translate(-50%, -50%);
                    height: calc(100% + 16px);
                    // left: calc(50% - 8px);
                    width: calc(100% + 16px);
                    // top: calc(50% - 8px);
                    opacity: 1;
                    visibility: visible;
                }
            }
        }

        &.rbt-access-box-has-bg-hover-white {
            .rbt-access-box-wrapper {
                &::before {
                    background: var(--color-white);
                }
            }
        }
    }
}



/*--------------------------
    Search With Category
----------------------------*/

.rbt-search-with-category {
    select {
        height: 100%;
        border: 0 none;
        width: 170px;
        font-size: 14px;
        font-weight: var(--f-medium);
        background-color: transparent;
        padding: 3px 20px;
    }

    .search-by-category {
        height: 100%;
        position: relative;
        flex: 1 1 0px;
    }

    .rbt-inner-search-field {
        width: 80%;
    }
}

.rbt-search-field,
.rbt-search-with-category,
.rbt-inner-search-field {
    display: flex;
    align-items: center;
    border: 0;
    height: 38px;
    border-radius: 500px;

    &.style-one {
        max-width: 722px;
        width: 100%;

        @media #{$laptop-device} {
            max-width: 500px;
        }

        @media #{$lg-layout} {
            max-width: 500px;
        }

        @media #{$md-layout} {
            max-width: 400px;
        }

        @media #{$sm-layout} {
            max-width: 280px;
        }

        &.rbt-search-field-rounded {
            input {
                border-radius: 60px;
            }
        }
    }

    .rbt-modern-select {
        .bootstrap-select {
            button {
                &.btn-light {
                    border: 0 none;
                    box-shadow: none;
                    height: inherit;
                    padding: 10px 20px;
                    border-radius: inherit;
                    line-height: 23px;
                    padding-right: 40px;
                    background-color: transparent;
                    border-right: 2px solid var(--color-gray-200);
                }
            }

            .dropdown-menu {
                max-width: 200px;
                width: 200px;
            }
        }
    }

    .rbt-inner-search-field {
        .search-btn {
            &::after {
                display: none;
            }
        }
    }

    &.uni-header-swc-one {
        border: 0;
        height: auto;
        border-radius: unset;

        @media #{$sm-layout} {
            display: none;
        }

        .rbt-inner-search-field {
            gap: 12px;
            width: 100%;

            .search-btn {
                position: unset;
                transform: none;
                height: 42px;
                width: auto;
                padding: 0 24px;
                border-radius: var(--radius);
                background: var(--color-black);
                color: var(--color-gray-300);
                font-size: var(--font-size-b1);

                i {
                    transition: var(--transition);
                    transform: scale(0.9);
                }

                &:hover {
                    i {
                        color: var(--color-white);
                        transform: scale(1);
                    }
                }
            }

            input {
                width: 100%;
                min-width: 448px;

                @media #{$extra-device} {
                    min-width: 387px;
                }

                @media #{$laptop-device} {
                    min-width: 350px;
                }
            }

            .search-by-category {
                position: absolute;
            }

            .rbt-search-input-section {
                position: relative;
                background: var(--color-white);
                border: 2px solid var(--color-gray-200);
                border-radius: var(--radius);

                .bootstrap-select:not([class*=col-]):not([class*=form-control]):not(.input-group-btn) {
                    width: 140px;
                    max-width: 140px;
                }

                .search-by-category::after {
                    background: var(--color-gray-200);
                    width: 2px;
                    height: 100%;
                }

                .rbt-modern-select .bootstrap-select button.btn-light {
                    padding: 0 16px;
                    padding-right: 32px;
                    color: var(--color-heading);
                    font-weight: var(--f-medium);
                    font-size: var(--font-size-b3);
                    line-height: 38px;
                }

                .dropdown-menu {
                    .form-control {
                        min-width: unset;
                        padding-left: 8px;
                        padding-right: 8px;
                    }
                }

                &.has-left-catagory-section {
                    input {
                        padding-left: 156px;
                        padding-right: 16px;
                    }

                    .search-by-category {
                        top: 0;
                        left: 0;
                    }
                }

                &.has-right-catagory-section {
                    input {
                        padding-right: 156px;
                        padding-left: 16px;
                    }

                    .search-by-category {
                        top: 0;
                        right: 0;
                        left: unset;
                    }

                    .cd-headline {
                        left: 16px;
                    }

                    .search-by-category {
                        &::after {
                            right: unset;
                            left: 0;
                        }
                    }

                    .bootstrap-select button.btn-light {
                        border-right: 0;
                        border-left: 2px solid var(--color-gray-200);
                    }
                }

            }
        }

        input {
            border: 0;
        }

        &.uni-header-swc-lg {
            input {
                width: 100%;
                max-width: 667px;

                @media #{$extra-lg-device} {
                    min-width: 667px;
                }
            }
        }

        &.uni-header-swc-md {
            input {
                width: 100%;
                max-width: 492px;

                @media #{$extra-lg-device} {
                    min-width: 492px;
                }
            }
        }

        &.uni-header-swc-xl {
            input {
                width: 100%;
                max-width: 970px;
                min-width: 640px !important;

                @media screen and (min-width: 1200px) and (max-width: 1399px) {
                    min-width: 300px !important;
                }

                @media screen and (min-width: 1400px) and (max-width: 1919px) {
                    min-width: 640px !important;
                }
            }
        }
    }
}

.rbt-inner-search-field {
    input {
        height: 38px;
        box-shadow: none;
        padding: 0 24px;
        padding-right: 65px;
        line-height: 38px;
    }

    &.filed-solid {
        input {
            background: var(--color-gray-light);
