@use "../default/variables" as *; // Importing all the variables
@use "../default/extend" as *; // Importing all the extend
@use "../default/mixins" as *; // Importing all the mixins

/*===================
Button Area 
====================*/
.rbt-button-group {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    align-items: center;
    margin: -10px;

    a,
    button {
        margin: 10px;
    }
}

.disabled,
.rbt-btn:disabled,
fieldset:disabled {
    pointer-events: none;
    opacity: .65;
    background: var(--color-gray-300) !important;

    &.rbt-btn-border {
        background: transparent !important;
        border: 2px solid var(--color-gray-300) !important;
        color: var(--color-gray-400) !important;
        line-height: 47px;

        @media #{$sm-layout, $md-layout} {
            line-height: 38px;
        }

        @media #{$small-mobile} {
            line-height: 28px;
        }
    }
}

.rbt-btn {
    padding: 0 40px;
    background: var(--color-primary);
    height: 50px;
    line-height: 50px;
    color: var(--color-white);
    font-size: 18px;
    font-weight: 600;
    display: inline-block;
    position: relative;
    transition: var(--transition);
    border-radius: var(--radius-60);
    border: 0 none;
    outline: none;
    white-space: nowrap;

    @media #{$md-layout} {
        padding: 0 24px;
        font-size: 15px;
        height: 40px;
        line-height: 40px;

        i {
            font-size: 14px;
        }
    }

    @media #{$sm-layout} {
        padding: 0 24px;
        font-size: 15px;
        height: 40px;
        line-height: 40px;

        i {
            font-size: 14px;
        }
    }

    @media #{$small-mobile} {
        padding: 0 12px;
        font-size: 12px;
        height: 32px;
        line-height: 32px;

        i {
            font-size: 12px !important;
        }
    }

    // Color Varient 
    &.rbt-btn-secondary {
        background: var(--color-brand-200);
        color: var(--color-primary);

        &:hover,
        &:focus {
            color: var(--color-white);
            box-shadow: none;
            background-color: var(--color-primary);
        }
    }

    &.rbt-btn-secondary-alt {
        background: var(--color-extra-twelve);
        color: var(--color-secondary);

        &:hover,
        &:focus {
            color: var(--color-white);
            box-shadow: none;
            background-color: var(--color-secondary);
        }
    }

    &.rbt-btn-black {
        background: var(--color-black);
        color: var(--color-white) !important;

        &:hover {
            color: var(--color-black);
            box-shadow: none;
        }
    }

    &.rbt-btn-gray {
        background: var(--color-brand-50);
        color: var(--color-heading);

        &:hover {
            background: var(--color-primary);
            color: var(--color-white);
        }
    }

    &.rbt-btn-gray-light {
        background: var(--color-gray-200);
        color: var(--color-gray-500);

        &:hover,
        &:focus {
            background: var(--color-black);
            color: var(--color-white);
            box-shadow: none;
        }
    }

    &.rbt-btn-white {
        background: var(--color-white);
        color: var(--color-heading);

        &:hover {
            background: var(--color-primary);
            color: var(--color-white);
        }
    }

    &.btn-bg-white-opacity {
        background: rgba(255, 255, 255, 0.2);
        color: var(--color-white);

        &:hover {
            background: var(--color-primary);
            color: var(--color-white);
        }
    }

    &.rbt-btn-naked {
        background: transparent;
        color: var(--color-heading);

        &:hover,
        &:focus {
            color: var(--color-white);
            background: var(--color-black);
            box-shadow: none;
        }
    }

    // Border Varient 
    &.rbt-btn-border {
        background: transparent;
        border: 2px solid var(--color-primary);
        color: var(--color-heading);
        line-height: 47px;

        @media #{$sm-layout, $md-layout} {
            line-height: 38px;
        }

        @media #{$small-mobile} {
            line-height: 28px;
        }

        &:hover,
        &:focus,
        &.active {
            background: var(--color-primary);
            border-color: var(--color-primary);
            color: var(--color-white);
        }

        &.color-two {
            border-color: var(--color-brand-500);

            &:hover,
            &:focus {
                border-color: var(--color-primary);
            }
        }

        &.color-dark {
            border-color: var(--color-black);

            &:hover,
            &:focus {
                border-color: var(--color-black);
                background: var(--color-black);
            }
        }

        &.rbt-btn-xs {
            line-height: 28px;
        }

        &.rbt-btn-sm {
            line-height: 32px;

            @media #{$small-mobile} {
                line-height: 27px;
            }
        }

        &.rbt-btn-md {
            line-height: 36px;

            @media #{$sm-layout} {
                line-height: 26px;
            }
        }

        &.rbt-btn-gray-light {
            border-color: var(--color-gray-200);
            color: var(--color-gray-500);

            &:hover,
            &:active,
            &:focus {
                background: var(--color-gray-500);
                border-color: var(--color-gray-500);
                color: var(--color-white);
            }
        }

        &.rbt-btn-border-black {
            border-color: var(--color-black);

            &:hover,
            &:active,
            &:focus {
                background: var(--color-black);
            }
        }

        &.rbt-btn-border-white {
            border-color: var(--color-white);
            background: transparent;
            color: var(--color-white);

            &:hover,
            &:active,
            &:focus {
                background: var(--color-primary);
                border-color: var(--color-primary);
                color: var(--color-black);
            }
        }
    }

    // Radius Varient 
    &.radius-round-6 {
        border-radius: var(--radius);
    }

    &.radius-round-10 {
        border-radius: 10px;
    }

    &.rbt-bg-color-secondary {
        &:hover {
            box-shadow: none;
        }
    }

    &:hover,
    &:focus {
        transform: translateY(-2px);
        box-shadow: var(--shadow-7);
        color: var(--color-white);
        background: var(--color-primary);

        &.icon-hover {
            .btn-text {
                transform: translateX(-5px);
            }

            .btn-icon {
                i {
                    opacity: 1;
                    transform: translateX(5px);
                }
            }
        }

        // Icon Reverse Btn
        &.hover-icon-reverse {
            .btn-text {
                transition-delay: 0.1s;
                transform: translateX(23px);
            }

            .btn-icon {
                opacity: 0;
                transition-delay: 0s;
                transform: translateX(10px);

                &+.btn-icon {
                    opacity: 1;
                    transform: translateX(0);
                    transition-delay: 0.225s;
                }
            }
        }

        &.has-no-hover-transform {
            transform: translateY(0);
        }

    }

    &:active {
        transform: translateY(0);

        &.icon-hover {
            .btn-text {
                transform: translateX(0);
            }

            .btn-icon {
                i {
                    opacity: 1;
                    transform: translateX(0);
                }
            }
        }

        // Icon Reverse Btn
        &.hover-icon-reverse {
            .btn-text {
                transition-delay: 0.1s;
                transform: translateX(0);
            }

            .btn-icon {
                opacity: 0;
                transition-delay: 0s;
                transform: translateX(0);

                &+.btn-icon {
                    opacity: 1;
                    transform: translateX(0);
                    transition-delay: 0.225s;
                }
            }
        }

    }


    // Rounded Video Player Button
    &.rounded-player {
        border-radius: var(--radius-full);
        width: 100px;
        height: 100px;
        padding: 0;
        line-height: 100px;
        display: inline-block;
        position: relative;
        z-index: 1;

        @media #{$md-layout} {
            width: 80px;
            height: 80px;
            line-height: 80px;
        }

        @media #{$sm-layout} {
            width: 70px;
            height: 70px;
            line-height: 70px;
        }

        span {
            display: inline-block;

            i {
                display: inline-block;
                position: absolute;
                left: 50%;
                top: 50%;
                transform: translate(-50%, -50%);
                font-size: 30px !important;

                @media #{$sm-layout} {
                    font-size: 20px;
                }
            }
        }

        &.bg-var-two {
            background: rgba(33, 90, 218, 0.10);
            color: var(--color-primary);

            &:hover,
            &:active {
                background-color: var(--color-primary);
                color: var(--color-white) !important;
            }
        }

        &.bg-var-three {
            background: rgba(255, 255, 255, 0.30);
            color: var(--color-white);

            &:hover,
            &:active {
                background-color: var(--color-primary);
                color: var(--color-white) !important;
            }
        }

        &.border {
            background-image: inherit;
            border-color: var(--color-white) !important;
            border-width: 2px !important;

            &:hover {
                background-color: var(--color-primary);
                border-color: var(--color-primary) !important;
            }
        }

        &.xl-size {
            width: 120px;
            height: 120px;
            line-height: 120px;

            span {
                i {
                    font-size: 30px !important;
                }
            }

            @media #{$md-layout} {
                width: 80px;
                height: 80px;
                line-height: 80px;
            }

            @media #{$sm-layout} {
                width: 70px;
                height: 70px;
                line-height: 70px;
            }
        }

        &.md-size {
            width: 80px;
            height: 80px;
            line-height: 80px;

            span {
                i {
                    font-size: 30px !important;
                }
            }
        }

        &.sm-size {
            width: 70px;
            height: 70px;
            line-height: 70px;
        }

        &.xs-size {
            width: 64px;
            height: 64px;
            line-height: 64px;

            span {
                i {
                    font-size: 26px !important;
                }
            }
        }

        &.position-center-center {
            top: 50%;
            left: 50%;
            position: absolute;
            transform: translate(-50%, -50%);
            top: 50%;
            left: 50%;
        }

        &:focus {
            outline: none;
            color: var(--color-white);
        }

        &:hover {
            transform: scale(1.1);
            background: var(--color-primary);
        }
    }


    // Marquee 
    &.rbt-marquee-btn {
        overflow: hidden;
        position: relative;
        max-width: 260px;

        &::after,
        &::before {
            content: "";
            position: absolute;
            top: 0;
            height: 100%;
            z-index: 2;
            width: 30px;
            opacity: 1;
            visibility: visible;
            transition: 0.3s;
        }

        &::after {
            right: -2px;
            background: linear-gradient(90deg, rgba(255, 255, 255, 0.1) 0%, rgba(255, 255, 255, 0.9) 45.02%, #FFF 86.62%);
        }

        &::before {
            left: -2px;
            background: linear-gradient(270deg, rgba(255, 255, 255, 0.1) 0%, rgba(255, 255, 255, 0.9) 45.02%, #FFF 86.62%);
        }

        &.has-primary-overlay {
            &::after {
                right: -2px;
                background: linear-gradient(90deg, rgb(33 90 218 / 18%) 0%, rgb(33 90 218 / 97%) 45.02%, #215ada 86.62%);
            }

            &::before {
                left: -2px;
                background: linear-gradient(270deg, rgb(33 90 218 / 18%) 0%, rgb(33 90 218 / 97%) 45.02%, #215ada 86.62%);
            }
        }

        span {
            display: inline-flex;
            position: relative;
            z-index: 1;
            line-height: 1.2;

            &::after {
                content: attr(data-text);
                position: absolute;
                white-space: nowrap;
                top: 50%;
                left: 100%;
                transform: translate(15%, -50%);
            }
        }

        &.no-white-overlay {

            &::after,
            &::before {
                display: none;
            }
        }

        &:hover {

            &::after,
            &::before {
                opacity: 0;
                visibility: hidden;
            }
        }

        &.marquee-text-y {
            span {
                &::after {
                    top: 100%;
                    left: 50%;
                    transform: translate(-50%, 100%);
                }
            }
        }

        &.marquee-auto {
            span {
                animation: btnTxtMarqueeX 5s linear infinite;
            }
        }
    }


    // Size Variation

    &.rbt-btn-sm {
        padding: 0 32px;
        font-size: var(--font-size-b3);
        height: 36px;
        line-height: 36px;

        i {
            font-size: var(--font-size-b3);
        }

        @media #{$sm-layout} {
            padding: 0 16px;
        }

        @media #{$small-mobile} {
            font-size: var(--font-size-b4);
            padding: 0 8px;
            height: 30px;
            line-height: 30px;
        }

    }

    &.rbt-btn-sm-2 {
        padding: 0 18px;
        font-size: var(--font-size-b3);
        height: 36px;
        line-height: 36px;

        i {
            font-size: var(--font-size-b3);
        }

        @media #{$sm-layout} {
            padding: 0 12px;
            font-size: var(--font-size-b4);
            height: 28px;
            line-height: 28px;
        }
    }

    &.rbt-btn-xs {
        padding: 0 16px;
        font-size: var(--font-size-b3);
        height: 32px;
        line-height: 32px;

        i {
            font-size: var(--font-size-b3);
        }
    }

    &.rbt-btn-md {
        padding: 0 32px;
        font-size: var(--font-size-b1);
        height: 40px;
        line-height: 40px;

        i {
            font-size: var(--font-size-b3);
        }

        @media #{$sm-layout} {
            padding: 0 12px;
            font-size: var(--font-size-b4);
            height: 28px;
            line-height: 27px;
        }

        @media #{$small-mobile} {
            font-size: 13px;
        }
    }

    i {
        display: inline-block;
        position: relative;
        font-size: 17px;

        &.image-icon {
            top: inherit;
            transition: 0.4s;
        }
    }

    &.btn-border-gradient {
        background: linear-gradient(90deg, #CFA2E8, #637FEA);
        border: none;
        outline: none;
        cursor: pointer;
        position: relative;
        z-index: 10;
        color: var(--color-heading);
        box-shadow: 0 10px 13px 0 rgba(209, 211, 237, 0.39);
        border-radius: 0;

        &::before {
            content: '';
            z-index: -1;
            top: 3px;
            left: 3px;
            position: absolute;
            background: #fff;
            width: calc(100% - 6px);
            height: calc(100% - 6px);
        }

        &.radius-round {
            border-radius: 500px;

            &::before {
                border-radius: 500px;
            }
        }
    }

    &.rbt-btn-gradient-red {
        background: linear-gradient(90deg, #D50000 0%, #F00 5.79%, #FF8E6B 12.11%, #F00 19.47%, #F00 37.89%, #E90000 58.42%, #540001 100%), #D8DA67;

        &:hover {
            box-shadow: none;
        }
    }

    &.hover-transform-none {
        &:hover {
            transform: none;
        }
    }

    // Round Icon
    &.rbt-btn-round {
        border-radius: var(--radius-full);
        height: 100px;
        width: auto;
        display: flex;
        text-align: center;
        gap: 4px;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        padding: 5px 15px;
        font-size: var(--font-size-b3);
        line-height: var(--line-height-b3);
        white-space: unset;
        max-width: max-content;
        min-width: 100px;

        @media #{$large-mobile} {
            height: 80px;
            min-width: 80px;
            font-size: 12px;
            line-height: 12px;
        }
    }

    &.rbt-full-square-btn {
        border-radius: var(--radius-0);
    }

    // Icon Hover
    &.icon-hover {
        .btn-text {
            transition-timing-function: cubic-bezier(0, 0.71, 0.4, 1);
            display: inline-block;
            transition: transform 0.5s;
            transform: translateX(5px);
        }

        .btn-icon {
            margin-inline-start: -5px;
            display: inline-block;

            i {
                transition-timing-function: cubic-bezier(0, 0.71, 0.4, 1);
                display: inline-block;
                opacity: 0;
                transform: translateX(-5px);
                transition: opacity 0.25s, transform 0.5s;
                padding-left: 0;
            }
        }

        &.icon-hover-left {

            .btn-text {
                transform: translateX(-5px);
            }

            .btn-icon {
                margin-inline-start: 0;
                margin-inline-end: -5px;

                i {
                    transform: translateX(5px);
                }
            }

            &:hover {
                .btn-icon {
                    i {
                        transform: translateX(-5px);
                    }
                }

                .btn-text {
                    transform: translateX(5px);
                }
            }
        }
    }


}



/*-------------------------------
    Button Bg Color Variation 
--------------------------------*/



a,
button {
    &.bg-primary-opacity {
        &:hover {
            background: var(--color-primary);
            color: var(--color-white);
        }
    }

    &.bg-white {
        background: var(--color-white);
        color: var(--color-heading);

        &:hover {
            background: var(--color-black) !important;
            color: var(--color-white) !important;
            box-shadow: none;
        }
    }
}










/*----------------------------------
    E-commerce Transparent Button 
------------------------------------*/
a,
button,
span {
    &.rbt-btn-link {
        color: var(--color-heading);
        position: relative;
        transition: var(--transition);
        font-size: var(--font-size-b1);
        font-weight: var(--f-medium);
        display: inline-block;

        i {
            position: relative;
            top: 1px;
            display: inline-block;
            padding-left: 4px;
        }

        &::after {
            position: absolute;
            content: "";
            left: auto;
            bottom: 0;
            background: currentColor;
            width: 0;
            height: 2px;
            transition: var(--transition);
            right: 0;
        }

        &:hover {
            color: var(--color-primary) !important;

            &::after {
                width: 100%;
                left: 0;
                right: auto;
            }
        }

        &.left-icon {
            i {
                padding-left: 0;
                padding-right: 4px;
            }
        }

        &.color-white {
            &:hover {
                color: var(--color-white) !important;
            }
        }

        &.b4 {
            font-size: var(--font-size-b4);
            line-height: var(--line-height-b4);
        }

    }

    &.transparent-button {
        color: var(--color-heading);
        position: relative;
        transition: var(--transition);
        font-size: 14px;
        font-weight: var(--f-medium);

        i {
            display: inline-block;
            padding-left: 4px;
            transition: 0.4s;
        }

        &:hover {
            i {
                padding-left: 10px;
            }
        }
    }
}


/*-----------------------
 Video Player Button 
-------------------------*/
.video-popup-wrapper {
    position: relative;

    .position-to-top {
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        margin: 0;
        cursor: pointer;
        z-index: 2;
    }

    .rbt-btn {
        &.rounded-player {
            &:hover {
                transform: translate(-50%, -50%) scale(1.1);
            }
        }
    }
}



.rbt-btn,
a,
button {
    transition: all 0.4s cubic-bezier(0, 0, 0.34, 0.54);

    .animated-icon {
        svg {
            width: 16px;

            @media #{$sm-layout} {
                width: 12px;
            }

            path {
                fill: var(--color-primary);
                transition: opacity 0.4s ease, transform 0.4s cubic-bezier(0, 0, 0.34, 0.54);
            }

            .icon-arrow-line-two,
            .icon-arrow-el-two {
                opacity: 0;
                visibility: hidden;
                transform: translate(-10px, 10px);
                transition: opacity 0.4s ease, transform 0.4s cubic-bezier(0, 0, 0.34, 0.54);
            }

            .icon-arrow-line-one,
            .icon-arrow-el-one {
                transform: translate(0, 0);
                opacity: 1;
                visibility: visible;
                transition: opacity 0.4s ease, transform 0.4s cubic-bezier(0, 0, 0.34, 0.54);
            }
        }
    }

    &:hover {
        .animated-icon {
            svg {
                width: 16px;

                @media #{$sm-layout} {
                    width: 12px;
                }

                path {
                    fill: var(--color-white) !important;
                }

                .icon-arrow-line-one,
                .icon-arrow-el-one {
                    transform: translate(10px, -10px);
                    opacity: 0;
                    visibility: hidden;
                }

                .icon-arrow-line-two,
                .icon-arrow-el-two {
                    opacity: 1;
                    visibility: visible;
                    transform: translate(0, 0);
                }
            }
        }
    }

    &.animated-icon-btn {
        &.defalt-secondary-bg {
            background: transparent;
            color: var(--color-primary);
            position: relative;

            &::after {
                content: "";
                position: absolute;
                top: 50%;
                left: 50%;
                transform: translate(-50%, -50%) scale(1);
                height: 100%;
                width: 100%;
                background-color: var(--color-brand-200);
                z-index: -1;
                border-radius: 60px;
                transition: opacity 0.4s ease, transform 0.4s cubic-bezier(0, 0, 0.34, 0.54);
            }

            .animated-icon {
                svg {
                    path {
                        fill: var(--color-primary);
                    }
                }
            }

            &:hover {
                background: transparent !important;
                color: var(--color-primary);

                .animated-icon {
                    svg {
                        path {
                            fill: var(--color-primary) !important;
                        }
                    }
                }

                &::after {
                    transform: translate(-50%, -50%) scale(1.1);
                }
            }
        }

        &.defalt-primary-bg {
            background: transparent;
            color: var(--color-white);
            position: relative;

            &::after {
                content: "";
                position: absolute;
                top: 50%;
                left: 50%;
                transform: translate(-50%, -50%) scale(1);
                height: 100%;
                width: 100%;
                background-color: var(--color-primary);
                z-index: -1;
                border-radius: 60px;
                transition: opacity 0.4s ease, transform 0.4s cubic-bezier(0, 0, 0.34, 0.54);
            }

            .animated-icon {
                svg {
                    path {
                        fill: var(--color-white);
                    }
                }
            }

            &:hover {
                background: transparent !important;
                color: var(--color-white);

                .animated-icon {
                    svg {
                        path {
                            fill: var(--color-white) !important;
                        }
                    }
                }

                &::after {
                    transform: translate(-50%, -50%) scale(1.1);
                }
            }
        }

        &.round-sm {
            height: 40px;
            width: 40px;
            display: flex;
            justify-content: center;
            align-items: center;

            @media #{$sm-layout} {
                height: 28px;
                width: 28px;
                min-width: none;
            }

            &::after {
                content: "";
                position: absolute;
                top: 50%;
                left: 50%;
                transform: translate(-50%, -50%) scale(1);
                height: 100%;
                width: 100%;
                background-color: var(--color-primary);
                z-index: -1;
                border-radius: 50%;
                transition: opacity 0.4s ease, transform 0.4s cubic-bezier(0, 0, 0.34, 0.54);
            }
        }
    }
}

/*-----------------------
 Card Link Button CSS
-------------------------*/

.rbt-icon-overlay-link-btn {
    height: 32px;
    width: 32px;
    border-radius: var(--radius-full);
    color: var(--color-primary);
    font-size: 14px;
    line-height: 32px;
    text-align: center;
    background: transparent;
    display: inline-block;
    position: relative;
    overflow: hidden;

    .rbt-btn-overlay {
        position: relative;
        overflow: hidden;
        height: 100%;
        width: 100%;
        display: block;
    }

    i {
        position: absolute;
        top: 50%;
        left: 50%;
        overflow: hidden;
        margin-top: -7px;
        margin-left: -4px;
        z-index: 1;

        &.rbt-icon {
            transition: var(--transition);
        }

        &.rbt-icon-bottom {
            position: absolute;
            transition: var(--transition);
            transform: translateY(300%) translateX(-475%);
        }

    }

    &::after {
        transition: var(--transition);
        content: "";
        width: 100%;
        height: 100%;
        background-color: var(--color-white);
        border: 1px solid var(--color-extra-four);
        border-radius: var(--radius-full);
        position: absolute;
        top: 0;
        left: 0;
        -webkit-transform: translateY(0);
        transform: translateY(0);
        opacity: 1;
    }

    &:hover {
        background: var(--color-primary);
        border-color: var(--color-primary);
        color: var(--color-primary);

        &::after {
            transform: scale(1.1);
            background: var(--color-primary);
            border-color: var(--color-primary);
            color: var(--color-white);
        }

        i {
            &.rbt-icon {
                transform: translateY(-300%) translateX(475%);
            }

            &.rbt-icon-bottom {
                transform: translateY(0) translateX(0) scale(1.1);
            }
        }
    }

    &.rbt-icon-overlay-link-btn {
        &::after {
            border: 2px solid var(--color-brand-400);
        }

        &:hover {
            &::after {
                background: var(--color-primary);
                border: 2px solid var(--color-primary);
                color: var(--color-white);
            }
        }
    }

    &:hover {
        background: transparent;
        border-color: transparent;
        color: var(--color-white);

        &::after {
            background: var(--color-primary);
            border: 2px solid var(--color-primary);
            color: var(--color-white);
        }
    }

    &.rbt-icon-overlay-link-btn-dflt-active {
        &::after {
            background: var(--color-primary);
            border-color: var(--color-primary);
            color: var(--color-white);
        }

        i {
            color: var(--color-white);

            &.rbt-icon {
                transform: translateY(-300%) translateX(300%);
            }

            &.rbt-icon-bottom {
                transform: translateY(0) translateX(0) scale(1.1);
            }
        }

        &:hover {
            &::after {
                transform: scale(0.85);
            }
        }
    }
}


