/*-----------------------
 Animation CSS
-------------------------*/



@keyframes btnTxtMarqueeX {
    100% {
        transform: translateX(-115%)
    }
}

@keyframes btnTxtMarqueeY {
    100% {
        transform: translateY(-115%)
    }
}

.rbt-btn-grp {
    display: flex;
    gap: 6px;
    position: relative;
    z-index: 3;

    &.rbt-has-separator-shape {
        >.rbt-btn-single {
            position: relative;

            &+.rbt-btn-single {
                &::before {
                    content: "";
                    position: absolute;
                    left: -12px;
                    top: 50%;
                    transform: translateY(-50%);
                    background-image: url(../images/pagination/pagination-mid-03.svg);
                    width: 18px;
                    height: 22px;
                    background-size: cover;
                    background-position: center;
                    background-repeat: no-repeat;
                    z-index: -1;

                    @media #{$sm-layout} {
                        left: -12px;
                    }
                }
            }
        }
    }
}

.rbt-trns-modern-btn {
    display: inline-flex;
    gap: 8px;
    align-items: center;
    font-size: var(--font-size-b1);
    line-height: var(--line-height-b1);
    font-weight: 500;
    position: relative;
    z-index: 1;

    &::after {
        content: '';
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%) scale(0.8);
        height: calc(100% + 8px);
        width: calc(100% + 16px);
        background: var(--color-gray-200);
        opacity: 0;
        visibility: hidden;
        z-index: -1;
        transition: var(--transition);
        border-radius: 30px;
    }

    &:hover {
        &::after {
            opacity: 1;
            visibility: visible;
            transform: translate(calc((-50%) + 4px), -50%) scale(1);
        }
    }
}

.rbt-video-area .pause-btn {
    pointer-events: none;
