@use "../default/variables" as *; // Importing all the variables
@use "../default/extend" as *; // Importing all the extend
@use "../default/mixins" as *; // Importing all the mixins

/*--------------------------
    Single Product Styles
---------------------------*/

.rbt-single-product-area {

    .rbt-card-subtitle {
        display: flex;
        font-size: var(--font-size-b1);
        line-height: var(--line-height-b1);
        color: var(--color-primary);
        font-weight: var(--f-medium);
    }

    .rbt-card-title {
        margin-top: 8px;
        margin-bottom: 0;
        font-weight: 700;
    }

    .rbt-card-rating {
        gap: 8px;

        @media #{$small-mobile} {
            gap: 4px;
        }

        .rbt-text-group {
            font-size: var(--font-size-b3);
            height: 24px;
            line-height: 24px;
        }

        .icon {
            color: var(--color-heading);

            @media #{$small-mobile} {
                font-size: var(--font-size-b3);
                line-height: 1;
            }
        }
    }

    .rbt-qty-area {
        @media #{$laptop-device} {
            padding: 10px 12px;
        }
    }

    .payment-img-link li img {
        max-height: 28px;
    }

    .description-text {
        margin-top: 16px;
        color: var(--color-gray-500);
        margin-bottom: 0;

        @media #{$small-mobile} {
            margin-top: 8px;
        }
    }

    .rbt-category {
        margin-bottom: 15px;
    }

    .rbt-card-rating {
        display: flex;
        align-items: center;
        margin-top: 8px;
        gap: 8px;

        .rating-digit {
            font-size: var(--font-size-b4);
            line-height: var(--line-height-b4);
            color: var(--color-gray-700);
            font-weight: var(--f-medium);
            margin-bottom: 0;
        }
    }

    .pricing-part {
        margin-top: 16px;
        display: flex;
        align-items: center;
        gap: 8px;
        font-size: 18px;
        font-weight: 700;
        line-height: 26px;
        color: var(--color-black);

        @media #{$sm-layout} {
            font-size: 16px;
            margin-top: 8px;
            gap: 4px;
        }

        del {
            font-weight: var(--f-medium);
            color: var(--color-gray-400);
            font-size: var(--font-size-b1);
            line-height: var(--line-height-b1);

            @media #{$sm-layout} {
                font-size: 14px;
            }
        }
    }

    .rbt-info-wrapper {
        display: flex;
        align-items: center;
        margin-top: 16px;
        gap: 8px 0;
        flex-wrap: wrap;

        @media #{$sm-layout} {
            margin-top: 8px;
        }
    }

    .rbt-product-card .rbt-card-body .right-part {
        align-items: start;
    }

    .prd-info-section {
        display: flex;
        gap: 8px;
        align-items: center;

        &.has-left-separator {
            padding-left: 16px;
            position: relative;
            margin-left: 16px;

            @media #{$sm-layout,$laptop-device} {
                margin-left: 8px;
                padding-left: 0;
            }

            &::before {
                content: "";
                display: block;
                height: 18px;
                width: 2px;
                background: var(--color-gray-200);
                left: 0;
                position: absolute;
                top: 50%;
                transform: translateY(-50%);

                @media #{$sm-layout,$laptop-device} {
                    display: none;
                }
            }

        }

        .rbt-brand-img {
            display: inline-block;
        }
    }

    .rbt-quick-access-banner-action-btn {
        .rbt-btn {
            z-index: unset;
        }
    }

    .prd-id-text {
        display: flex;
        align-items: center;
        gap: 12px;

        @media #{$sm-layout} {
            flex-wrap: wrap;
            gap: 4px;
        }

        img {
            max-height: 24px;
        }

        p {
            font-size: var(--font-size-b2);
            margin: 0;
            color: var(--color-gray-500);
            line-height: 1;

            @media #{$sm-layout} {
                font-size: var(--font-size-b4);
            }

            &.text-bold {
                font-weight: 600;
                color: var(--color-heading);
            }
        }
    }

    .product-styles-grp {
        display: flex;
        gap: 8px 16px;
        margin-top: 16px;
        align-items: baseline;

        .content {
            display: flex;
            gap: 6px;

            .rbt-btn {
                padding: 0 16px;
                color: var(--color-primary);

                &:hover,
                &:focus,
                &.active {
                    color: var(--color-white);
                }
            }
        }

        .title {
            margin: 0;
            white-space: nowrap;
            font-weight: 600;
            color: var(--color-heading);
        }
    }

    .rbt-card-text {
        color: var(--color-body);
        margin-bottom: 20px;

        @media #{$smlg-device} {
            margin-bottom: 14px;
        }

        @media #{$sm-layout} {
            margin-bottom: 10px;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }
    }

    .rbt-author-meta {
        @media #{$smlg-device} {
            margin-bottom: 10px !important;
        }
    }

    .rbt-review {
        margin-bottom: 12px;
    }

    .rbt-card-bottom {
        display: flex;
        justify-content: space-between;
        align-items: center;
        flex-wrap: wrap;

        .rbt-btn-link {
            font-size: 14px;
        }
    }

    .rbt-product-switch-area {
        display: flex;
        align-items: center;
        gap: 12px;

        .rbt-switcher-product-list {
            display: flex;
            align-items: center;
            margin: 0;
            padding: 0;
            list-style: none;
            gap: 8px;
            flex-wrap: wrap;

            li {
                margin: 0;

                .rbt-switcher--prd {
                    display: block;
                    position: relative;
                    height: auto;
                    width: 64px;
                    border-radius: 6px;

                    >img {
                        min-width: 100%;
                        border-radius: 6px;
                        border: 2px solid transparent;
                    }
                }

                &.active {
                    .rbt-switcher--prd {
                        >img {
                            border-color: var(--color-primary);
                        }
                    }
                }
            }
        }

        .title {
            margin: 0;
            white-space: nowrap;
            font-weight: 600;
            color: var(--color-heading);
            display: block;
        }

        .prd-link-text {
            font-size: var(--font-size-b4);
            line-height: var(--line-height-b4);
        }
    }

    .rbt-qty-area {
        input {
            border: 0 !important;
        }
    }

    .product-btn-grp {
        margin-top: 16px;
        display: flex;
        gap: 16px;
        align-items: center;

        @media #{$laptop-device} {
            gap: 16px;
        }

        @media #{$sm-layout} {
            margin-top: 12px;
        }

        .rbt-btn {
            // flex-basis: 100%;
            flex-grow: 1;
        }
    }

    .rbt-prd-qty-area {
        display: flex;
        gap: 12px;

        p {
            margin-bottom: 0;
            color: var(--color-gray-500);
            white-space: nowrap;

            strong {
                color: var(--color-black);
                font-weight: 600;
            }
        }

        .progress {
            margin-top: 8px;
            border-radius: 50px;
            background: #E5FAE5;
            height: 8px;
            width: 100%;

            .progress-bar {
                background: #24BD25;
                border-radius: 5px;
            }
        }
    }

    .prd-btn-grp {
        margin-top: 12px;
    }

    .rbt-quick-link-grp {
        display: flex;
        gap: 16px;
        justify-content: space-around;
        flex-wrap: wrap;
        margin-top: 16px;
        padding: 0 16px;

        @media #{$sm-layout} {
            padding: 0;
            gap: 8px;
            margin-top: 12px;
            justify-content: space-between;
        }
    }

    .rbt-quick-link {
        font-size: var(--font-size-b3);
        line-height: var(--line-height-b3);
        font-weight: var(--f-medium);
        white-space: nowrap;
        padding: 0;
        border: 0;
        outline: unset;
        cursor: pointer;
        padding: 0;
        border: 0;
        background: transparent;

        @media #{$sm-layout} {
            font-size: var(--font-size-b4);
        }

        i {
            margin-right: 4px;
        }

        &:hover {
            transform: translateY(-2px);
        }
    }

    .rbt-info-box {
        padding: 24px;
        border-radius: var(--radius-12);

        .rbt-info-title {
            font-size: var(--font-size-b1);
            line-height: var(--line-height-b1);
            font-weight: 600;
            color: var(--color-heading);
            margin-bottom: 16px;
        }

        .rbt-single-element {
            gap: 12px 32px;

            @media #{$sm-layout} {
                gap: 12px;
            }

            @media #{$small-mobile} {
                flex-wrap: wrap;
            }
        }
    }

    .product-details-list {
        margin: 0;
        padding: 0;
        padding-left: 26px;
        list-style: none;
        display: flex;
        flex-direction: column;
        gap: 10px;

        li {
            margin: 0;
            position: relative;
            font-size: var(--font-size-b3);
            line-height: var(--line-height-b3);
            color: var(--color-gray-500);

            .rbt-bold--text {
                color: var(--color-heading);
            }

            .text {
                color: var(--color-gray-500);
            }
        }

        &.shipment-details-list {
            margin-top: 12px;
            padding: 0;

            li {
                display: flex;

                &::before {
                    display: none;
                }

                .icon {
                    margin-right: 8px;
                }
            }
        }
    }

    .bootstrap-select {
        @media #{$sm-layout} {
            width: max-content !important;
        }
    }
}


.rbt-product-single-img {
    background: var(--color-gray-100);
}

.rbt-single-product-media-area {
    &.sticky-top {
        position: sticky;
        top: 150px;
    }
}



.rbt-file-upload-container {
    display: flex;
    justify-content: center;
    align-items: center;
    position: relative;

    .file-upload-area {
        width: 100%;
        text-align: center;
        transition: border-color 0.3s;
        position: relative;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        width: 100%;
        border: 2px dashed var(--color-gray-200);
        border-radius: 8px;
        text-align: center;
        transition: border-color 0.3s;
        padding: 32px;
        position: relative;
        background: var(--color-gray-light);

        @media #{$sm-layout} {
            padding: 32px;

            .file-upload-content {
                flex-wrap: wrap;
            }
        }
    }

    .file-upload-area.dragging {
        border-color: var(--color-primary);
    }

    .file-upload-content {
        display: flex;
        align-items: center;
        gap: 8px;
    }

    .rbt-title,
    .rbt-icon {
        font-size: var(--font-size-b2);
        line-height: var(--line-height-b2);
        font-weight: 500;
        color: var(--color-heading);
        margin-bottom: 0;
    }

    .upload-icon {
        width: 50px;
        margin-bottom: 10px;
    }

    .fileCount {
        color: var(--color-gray-400);
        position: absolute;
        bottom: 12px;
        right: 12px;
        margin-bottom: 0;
    }

    .file-list {
        width: 100%;
        z-index: 1;
        overflow-y: auto;
        overflow-x: hidden;
        display: flex;
        flex-direction: column;
        max-height: 45vh;
        padding-right: 16px;
        margin-right: -16px;

        &::-webkit-scrollbar-track {
            -webkit-box-shadow: inset 0 0 6px rgba(0, 0, 0, 0.1);
            background-color: var(--color-gray-200);
            border-radius: 40px;
            height: 337px;
        }

        &::-webkit-scrollbar {
            width: 4px;
            height: 337px;
            background-color: var(--color-gray-200);
        }

        &::-webkit-scrollbar-thumb {
            border-radius: 40px;
            background-color: var(--color-gray-400);
        }
    }

    .file-item {
        display: flex;
        justify-content: space-between;
        align-items: center;
        background-color: var(--color-white);
        border: 1px solid var(--color-border);
        border-radius: 4px;
        padding: 10px;
        margin-top: 16px;
    }

    .file-name {
        flex: 1;
    }

    .cancel-button {
        background-color: var(--color-gray-200);
        color: var(--color-heading);
        border: none;
        padding: 5px 10px;
        border-radius: 5px;
        cursor: pointer;
        transition: var(--transition);
    }

    .cancel-button:hover {
        background-color: var(--color-danger);
        color: var(--color-white);
    }
}

.rbt-single-product-media-area {
    &.position-sticky-top {
        position: sticky;
        top: 150px;
    }

    @media #{$sm-layout,$md-layout} {
        justify-content: center;
        gap: 16px !important;
        flex-wrap: wrap;
    }

    @media #{$lg-layout} {
        flex-wrap: nowrap;
    }

    .rbt-thumb-slide-part {
        .swiper-slide {
            button {
                .rbt-thumb-img-sm {
                    img {
                        border: 2px solid transparent;
                        transition: var(--transition);
                        max-height: 120px;

                        @media #{$sm-layout,$md-layout} {
                            max-height: unset;
                        }
                    }
                }
            }
        }

        .swiper-slide-thumb-active {
            &.swiper-slide {
                button {
                    .rbt-thumb-img-sm {
                        img {
                            border-color: var(--color-primary);
                        }
                    }
                }
            }
        }
    }
}

.rbt-single-product-content {
    >* {
        &:first-child {
            margin-top: 0 !important;
        }
    }

    &.rbt-single-product-content-sticky-one {
        position: sticky;
        top: 150px;
    }

    &.rbt-content-top-sticky-on-img {
        position: sticky;
        top: 150px;
        margin-top: -240px;
        padding: 32px;
        z-index: 2;
        border-radius: 16px;
        border: 2px solid var(--color-gray-200);
        background: var(--gradient-white-b);
        backdrop-filter: blur(50px);
        width: 488px;
        margin-left: 48px;

        @media #{$laptop-device} {
            margin-left: 0;
        }

        @media #{$xl-layout} {
            margin-left: 0;
        }

        @media #{$smlg-device} {
            width: 100%;
            margin-top: 0;
            margin-left: 0;
        }

        &.rbt-content-top-sticky-on-img-vr {
            margin-left: 0;
            margin-right: -160px;
            width: 960px;

            @media #{$laptop-device} {
                margin-right: 0;
            }

            @media #{$smlg-device} {
                width: 100%;
                margin-top: 0;
                margin-left: 0;
                margin-right: 0;
            }
        }
    }
}

.rbt-thumb-slide-part.rbt-sticky-top-150 {
    height: 100%;
}

/*---------------------------
    Rbt Countdown Banner Styles 
------------------------------*/
.rbt-countdown-banner {
    display: flex;
    align-items: center;
    gap: 12px;
    justify-content: space-between;

    @media #{$sm-layout} {
        flex-wrap: wrap;
    }

    .rbt-title {
        white-space: nowrap;
        font-weight: var(--f-semi-bold);
        color: var(--color-heading);
    }

    .rbt-desc {
        color: var(--color-gray-700);
    }

    &.rbt-countdown-banner-sm {
        padding: 16px;
        border-radius: 8px;
        border: 1px dashed var(--color-primary);

        @media #{$sm-layout} {
            justify-content: center;
        }
    }

    &.rbt-countdown-banner-sm {
        padding: 16px;
        border-radius: 8px;
        border: 1px dashed var(--color-primary);
    }

    &.rbt-countdown-banner-has-bg-01 {
        @extend %bgImagePosition;
        background-image: url('../images/countdown/countdown-banner-sm-01.webp');
        background-color: var(--color-brand-300);
    }
}


.rbt-coupon {
    min-width: 70%;
    position: relative;
    overflow: hidden;
    height: 100%;

    .inner {
        border: 2px dashed var(--color-primary);
        padding: 16px;
        background: var(--color-brand-300);
        display: flex;
        border-radius: 8px;

        @media #{$sm-layout} {
            padding: 8px;
        }
    }

    @media #{$smlg-device} {
        min-width: 100%;
    }

    .left-part {
        flex-basis: 12%;
        border-right: 2px dashed var(--color-primary);
        text-align: center;
        display: flex;
        align-items: center;
        margin-right: 16px;
        position: relative;

        &::before,
        &::after {
            content: '';
            position: absolute;
            height: 32px;
            width: 32px;
            background: var(--color-brand-50);
            border-radius: 50%;
            left: 100%;
            transform: translate(-50%);
            top: 100%;
            border: 2px dashed var(--color-primary);
            z-index: 4;
        }

        &::after {
            bottom: 100%;
            top: unset;
        }
    }

    .rbt-coupon-code-text {
        color: var(--color-primary);
        text-align: center;
        font-size: var(--font-size-b2);
        font-weight: 500;
        line-height: var(--line-height-b2);
        transform: rotate(180deg);
        white-space: nowrap;
        writing-mode: vertical-lr;
        padding: 0;
        height: auto;
        border: 0;
        width: auto;
        max-height: 100px;
    }

    .coupon-details {

        .rbt-coupon-info-title,
        .rbt-coupon-info-sub-title {
            font-weight: 600;
            margin-bottom: 0;
            color: var(--color-heading);
        }

        .rbt-coupon-info-list {
            margin: 0;
            margin: -4px 0;

            li {
                margin: 4px 0;
                font-size: var(--font-size-b4);
                line-height: var(--line-height-b4);

                @media #{$small-mobile} {
                    font-size: var(--font-size-b4);
                }
            }
        }
    }

    .copy-icon {
        display: flex;
        width: 36px;
        height: 36px;
        justify-content: center;
        align-items: center;
        font-size: var(--font-size-b3);
        position: absolute;
        right: 16px;
        top: 16px;

        &::after {
            content: attr(data-tooltip);
            width: 80px;
            height: 30px;
            top: 124%;
            right: 0;
            border-radius: var(--radius-60);
            font-size: var(--font-size-b3);
            line-height: 30px;
            opacity: 0;
            pointer-events: none;
            position: absolute;
            background-color: var(--color-primary);
            color: var(--color-gray-200);
            transform: translateY(-10px) translateX(-50%);
            text-align: center;
            transition: var(--transition);
        }

        &::before {
            content: "";
            position: absolute;
            height: 0;
            width: 0;
            margin-bottom: -47px;
            border-bottom: 8px solid var(--color-primary);
            border-right: 8px solid transparent;
            border-left: 8px solid transparent;
            opacity: 0;
            transform: translateY(-10px);
            transition: var(--transition);
        }

        &:hover {
            &::after {
                opacity: 1;
                transform: translateY(0) translateX(-50%);
            }

            &::before {
                opacity: 1;
                transform: unset;
            }
        }
    }

    &.rbt-coupon-expired {
        .inner {
            border-color: var(--color-gray-300);
            background: var(--color-brand-50);
            justify-content: space-between;
        }

        .left-part {
            border-color: var(--color-gray-300);

            &::after,
            &::before {
                border-color: var(--color-gray-300);
            }
        }

        .rbt-coupon-code-text {
            color: var(--color-gray-400);
        }

        .coupon-details {

            .rbt-coupon-info-title,
            .rbt-coupon-info-sub-title {
                color: var(--color-gray-400);
            }

            .rbt-coupon-info-list {
                li {
                    color: var(--color-gray-400);

                    &::marker {
                        color: var(--color-gray-400);
                    }
                }
            }
        }

        .rbt-btn {
            cursor: not-allowed;
            position: absolute;
            right: 16px;
            top: 16px;
        }
    }

    &.rbt-coupon-bg-white {
        .left-part {

            &::after,
            &::before {
                background: var(--color-white);
            }
        }
    }

    &.rbt-coupon-lg {
        .rbt-coupon-code-text {
            max-height: 160px;
            width: 100%;
            font-size: 20px;
            line-height: 20px;
        }
    }
}




/*---------------------------
    Rbt Combo Box Styles 
------------------------------*/

.rbt-combo-prd-box {
    padding: 32px;
    border-radius: 18px;
    border: 2px solid var(--color-gray-200);

    @media #{$small-mobile} {
        padding: 16px;
    }

    .rbt-combo-title-section {
        color: var(--color-heading);
        font-weight: var(--f-semi-bold);
        display: flex;
        flex-direction: column;
        gap: 12px;
        align-items: start;

        @media #{$small-mobile} {
            gap: 8px;
        }

        i {
            font-size: 32px;

            @media #{$small-mobile} {
                font-size: 18px;
            }
        }
    }

    .rbt-title {
        font-weight: 700;
    }


    .rbt-prd-pricing-box {
        display: flex;
        flex-direction: column;
        gap: 24px;
    }

    .rbt-pricing-box-top {
        padding: 28px;
        background: var(--color-gray-light);
        border-radius: 16px;
        display: flex;
        gap: 12px 32px;
        align-items: center;

        @media #{$sm-layout} {
            padding: 12px;
            flex-wrap: wrap;
            justify-content: center;
        }

        @media #{$small-mobile} {
            padding: 8px;
            flex-wrap: wrap;
            justify-content: center;
        }
    }

    .rbt-prd-img-area {
        display: flex;
        align-items: center;
        gap: 32px;
        overflow-x: auto;

        &::-webkit-scrollbar-track {
            -webkit-box-shadow: inset 0 0 6px rgba(0, 0, 0, 0.1);
            background-color: var(--color-gray-200);
            border-radius: 40px;
            width: 337px;
        }

        &::-webkit-scrollbar {
