// Color Swither
.rbt-color-select-area {
    display: flex;
    align-items: center;
    gap: 12px 6px;
    margin-bottom: 0;

    @media #{$small-mobile} {
        flex-wrap: wrap;
    }

    .rbt-switcher-color-list {
        display: flex;
        align-items: center;
        flex-wrap: wrap;
        margin: 0;
        padding: 0;
        list-style: none;
        gap: 8px;

        @media #{$small-mobile, $lg-layout} {
            gap: 4px;
        }

        li {
            margin: 0;

            .rbt-switcher--color {
                display: block;
                transition: var(--transition);
                border-radius: var(--radius-full);
                position: relative;
                height: 24px;
                width: 24px;
                display: flex;
                justify-content: center;
                align-items: center;

                @media #{$lg-layout} {
                    height: 20px;
                    width: 20px;
                }

                @media #{$sm-layout} {
                    height: 12px;
                    width: 12px;
                }

                &::after {
                    content: '';
                    height: 100%;
                    width: 100%;
                    top: 50%;
                    left: 50%;
                    transform: translate(-50%, -50%);
                    position: absolute;
                    border: 1px solid var(--color-gray-200);
                    border-radius: var(--radius-full);
                    transition: all 0.4s cubic-bezier(0, 0, 0.34, 0.54);

                    @media #{$small-mobile} {
                        height: 12px;
                        width: 12px;
                    }
                }

                .rbt-color-circle {
                    height: calc(100% - 8px);
                    width: calc(100% - 8px);
                    border-radius: var(--radius-full);
                    display: block;
                    transition: transform 0.4s cubic-bezier(0, 0, 0.34, 0.54);

                    @media #{$small-mobile} {
                        height: 8px;
                        width: 8px;
                    }
                }

                &.rbt-switcher--color-one {
                    .rbt-color-circle {
                        background: #2B2B2B;
                    }
                }

                &.rbt-switcher--color-two {
                    .rbt-color-circle {
                        background: #CAA1A4;
                    }
                }

                &.rbt-switcher--color-three {
                    .rbt-color-circle {
                        background: #9C9B9E;
                    }
                }

                &.rbt-switcher--color-four {
                    .rbt-color-circle {
                        background: #F2EDE7;
                    }
                }

                &.rbt-switcher--color-five {
                    .rbt-color-circle {
                        background: #B4B7C5;
                    }
                }
            }

            &.active {
                .rbt-switcher--color {
                    background: transparent;
                    display: flex;
                    justify-content: center;
                    align-items: center;

                    &::after {
                        border: 1px solid var(--color-primary);
                    }
                }

                .rbt-color-circle {
                    transform: scale(0.875);
                }
            }
        }

        &.rbt-switcher-color-list-lg {
            gap: 16px;

            @media #{$sm-layout} {
                gap: 8px;
            }

            li {
                .rbt-switcher--color {
                    .rbt-color-circle {
                        height: 24px;
                        width: 24px;

                        @media #{$sm-layout} {
                            height: 12px;
                            width: 12px;
                        }
                    }

                    &::after {
                        height: calc(100% + 12px);
                        width: calc(100% + 12px);

                        @media #{$sm-layout} {
                            height: 16px;
                            width: 16px;
                        }
                    }
                }
            }
        }
    }

    .prd-link-text {
        font-size: var(--font-size-b4);
        line-height: var(--line-height-b4);

        @media #{$small-mobile} {
            font-size: 10px;
            line-height: 1;
        }
    }
}




