        flex-direction: column;
        align-items: start;
    }

    .rbt-variation-label {
        display: flex;
        gap: 8px;
    }

    .rbt-disabled {
        filter: grayscale(1);
        opacity: 0.9;
        pointer-events: none;

        &.rbt-switcher--color {
            filter: unset;
            opacity: 1;
        }
    }

    .dropdown-menu {
        .disabled {
            background: var(--color-gray-200) !important;
        }
    }

    &.rbt-store-variation-controls-verticle {
        .prd-info-section {
            width: 100%;
        }

        .prd-id-text {
            width: 100%;
            justify-content: space-between;
            flex-direction: row;
        }
    }
}