@use "../default/variables" as *; // Importing all the variables
@use "../default/extend" as *; // Importing all the extend
@use "../default/mixins" as *; // Importing all the mixins

/*=====================
    All Product Banner Style
=======================*/

.rbt-product-banner {
    position: relative;
    z-index: 1;
    border-radius: 16px;
    border: 2px solid var(--color-brand-100);

    @media #{$sm-layout} {
        border-radius: 8px;
    }

    .rbt-banner-inner {
        border-radius: 16px;
        position: relative;
        overflow: hidden;

        @media #{$sm-layout} {
            border-radius: 8px;
        }
    }

    .rbt-banner-description {
        margin-bottom: 0;
    }

    .rbt-banner-subtitle {
        font-size: var(--font-size-b1);
        line-height: 100%;
        color: var(--color-heading);
        font-weight: var(--f-medium);

        @media #{$sm-layout} {
            font-size: var(--font-size-b3);
            line-height: var(--line-height-b3);
        }

        @media #{$sm-layout} {
            font-size: 12px;
        }
    }

    .rbt-pricing-part {
        display: flex;
        flex-direction: column;
        gap: 16px;
        margin-top: 32px;

        @media #{$small-mobile} {
            gap: 8px;
            flex-wrap: wrap;
        }

        .rbt-dis-price-text {
            color: var(--color-gray-400);
            font-size: 18px;
            font-weight: 600;
            line-height: 1;

            @media #{$sm-layout} {
                font-size: var(--font-size-b1);
            }
        }

        .rbt-price-text {
            color: var(--color-primary);
            font-weight: 700;
            font-size: var(--h2);
            line-height: 1;

            @media #{$sm-layout} {
                font-size: var(--h4);
            }
        }

        .rbt-offer-badge {
            padding: 4px 8px;
            font-size: var(--font-size-b4);
            line-height: var(--line-height-b4);

            @media #{$sm-layout} {
                font-size: 10px;
                line-height: 1;
            }
        }
    }

    .rbt-banner-title {
        margin-top: 12px;
        font-weight: 400;
        line-height: 100%;

        @media #{$md-layout, $sm-layout} {
            margin-top: 4px;
        }

        .rbt-bold--text {
            font-weight: 700;
        }

        &.text-fsize-38 {
            font-size: 38px;
            line-height: 1.2;

            @media #{$lg-layout} {
                font-size: 32px;
                line-height: 1.2;
            }

            @media #{$md-layout} {
                font-size: 30px;
                line-height: 1.2;
            }

            @media #{$sm-layout} {
                font-size: 18px;
                line-height: 1.2;
            }
        }

        &.title-capitalize-text {
            text-transform: uppercase;
        }

        &.rbt-banner-title-lg {
            font-size: var(--h1);
            line-height: 1.33;

            @media #{$lg-layout} {
                font-size: 32px;
                line-height: 1.2;
            }

            @media #{$md-layout} {
                font-size: 30px;
                line-height: 1.2;
            }

            @media #{$sm-layout} {
                font-size: 30px;
                line-height: 1.2;
            }

            @media #{$large-mobile} {
                font-size: 26px;
                line-height: 1;
            }
        }
    }

    .rbt-secondery-subtitle {
        font-family: var(--font-secondary);
        font-weight: 700;
        color: var(--color-primary);
        margin-top: 8px;
        line-height: 100%;

        @media #{$sm-layout} {
            margin-top: 4px;
        }
    }

    .rbt-product-banner-img {
        img {
            transition: var(--transition);
        }

        &.rbt-full-width-img {
            width: 100%;
            height: 100%;

            img {
                width: 100%;
                height: 100%;
                object-fit: cover;
            }
        }
    }

    [data-overlay="2"]:before,
    [data-black-overlay="2"]:before,
    [data-white-overlay="2"]:before,
    [data-gradient-overlay="2"]:before {
        z-index: 3;
    }

    &.rbt-banner-has-curved-section {
        border-radius: 0;

        .rbt-curved-portion {
            --box-size: 22px;
            position: absolute;
            transition: var(--transition);
            z-index: 1;
            width: 60%;

            .rbt-wrapper {
                position: relative;
                height: 35px;
                width: 100%;
                background: var(--color-gray-light);

                &::before,
                &:after {
                    content: "";
                    position: absolute;
                    height: var(--box-size);
                    width: var(--box-size);
                    background: transparent;
                    border-radius: var(--radius-full);
                }
            }
        }
    }

    &.rbt-banner-has-top-left-curved {
        .rbt-left-corner-portion {
            left: 0;
            top: 0;

            .rbt-wrapper {
                border-radius: 0 0 40px 0;

                &::before,
                &:after {
                    box-shadow: -8px -11px 0 0 var(--color-gray-light);
                }

                &::before {
                    top: 0px;
                    left: 100%;
                }

                &::after {
                    top: 100%;
                    left: 0;
                }
            }
        }
    }

    &.rbt-banner-has-top-right-curved {
        .rbt-right-corner-portion {
            right: 0;
            top: 0;

            .rbt-wrapper {
                border-radius: 0 0 0 40px;

                &::before,
                &:after {
                    box-shadow: 13px -13px 0 0 var(--color-gray-light);
                }

                &::before {
                    top: 0px;
                    right: 100%;
                }

                &::after {
                    top: 100%;
                    right: 0;
                }
            }
        }
    }


    &:hover {
        .rbt-product-banner-img {
            img {
                transform: scale(1.03);
            }
        }
    }

    &.has-no-hover-img-scale {
        &:hover {
            .rbt-product-banner-img {
                img {
                    transform: none;
                }
            }
        }
    }

    &.rbt-product-banner-style-one {
        border: 0;

        @media #{$smlg-device} {
            background-color: var(--color-gray-light);
            padding: 36px;
            margin-bottom: 30px;
            border: 2px solid var(--color-brand-100);
            display: flex;
            flex-direction: column-reverse;
            align-items: center;
        }

        @media #{$sm-layout} {
            padding: 16px 0;
            margin-bottom: 16px;
        }

        .rbt-banner-inner {
            display: flex;
            align-items: center;
            justify-content: end;
            padding: 0 80px;

            @media #{$smlg-device} {
                padding: 0;
                width: 100%;
            }

            @media only screen and (min-width: 1200px) and (max-width: 1399px) {
                padding: 0 40px;
            }

            @media #{$sm-layout,$md-layout} {
                display: flex;
                flex-direction: column;
                align-items: normal;
            }

            @media #{$small-mobile} {
                padding: 0 20px;
            }
        }

        .rbt-product-banner-img {
            position: absolute;
            left: 80px;
            bottom: 0;
            z-index: 2;

            @media only screen and (min-width: 1200px) and (max-width: 1399px) {
                max-width: 350px;
                left: 40px;
            }

            @media #{$sm-layout,$md-layout} {
                max-width: 250px;
                left: unset;
                bottom: unset;
                top: unset;
                transform: none;
                position: relative;
            }

            @media #{$md-layout} {
                max-width: 400px;
                left: 40px;
                bottom: unset;
                top: 50%;
                transform: translateY(-50%);
            }

            @media #{$lg-layout} {
                position: absolute;
                left: 48px;
                bottom: 8px;
                max-width: 275px;
            }
        }

        .rbt-product-banner-content {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 56px 0;

            @media #{$smlg-device} {
                position: relative;
                z-index: 1;
                padding: 0;
            }

            @media #{$sm-layout} {
                padding: 0 16px;
            }

            @media #{$small-mobile} {
                padding: 20px 0;
            }

            .rbt-content-section {
                border-left: 3px solid #E7E9EC;
                padding-left: 56px;
                margin-left: 56px;

                @media #{$smlg-device} {
                    padding-left: 20px;
                    margin-left: 20px;
                }

                @media #{$sm-layout,$md-layout} {
                    padding-left: 0;
                    margin-left: 0;
                    border: 0;
                }


                .rbt-banner-subtitle {
                    @media #{$small-mobile} {
                        font-size: 12px;
                    }
                }

            }

            .rbt-banner-btn {
                margin-left: 94px;

                @media #{$smlg-device,$laptop-device} {
                    margin-left: 54px;
                }

                @media #{$small-mobile} {
                    margin-left: 0px;
                }

                .rbt-btn {
                    @media #{$small-mobile} {
                        height: 54px;
                        width: 54px;
                        padding: 12px 16px;
                        font-size: 8px;
                        line-height: 1;
                        min-width: unset;
                    }
                }
            }
        }
    }

    &.rbt-product-banner-style-two {
        overflow: hidden;

        .rbt-banner-inner {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            text-align: center;
        }

        .rbt-product-banner-content {
            position: absolute;
            left: 50%;
            transform: translateX(-50%);
            top: 10%;

            @media #{$small-mobile} {
                width: 100%;
            }
        }

        .rbt-banner-btn {
            display: inline-block;
            margin-top: 170px;

            @media #{$laptop-device} {
                margin-top: 115px;
            }

            @media #{$sm-layout} {
                margin-top: 32px;
            }

            .rbt-btn {
                border: 1px solid var(--color-white);

                &.rbt-round-btn {
                    @media #{$small-mobile} {
                        height: 70px;
                        width: 70px;
                        font-size: var(--font-size-b4);
                        line-height: var(--line-height-b4);
                        min-width: unset;
                    }
                }

                &:hover {
                    border-color: var(--color-primary);
                }
            }
        }
    }

    &.rbt-banner-center-style {
        .rbt-product-banner-img {
            height: 100%;
            width: 100%;

            img {
                height: 100%;
                width: 100%;
                object-fit: cover;
            }
        }

        .rbt-product-banner-content {
            text-align: center;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
        }
    }

    &.rbt-banner-right-style {
        .rbt-product-banner-content {
            display: flex;
            flex-direction: column;
            justify-content: flex-end;
            align-items: flex-end;
        }
    }

    &.rbt-banner-bgdark-style {

        .rbt-banner-subtitle,
        .rbt-banner-title {
            color: var(--color-white);
        }

        .rbt-content-section {
            .rbt-banner-description {
                color: var(--color-gray-200) !important;
            }
        }

        .rbt-product-banner-img {
            z-index: 1;
        }
    }

    &.rbt-bg-color-gray-one {
        background-color: var(--color-extra-one);
    }

    &.rbt-bg-color-yellow-one {
        background-color: var(--color-extra-two);
    }

    &.rbt-product-banner-style-three {
        overflow: hidden;

        .rbt-product-banner-img {
            position: absolute;
            right: 0;
            bottom: 0;
            z-index: 1;
            height: 100%;
            width: 100%;

            img {
                object-fit: cover;
                height: 100%;
                width: 100%;
            }
        }

        .rbt-content-section {
            max-width: 524px;
            margin-right: 72px;

            @media #{$small-mobile} {
                margin-right: 0;
            }

            .rbt-banner-title {
                margin-top: 16px;

                @media #{$sm-layout} {
                    margin-top: 16px;
                }
            }

            .rbt-secondery-subtitle {
                margin-top: 24px;
            }

            .rbt-banner-subtitle {
                font-size: 18px;
                line-height: 1;

                @media #{$sm-layout} {
                    font-size: 15px;
                    margin-top: 8px;
                }
            }

            .rbt-secondery-subtitle {
                font-size: 36px;
                line-height: 1;

                @media #{$sm-layout} {
                    font-size: 18px;
                    margin-top: 8px;
                }
            }
        }

        .rbt-product-banner-content {
            position: relative;
            z-index: 2;
            padding: 77px 104px;
            display: flex;

            @media #{$md-layout} {
                padding: 40px;
            }

            @media #{$sm-layout} {
                padding: 40px;
            }

            @media #{$small-mobile} {
                padding: 32px 24px;
                flex-direction: column;
                gap: 8px;
            }
        }

        .rbt-btn {
            @media #{$small-mobile} {
                padding: 0 16px;
                background: var(--color-primary);
                height: 40px;
                width: auto;
                line-height: 40px;
                color: var(--color-white);
                font-size: 15px;
                font-weight: 600;
                display: inline-block;
                position: relative;
                z-index: 1;
                transition: all 0.4s ease-in-out;
                border-radius: var(--radius-60);
                border: 0 none;
                outline: none;
            }

            i {
                margin-right: 5px;
                font-size: var(--font-size-b3);
            }
        }
    }

    &.rbt-product-banner-style-four {
        border: 0;
        overflow: hidden;
        width: 100%;

        .rbt-product-banner-content {
            padding: 95px 56px;
            width: 100%;
            position: relative;
            z-index: 2;

            &.has-lg-space-bottom {
                padding-bottom: 140px;
            }

            @media #{$small-mobile} {
                padding: 81px 26px;
                padding-bottom: 40px !important;
            }

            @media #{$lg-layout} {
                padding: 81px 26px;
                padding-bottom: 90px !important;
            }

            &.rbt-content-style-one {
                padding-left: 48px;
                padding-right: 48px;

                @media #{$small-mobile} {
                    padding-left: 20px;
                    padding-right: 20px;
                }
            }

            &.rbt-content-style-two {
                padding: 56px 80px;

                @media #{$small-mobile} {
                    padding: 40px 20px;
                    padding-bottom: 100px;
                }
            }

            .rbt-content-section {
                max-width: 316px;

                &.rbt-content-less-wider {
                    max-width: 260px;
                }

                &.rbt-banner-content-wider {
                    max-width: 314px;
                }

                &.rbt-banner-content-lg-wider {
                    max-width: 425px;
                }

                &.rbt-content-section-full-wider {
                    max-width: none;
                }

                .rbt-banner-description {
                    margin-top: 8px;
                    margin-bottom: 0;
                    color: var(--color-gray-400);

                    &.text-color-darker {
                        color: var(--color-gray-500);

                        @media #{$smlg-device,$laptop-device} {
                            color: var(--color-gray-100);
                        }
                    }
                }

                .rbt-banner-btn {
                    margin-top: 24px;

                    @media #{$large-mobile} {
                        margin-top: 30px;
                    }
                }
            }
        }

        .rbt-product-banner-img {
            position: absolute;
            right: 0;
            bottom: 0;
            z-index: 1;
            height: 100%;
            width: 100%;
            overflow: hidden;
        }

        .rbt-product-image,
        .rbt-product-banner-img {
            img {
                transition: var(--transition);
                min-height: 100%;
            }
        }

        &.rbt-curved-style-box {
            &.rbt-curved-style-left {
                mask-image: url(../images/system/product-banner-10-left-curved-mask.webp);
                -webkit-mask-image: url(../images/system/product-banner-10-left-curved-mask.webp);
                background-image: url(../images/system/product-banner-10-left-curved-mask.webp);
            }

            &.rbt-curved-style-right {
                mask-image: url(../images/system/product-banner-10-right-curved-mask.webp);
                -webkit-mask-image: url(../images/system/product-banner-10-right-curved-mask.webp);
                background-image: url(../images/system/product-banner-10-right-curved-mask.webp);
            }
        }

        &.rbt-banner-resp-var-one {
            .rbt-product-banner-img {
                @media #{$smlg-device,$laptop-device} {
                    height: 100%;
                    width: 100%;
                }

                img {
                    @media #{$smlg-device,$laptop-device} {
                        height: 100%;
                        width: 100%;
                    }
                }
            }

            .rbt-banner-subtitle,
            .rbt-banner-title {
                @media #{$smlg-device,$laptop-device} {
                    color: var(--color-white);
                }
            }

            .rbt-product-banner-img {
                @media #{$smlg-device,$laptop-device} {
                    z-index: 1;
                    width: 100% !important;
                }
            }
        }

        &.rbt-banner-four-var-one {
            .rbt-banner-subtitle {
                font-size: var(--h6);
                line-height: 1.44;
                font-weight: 400;
                color: var(--color-heading);

                @media #{$md-layout, $sm-layout} {
                    font-size: 16px !important;
                }
            }

            .rbt-product-banner-content {
                padding: 80px 50px;
                padding-bottom: 40px;

                @media #{$large-mobile} {
                    padding: 50px 20px;
                    padding-bottom: 20px;
                }

                .rbt-pricing-part {
                    gap: 12px;
                    margin-top: 16px;

                    @media #{$large-mobile} {
                        gap: 8px;
                    }
                }
            }

            &.rbt-product-banner-accessories {

                .rbt-product-banner-content {
                    padding: 72px 52px;
                    padding-bottom: 240px !important;

                    @media #{$md-layout, $sm-layout} {
                        padding: 20px 22px 28px;
                        padding-bottom: 28px !important;
                    }

                    @media #{$lg-layout} {
                        padding: 50px 40px;
                        padding-bottom: 120px !important;
                    }

                    .rbt-pricing-part {
                        gap: 12px;
                        margin-top: 8px;

                        @media #{$large-mobile} {
                            gap: 8px;
                        }
                    }
                }

                .rbt-banner-inner {
                    min-height: 625px;

                    @media #{$lg-layout} {
                        min-height: 410px;
                    }

                    @media #{$md-layout} {
                        min-height: 330px;
                    }

                    @media #{$sm-layout} {
                        min-height: 300px;
                    }
                }

                .rbt-banner-bg-shape {
                    position: absolute;
                    height: 100%;
                    width: 100%;
                    top: 0;
                    left: 0;
                }

                &.rbt-banner-four-var-gamepad {
                    .rbt-banner-inner {
                        position: relative;
                    }

                    .rbt-product-banner-content {
                        padding: 20px 22px 28px;
                        height: 100%;
                        position: absolute;
                        inset: 0;
                        padding-bottom: 28px !important;
                    }

                    .rbt-content-section {
                        max-width: 205px;
                        min-height: 100%;
                        display: flex;
                        flex-direction: column;
                        align-items: flex-start;
                        position: relative;
                        z-index: 2;

                        .rbt-product-badge {
                            margin-bottom: 16px;
                            padding: 4px 12px;
                            min-width: 48px;
                            border-radius: var(--radius-60);
                            font-size: 12px;
                            line-height: 1.2;
                        }

                        .rbt-banner-title {
                            line-height: 1.25;
                            margin-bottom: 6px;

                            @media #{$md-layout, $sm-layout} {
                                font-size: 18px !important;
                            }
                        }

                        .rbt-banner-subtitle {
                            color: var(--color-gray-500);
                            margin-bottom: 0;
                        }

                        .rbt-banner-watermark-text {
                            position: absolute;
                            left: 50%;
                            top: 57%;
                            transform: translate(-50%, -50%);
                            font-size: 86px;
                            font-weight: var(--f-black);
                            line-height: 0.95;
                            letter-spacing: 0.02em;
                            color: var(--color-white);
                            opacity: 0.38;
                            text-align: center;
                            pointer-events: none;
                            z-index: -1;
                        }

                        .rbt-btn {
                            margin-top: auto;
                            align-self: center;
                            min-width: 180px;

                            @media #{$sm-layout,$md-layout} {
                                min-width: auto;
                                align-self: flex-start;
                            }
                        }
                    }

                    .rbt-product-banner-img {
                        img {
                            object-position: bottom center;
                        }
                    }

                    @media #{$large-mobile} {
                        .rbt-banner-inner {
                            min-height: 520px;
                        }

                        .rbt-product-banner-content {
                            padding: 16px;
                        }

                        .rbt-content-section {
                            max-width: 100%;

                            .rbt-banner-watermark-text {
                                font-size: 58px;
                            }
                        }
                    }
                }
            }

        }



        &.rbt-banner-four-var-two {
            position: relative;

            .rbt-product-banner-content {
                padding: 170px 244px;
                max-width: 2150px;
                margin: 0 auto;

                &.spacing--72 {
                    padding: 72px;
                }

                @media #{$laptop-device} {
                    padding: 120px 180px;
                }

                @media #{$lg-layout} {
                    padding: 100px 150px;
                }

                @media #{$md-layout} {
                    padding: 80px 100px;
                }

                @media #{$sm-layout} {
                    padding: 60px 20px;
                }

                &.rbt-product-banner-content-var-one {
                    padding: 150px 80px;

                    @media #{$laptop-device} {
                        padding: 120px 50px;
                    }

                    @media #{$lg-layout} {
                        padding: 100px 50px;
                    }

                    @media #{$md-layout} {
                        padding: 80px 40px;
                    }

                    @media #{$sm-layout} {
                        padding: 60px 20px;
                    }
                }

                .rbt-content-section {
                    max-width: 695px;

                    .rbt-banner-subtitle-two {
                        font-weight: 400;
                    }

                    .rbt-banner-title {
                        font-size: var(--font-size-xl);
                        line-height: 1.18;

                        @media #{$lg-layout,$md-layout} {
                            font-size: var(--h2);
                        }

                        @media #{$sm-layout} {
                            font-size: var(--h3);
                        }
                    }

                    .rbt-pricing-part {
                        margin-top: 24px;

                        @media #{$sm-layout} {
                            margin-top: 16px;
                        }

                        p {
                            margin-bottom: 0;
                        }

                        .rbt-price-text {
                            line-height: 1.3;
                        }
                    }

                    .rbt-banner-btn {
                        margin-top: 32px;

                        @media #{$sm-layout} {
                            margin-top: 16px;
