@use "../default/variables" as *; // Importing all the variables
@use "../default/extend" as *; // Importing all the extend
@use "../default/mixins" as *; // Importing all the mixins

/*----------------------------
    Edu Pagination Style  
------------------------------*/
.rbt-pagination {
    padding: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    margin: 0;
    li {
        position: relative;
        margin: 0;
        width: 48px;
        height: 48px;
        background: var(--color-brand-100);
        border-radius: var(--radius-full);
        text-align: center;
        display: flex;
        align-items: center;
        justify-content: center;
        @media #{$sm-layout} {
            width: 40px;
            height: 40px;
        }
        a {
            width: calc(100% - 8px) !important;
            height: calc(100% - 8px) !important;
            text-align: center;
            color: var(--color-heading);
            transition: 0.4s;
            font-weight:  var(--f-medium);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: var(--font-size-b1);
            line-height: var(--line-height-b1);
            border-radius: var(--radius-full);
            position: relative;
            z-index: 2;
            i {
                font-size: 18px;
                font-weight:  var(--f-medium);
            }
            &.active,
            &:hover {
                background: var(--color-primary);
                color: var(--color-white);
            }
        }
        &+li{
            &::before{
                content: '';
                position: absolute;
                left: -14px;
                top: 50%;
                transform: translateY(-50%);
                background: url(../images/pagination/pagination-mid-01.svg);
                width: 22px;
                height: 20px;
                background-size: cover;
                background-position: center;
                background-repeat: no-repeat;
            }
        }
    }
    &.rbt-pagination-sm{
        li{
            height: 36px;
            width: 36px;
            a{
                font-size: var(--font-size-b3);
                line-height: var(--line-height-b3);
                height: calc(100% - 6px);
                width: calc(100% - 6px);
                i{
                    font-size: var(--font-size-b4);
                }
            }
            & + li::before {
                left: -10px;
                width: 15px;
                height: 10px;
            }
        }
    }
}
.rbt-nav-effect-activation{
    .rbt-pagination{
        li{
            a{
                &.active,
                &:hover {
                    background: transparent;
                    background-color: transparent;
                    color: var(--color-heading);
                }
            }
        }
        &.rbt-pagination-bg-brand{
            li{
                background: var(--color-brand-200);
                a{
                    color: var(--color-primary);
                    &.active,
                    &:hover {
                        background: transparent;
                        background-color: transparent;
                        color: var(--color-white);
                    }
                    &:hover {
                        color: var(--color-brand-500);
                    }
                }
                & + li{
                    &::before{
                        background-image: url(../images/pagination/pagination-mid-02.svg);
                        transform: translateY(-50%);
                        height: 24px;
                    }
                }
            }
        }
    }
    .rbt-pagination-bg-highlight{
        background: var(--color-white);
        border-radius: 50%;
        &.rbt-pagination-bg-highlight-brand{
            background: var(--color-primary);
        }
    }
}