@use "../default/variables" as *; // Importing all the variables
@use "../default/extend" as *; // Importing all the extend
@use "../default/mixins" as *; // Importing all the mixins


/*----------------------
    Rbt Tab Style  
------------------------*/



// File Shape Tab
.rbt-fshape-tab{
    position: relative;
    z-index: 1;
    --shape-width: 52px;
    &.rbt-fshape-tab-sm{
        .nav-tabs .nav-item:first-child .nav-link{
            padding-left: 16px;
        }
        .tab-content .tab-pane{
            padding: 12px 16px;
        }
        .rbt-product-card.rbt-list-view-variation.list-view-md + .list-view-md{
            margin-top: 12px;
            padding-top: 12px;
        }
    }
    .rbt-tab-nav-wrapper{
        max-width: calc(100% - 20px);
    }
    .nav-tabs {
        border: 0;
        border: 0;
        overflow-x: auto;
        overflow-y: hidden;
        flex-wrap: nowrap;
        padding-top: 2px;
        -ms-overflow-style: none;
        &::-webkit-scrollbar { 
            width: 0 !important;
            display: none; 
        }
        .nav-link {
            margin-bottom: 0;
            background: transparent;
            border: 0;
            border-radius: 0;
            padding: 12px var(--shape-width);
            position: relative;
            z-index: 2;
            margin: 0 calc(-1/2*(var(--shape-width)));
            color: var(--color-gray-700);
            font-weight: 500;
            white-space: nowrap;
            &::before{
                content: '';
                position: absolute;
                top: -2px;
                left: var(--shape-width);
                width: calc(100% - (2*var(--shape-width)));
                height: 2px;
                background-color: transparent;
                transition: var(--transition);
            }
            &::after{
                content: '';
                position: absolute;
                top: 0;
                left: var(--shape-width);
                width: calc(100% - (2*var(--shape-width)));
                height: 100%;
                background-color: transparent;
                transition: var(--transition);
                z-index: -1;
            }
            &.disabled {
                background: unset !important;
            }
            .rbt-fshape-portion{
                position: absolute;
                top: -2px;
                width: var(--shape-width);
                height: calc(100% + 2px);
                opacity: 0;
                visibility: hidden;
                transition: var(--transition);
                &.rbt-fshape-left-portion{
                    left: 0;
                }
                &.rbt-fshape-right-portion{
                    right: 0;
                }
                &.rbt-fshape-right-portion-sm{
                    width: 48px;
                }
                svg{
                    height: 100%;
                    width: 100%;
                    display: inline-block;
                    transition: var(--transition);
                    .rbt-svg-fill-one{
                        fill: var(--color-gray-light);
                    }
                    .rbt-svg-fill-two{
                        fill: var(--color-brand-100);
                    }
                }
            }
            &.active{
                color: var(--color-primary);
                .rbt-fshape-portion{
                    opacity: 1;
                    visibility: visible;
                    svg{
                        .rbt-svg-fill-one{
                            fill: var(--color-white);
                        }
                        .rbt-svg-fill-two{
                            fill: var(--color-brand-100);
                        }
                    }
                }
                &::before{
                    background-color: var(--color-brand-100);
                }
                &::after{
                    background-color: var(--color-white);
                }
            }
        }
        .nav-item{
            margin: 0;

            &:first-child{

                .nav-link{
                    padding-left: 32px;
                    margin-left: 0;
                    @media  #{$sm-layout} {
                        padding-left: 16px;
                    }
                    &::after{
                        width: calc(100% - 50px);
                        left: 0;
                        top: -2px;
                        height: calc(100% + 2px);
                        border-top-left-radius: 16px;
                        border-top: 2px solid transparent;
                        border-left: 2px solid transparent;
                    }
                    &.active{
                        border-top-left-radius: 16px;
                        &::before{
                           display: none;
                        }
                        .rbt-fshape-left-portion{
                            display: none;
                        }
                        &::after{
                            border-color: var(--color-brand-100);
                        }
                    }
                }
                
            }

        }
       
    }
    .tab-content{
        .tab-pane{
            padding: 26px 32px;
            border: 2px solid transparent;
            border-radius: 18px;
            background-color: var(--color-white);
            position: relative;
            margin-top: -2px;
            &:first-child{
                border-top-left-radius: 0;
            }
            &.active{
                border-color: var(--color-brand-100);
            }
            @media  #{$sm-layout} {
                padding: 16px;
            }
        }

    }
}


.rbt-megamenu-tab{
    & > .nav-link {
        font-weight: var(--f-medium);
        padding: 16px;
        font-size: var(--font-size-b1);
        line-height: var(--line-height-b1);
        gap: 8px;
        display: flex;
        align-items: center;
        position: relative;
        color: var(--color-heading);
        border-radius: 6px;
        padding-left: 24px;
        transition: var(--transition);
        position: relative;
        z-index: 1;
        overflow: hidden;
        @media #{$laptop-device} {
           padding: 12px 16px;
        }
        &.disabled {
            background: transparent !important;
            pointer-events: none;
        }
        &::after{
            content: '';
            position: absolute;
            z-index: -1;
            top: 50%;
            left: 50%;
            height: 100%;
            width: 100%;
            transform: translate(-50%, -50%) scale(0.9);
            background: var(--color-white);
            border-radius: 6px;
            opacity: 0;
            transition: opacity 0.4s ease,
                        transform 0.4s cubic-bezier(0, 0, 0.34, 0.54);
        }
        .rbt-chevron-right{
            position: absolute;
            top: 50%;
            transform: translateY(-50%) translateX(-10px);
            right: 16px;
            opacity: 0;
            transition: opacity 0.4s ease,
                transform 0.4s cubic-bezier(0, 0, 0.34, 0.54);
        }
        &:hover,
        &.active {
            color: var(--color-primary);
            background: transparent;
            .rbt-chevron-right {
                transform: translateY(-50%) translateX(0);
                opacity: 1;
            }
            &::after{
                transform: translate(-50%, -50%) scale(1);
                opacity: 1;
            }
        }
    }
}




.rbt-isotop-tabs {
    display: flex;
    gap: 8px;
    margin: 0 auto;
    justify-content: center;

    @media #{$sm-layout, $md-layout} {
        justify-content: start;
    }

    .rbt-product-nav-grp {
        position: relative;
        gap: 0;

        &+.rbt-product-nav-grp {
            &::before {
                content: "";
                position: absolute;
                left: -14px;
                top: 50%;
                transform: translateY(-50%);
                background-image: url(../images/pagination/pagination-mid-01.svg);
                width: 22px;
                height: 20px;
                background-size: cover;
                background-position: center;
                background-repeat: no-repeat;
            }
        }
    }
}

.rbt-tab-btn-list {
    &.rbt-tab-btn-primary {
        button, a {
            &.active {
                background: transparent;
                color: var(--color-white);
            }
            &:hover {
                color: var(--color-gray-400);
            }
        }
    }

    button, a {
        padding: 4px 16px;
        background: transparent;
        color: var(--color-heading);
        font-size: var(--font-size-b3);
        line-height: var(--line-height-b3);
        line-height: 1.6;
        font-weight: var(--f-medium);
        border-radius: 20px;
        transition: var(--transition);
        white-space: nowrap;
        border: none;
        display: block;
        position: relative;
        z-index: 1;
        text-align: center;
        transition: 0.3s ease;

        &:focus {
            outline: none;
        }
    }

}

.rbt-bg-highlight {
    &.isotop-tab-bg-highlight {
        background: var(--color-primary);
    }
}
.rbt-menu-tab-content-wrapper {
    .rbt-megamenu-tab-content {
        position: relative;

        >.tab-pane {
            opacity: 0;
            visibility: hidden;
            transform: translateX(-20px);
            transition: opacity 0.2s cubic-bezier(0.4, 0, 1, 1), visibility 0.3s cubic-bezier(0.4, 0, 1, 1), transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
            position: absolute;
            top: 0;
            max-width: 100%;
            display: block !important;
            z-index: 1;

            &.active {
                opacity: 1;
                visibility: visible;
                transform: translateX(0);
                z-index: 10;
            }
        }
    }
}

.rbt-product-single-details-tab-sm{
    &.rbt-fshape-tab {
        .nav-tabs {
            .nav-item{
                &:first-child{
                    .nav-link{
                        padding-left: 16px;
                    }
                }
            }
        }
        .tab-content {
            .tab-pane{
                padding: 12px 16px;
            }
        }
    }
}

/*-------------------------
    Advance Tab Style Two  
--------------------------*/
.tab-button-style-2 {
    border-bottom: 2px solid var(--color-border);
    justify-content: center;
    margin-bottom: 30px;
    padding: 0;
    list-style: none;

    @media #{$sm-layout} {
        margin-bottom: 20px;
    }

    li {
        margin-top: 0;
        margin-bottom: 0;

        a {
            position: relative;
            display: block;
            outline: none;
            padding: 16px 28px;
            border: 0 none;
            box-shadow: none;

            @media #{$md-layout} {
                padding: 16px 12px;
            }

            @media #{$sm-layout} {
                padding: 14px 10px;
            }

            &::after {
                content: '';
                display: inline-block;
                width: 100%;
                height: 2px;
                position: absolute;
                bottom: -2px;
                left: 0;
                background-color: var(--color-primary);
                transform: scaleX(0);
                transition: transform .3s;
            }

            &.active {
                border: 0 none;
                outline: none;
                color: var(--color-primary);

                &::after {
                    transform: scaleX(1);
                }
            }

            .title {
                font-size: 18px;
                margin-bottom: 0;
                font-weight: 500;
            }
        }
    }
}

.advance-tab-content-style-2 {
    text-align: center;
    @media #{$lg-layout} {
        padding: 0 6%;
    }

    @media #{$md-layout} {
        padding: 0 7%;
    }

    @media #{$sm-layout} {
        padding: 0;
    }

    &.text-start {
        padding: 0;

        @media #{$lg-layout} {
            padding: 0;
        }

        @media #{$md-layout} {
            padding: 0;
        }

        @media #{$sm-layout} {
            padding: 0;
        }
    }
}