/*-------------------------
    Rbt Default
-------------------------*/
.rbt-fullwidth-wrapper {
    width: 100%;
    margin: 0 auto;
    padding: 0 100px;

    @media #{$laptop-device,$smlg-device} {
        padding: 0 32px;
    }

    @media #{$sm-layout} {
        padding: 0 16px;
    }
}

.rbt-wider-wrapper {
    width: 100%;
    margin: 0 auto;
    padding: 0 100px;
    max-width: 1920px;

    @media #{$sm-layout} {
        padding: 0 16px;
    }
}

.rbt-index-upper {
    position: relative;
    z-index: 1;
}

.sticky-top {
    position: sticky;
    top: 30px;
    z-index: 9;

    &.sticky-top-136 {
        top: 136px;
    }
}

.sticky-top-0 {
    position: sticky;
    top: 0;
    z-index: 9;
}

.max-w-unset {
    max-width: unset !important;
}

.line-height-normal {
    line-height: normal !important;
}

.rbt-single-group {
    margin: -5px;

    .rbt-single-list {
        margin: 5px;
    }
}

.transform-sm-none {
    @media #{$sm-layout} {
        transform: none !important;
    }
}

.rbt-mobile-row {
    @media #{$sm-layout} {
        overflow-x: auto;
        flex-wrap: nowrap;
        min-height: max-content;
        overflow-y: hidden;

        &::-webkit-scrollbar {
            display: none;
            -webkit-appearance: none;
            -moz-appearance: none;
        }

        .col-6 {
            width: 40%;
        }

        .col-12 {
            width: 85%;
        }

        .col-3 {
            flex: 0 0 auto;
            width: 27%;
        }
    }
}

.rbt-tablet-row {
    @media #{$md-layout} {
        overflow-x: auto;
        flex-wrap: nowrap;
        min-height: max-content;
        overflow-y: hidden;

        &::-webkit-scrollbar {
            display: none;
            -webkit-appearance: none;
            -moz-appearance: none;
        }

        .col-md-2 {
            flex: 0 0 auto;
            width: 16%;
        }
    }
}

.rbt-large-tablet-row {
    @media #{$lg-layout} {
        overflow-x: auto;
        flex-wrap: nowrap;
        min-height: max-content;
        overflow-y: hidden;

        &::-webkit-scrollbar {
            display: none;
            -webkit-appearance: none;
            -moz-appearance: none;
        }

        .col-lg-1 {
            flex: 0 0 auto;
            width: 15%;
        }
    }
}


.rbt-md-wrapper {
    max-width: 1672px;
}

.contaner-wider-device {
    max-width: 1920px !important;
}

.rbt-card-row-has-top-separator {
    .rbt-card {
        padding-top: 24px;
        border-top: 2px solid var(--color-brand-50);
    }

    &.rbt-three-align-card-row {
        >[class*=col] {

            &:nth-child(1),
            &:nth-child(2),
            &:nth-child(3) {
                .rbt-card {
                    padding-top: 0;
                    border-top: 0;
                }
            }

            &:nth-child(2),
            &:nth-child(3) {
                .rbt-card {
                    @media #{$large-mobile} {
                        padding-top: 24px;
                        border-top: 2px solid var(--color-brand-50);
                    }
                }
            }
        }
    }

    &.rbt-two-align-card-row {
        >[class*=col] {

            &:nth-child(1),
            &:nth-child(2) {
                .rbt-card {
                    padding-top: 0;
                    border-top: 0;
                }
            }

            &:nth-child(2) {
                .rbt-card {
                    @media #{$large-mobile} {
                        padding-top: 24px;
                        border-top: 2px solid var(--color-brand-50);
                    }
                }
            }
        }
    }

    &.rbt-one-align-card-row {
        >[class*=col] {
            &:nth-child(1) {
                .rbt-card {
                    padding-top: 0;
                    border-top: 0;
                }
            }
        }
    }
}

