/*-------------------------
    Rbt Round Btn
-------------------------*/
.rbt-round-btn {
    width: 35px;
    height: 35px;
    line-height: 35px;
    text-align: center;
    border-radius: var(--radius-full);
    position: relative;
    z-index: 1;
    background: transparent;
    padding: 0;
    border: 0 none;
    display: block;
    cursor: pointer;

    @media #{$sm-layout} {
        width: 30px;
        height: 30px;
        line-height: 30px;
    }

    &.rbt-bg-static-gray {
        color: var(--color-black);

        &::after {
            background: var(--color-gray-200);
            opacity: 1;
            visibility: visible;
        }
    }

    &.rbt-bg-static-primary {
        color: var(--color-white);

        &::after {
            background: var(--color-primary);
            opacity: 1;
            visibility: visible;
        }
    }

    &.bg-light-one {
        background: linear-gradient(168deg, rgba(255, 255, 255, 0.9) 0%, rgba(255, 255, 255, 0.5) 100%);
        backdrop-filter: blur(50px);
        color: var(--color-gray-300);

        &::after,
        &:hover,
        &.active {
            background: var(--color-black);
            color: var(--color-white);
            backdrop-filter: unset;
        }

        &.active {
            i {
                &::before {
                    content: "\f004";
                }
            }
        }

        &.tooltips>span {
            background: var(--color-black);
        }

        &.tooltips[data-tooltip-position=left]>span:after {
            border-left-color: var(--color-black);
        }
    }

    &.rbt-bg-primary {
        background: var(--color-primary);
        color: var(--color-white);

        &::after,
        &:hover,
        &.active {
            background: var(--color-primary);
            color: var(--color-white);
            transform: translateY(-2px);
        }

        &.active {
            i {
                &::before {
                    content: "\f004";
                }
            }
        }
    }

    i {
        margin-right: 0;
    }

    &.has-rbt-bg-black {
        background: var(--color-black);
        color: var(--color-white);

        &::after,
        &:hover,
        &.active {
            background: var(--color-primary);
            color: var(--color-white);
        }

        &.active {
            i {
                &::before {
                    content: "\f004";
                }
            }
        }
    }

    &::after {
        background: var(--color-gray-200);
        position: absolute;
        content: "";
        width: 100%;
        height: 100%;
        left: 0;
        top: 0;
        transition: var(--transition-cubic);
        opacity: 0;
        transform: scale(0.85);
        border-radius: var(--radius-full);
        z-index: -1;
    }

    &.btn-white-off {
        color: var(--color-white);
    }

    &:hover,
    &.open {
        color: var(--color-heading);

        &::after {
            opacity: 1;
            transform: scale(1);
        }
    }

    &:active {
        &::after {
            transform: scale(0.9);
            transition: var(--transition-short-cubic);
        }
    }

    &.rbt-round-btn-tr-one {
        height: 22px;
        width: 22px;
        line-height: 22px;

        .access-box-count {
            top: -9px;
            right: -9px;
        }
    }

    &.rbt-modern-close-btn {
        --icon-line-height: 16px;
        --icon-line-width: 16px;
        position: relative;

        .modern-close-wrapper {
            -webkit-font-smoothing: subpixel-antialiased;
            transform-style: preserve-3d;
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translateX(-50%) translateY(-50%) translateZ(0);
            transition: margin .2s ease, transform .2s ease 1s, opacity .3s ease;
            height: var(--icon-line-height);
            width: var(--icon-line-width);
            display: block;
            overflow: hidden;

            &::after,
            &::before {
                content: '';
                height: 100%;
                width: 2px;
                background: var(--color-heading);
                backface-visibility: hidden;
                position: absolute;
                border-radius: 5px;
                top: 0;
                left: 7px;
                transition: opacity .2s ease, background-color .2s ease;
                animation-duration: .4s;
                animation-timing-function: cubic-bezier(.50, .01, .15, 1);
                animation-fill-mode: forwards;
            }
        }
    }

    &.rbt-round-btn-xl {
        height: 66px;
        width: 66px;
        line-height: 66px;
        font-size: 18px;
    }
}


@keyframes crossLeft {
    0% {
        -webkit-transform: translateY(-30px) translateX(30px) rotate(45deg);
        transform: translateY(-30px) translateX(30px) rotate(45deg);
        opacity: 0;
        visibility: hidden;
    }

    100% {
        -webkit-transform: translateY(0) translateX(0) rotate(45deg);
        transform: translateY(0) translateX(0) rotate(45deg);
        opacity: 1;
        visibility: visible;
    }
}

@keyframes crossRight {
    0% {
        -webkit-transform: translateY(-30px) translateX(-30px) rotate(-45deg);
        transform: translateY(-30px) translateX(-30px) rotate(-45deg);
        opacity: 0;
        visibility: hidden;
    }

    100% {
        -webkit-transform: translateY(0) translateX(0) rotate(-45deg);
        transform: translateY(0) translateX(0) rotate(-45deg);
        opacity: 1;
        visibility: visible;
    }
}


/*------------------------------
    Rbt Hover Style
-------------------------------*/

.rbt-hover {
    transition: var(--transition-2);

    &:hover {
        transform: scale(1.02);
    }
}

.rbt-hover-02 {
    transition: var(--transition-2);

    &:hover {
        transform: translateY(-10px);
    }
}

.rbt-hover-03 {
    transition: transform .65s cubic-bezier(.23, 1, .32, 1);

    &:hover {
        transform: translateY(-3px);
    }
}

.rbt-link-hover {

    a,
    button {
        position: relative;

        &::after {
            content: "";
            position: absolute;
            width: 100%;
            height: 2px;
            bottom: 0;
            left: 0;
            background-color: currentColor;
            transform: scaleX(0);
            transform-origin: bottom right;
            transition: transform 0.3s;
        }

        &:hover {
            &::after {
                transform-origin: bottom left;
                transform: scaleX(1);
            }
        }
    }
}


