// RBT Tag List

.rbt-tag-list {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 12px;

    @media #{$sm-layout} {
        gap: 8px;
    }

    a {
        border: 2px solid var(--color-gray-100);
        padding: 0 12px;
        background: transparent;
        color: var(--color-heading);
        height: 36px;
        line-height: 36px;
        border-radius: 4px;
        font-size: 14px;
        display: flex;
        transition: var(--transition);
        background: var(--color-white);
        text-align: center;
        align-items: center;
        gap: 4px;
        font-weight: var(--f-medium);
        min-width: max-content !important;

        i {
            font-size: var(--font-size-b4);
            line-height: 36px;
        }

        &:hover,
        &.active {
            background: var(--color-primary);
            color: var(--color-white);
            border-color: var(--color-primary);
        }
    }

    &.rbt-tag-list-rounded {
        a {
            border-radius: 40px;
        }
    }

    &.rbt-tag-list-var-one {
        a {
            i {
                color: var(--color-primary);
                transition: var(--transition);
            }

            &:hover,
            &.active {
                background: var(--color-primary);
                color: var(--color-white);

                i {
                    color: var(--color-white);
                }
            }
        }
    }

    &.rbt-tag-list-rounded-lg {
        a {
            border-radius: 80px;
            color: var(--color-gray-400);

            &:hover,
            &:active,
            &.active {
                background: var(--color-primary);
                color: var(--color-white);

                i {
                    color: var(--color-white);
                }
            }
        }
    }

    &.rbt-tag-list-sm {
        a {
            height: 28px;
            line-height: 1.5;
            gap: 8px;

            @media #{$small-mobile} {
                gap: 0px;
                padding: 0 8px;
            }

            i {
                font-size: 12px;
                line-height: 1.5;
            }
        }
    }

    &.rbt-tag-list-bg-var-one {
        a {
            background: var(--color-brand-200);
            border: 0;

            &:hover {
                background: var(--color-primary);
            }
        }

    }

    &.rbt-tag-cancel-var {
        a {
            padding: 0 6px;
            gap: 4px;

            i {
                display: flex;
                justify-content: center;
                align-items: center;
                position: relative;
                z-index: 1;
                line-height: 1;
                height: 18px;
                width: 18px;
                transition: var(--transition);

                &::after {
                    content: '';
                    position: absolute;
                    top: 50%;
                    left: 50%;
                    height: 0;
                    width: 0;
                    border-radius: 50%;
                    background: var(--color-danger);
                    opacity: 0;
                    visibility: hidden;
                    z-index: -1;
                    transition: var(--transition);
                }

                &:hover {
                    color: var(--color-white);

                    &::after {
                        top: 0;
                        left: 0;
                        height: 100%;
                        width: 100%;
                        opacity: 1;
                        visibility: visible;
                    }
                }
            }

            &:hover {
                background: var(--color-brand-200);
                color: var(--color-heading);
            }

            &.text-decoration-underline {
                position: relative;
                z-index: 1;
                padding: 0 12px;
                background: transparent;

                &::after {
                    content: '';
                    position: absolute;
                    top: 50%;
                    left: 50%;
                    height: 50%;
                    width: 50%;
                    transform: translate(-50%, -50%);
                    background: var(--color-danger);
                    opacity: 0;
                    visibility: hidden;
                    z-index: -1;
                    transition: var(--transition);
                    border-radius: 40px;
                }

                &:hover {
                    color: var(--color-white);

                    &::after {
                        height: 100%;
                        width: 100%;
                        opacity: 1;
                        visibility: visible;
                    }
                }
            }
        }
    }
}





.rbt-color-swatch-group {
    display: flex;
    justify-content: space-between;
    align-items: center;

    .rbt-color-swatch-content {
        display: flex;
        flex: 1 1 auto;
        padding: 4px 6px;
    }

    .rbt-color-swatch {
        display: flex;
        align-items: center;
        gap: 4px;
        transition: var(--transition);

        .rbt-color-swatch-bg {
            height: 18px;
            display: inline-block;
            width: 18px;
            border-radius: var(--radius-full);
            background: transparent;
            position: relative;

            &::before {
                position: absolute;
                content: "\f00c";
                font-family: "Font Awesome 7 Pro", sans-serif;
                color: var(--color-white);
                font-size: var(--font-size-b4);
                line-height: var(--line-height-b4);
                top: 50%;
                left: 50%;
                transform: translate(-50%, -50%);
                opacity: 0;
                visibility: hidden;
                transition: var(--transition);
            }

            &::after {
                position: absolute;
                content: "\f00d";
                font-family: "Font Awesome 7 Pro", sans-serif;
                color: var(--color-white);
                font-size: var(--font-size-b4);
                line-height: var(--line-height-b4);
                top: 50%;
                left: 50%;
                transform: translate(-50%, -50%);
                opacity: 0;
                visibility: hidden;
                transition: var(--transition);
            }

            &.rbt-swatch-bg-black {
                background: #000000;
            }

            &.rbt-swatch-bg-blue {
                background: #1E73BE;
            }

            &.rbt-swatch-bg-brown {
                background: #DD9933;
            }

            &.rbt-swatch-bg-gray {
                background: #BFBFBF;
            }

            &.rbt-swatch-bg-green {
                background: #81D742;
            }

            &.rbt-swatch-bg-orange {
                background: #FF7900;
            }

            &.rbt-swatch-bg-red {
                background: #DD3233;
            }

            &.rbt-swatch-bg-yellow {
                background: #EEEE23;
            }
        }
    }

    .rbt-color-swatch-content {

        &:hover,
        &.active {
            .rbt-color-swatch-bg {
                &::before {
                    opacity: 1;
                    visibility: visible;
                }
            }
        }

        &.active {
            &:hover {
                .rbt-color-swatch-bg {
                    &::after {
                        opacity: 1;
                        visibility: visible;
                    }

                    &::before {
                        opacity: 0;
                        visibility: hidden;
                    }
                }
            }
        }
    }

    .rbt-color-swatch-text,
    .rbt-color-swatch-count {
        color: var(--color-gray-500);
        font-weight: var(--f-medium);
        font-size: var(--font-size-b2);
