@use "../default/variables" as *; // Importing all the variables
@use "../default/extend" as *; // Importing all the extend
@use "../default/mixins" as *; // Importing all the mixins

/*-----------------------
    Swiper Slider  
------------------------*/
.slick-initialized .slick-slide {
    margin-bottom: -10px;
}

// Swiper Cards 
.swiper-cards .swiper-slide {
    overflow: visible;
}

.swiper-3d .swiper-slide-shadow {
    background: transparent;
}

.swiper-horizontal>.swiper-pagination-bullets,
.swiper-pagination-bullets.swiper-pagination-horizontal,
.swiper-pagination-custom,
.swiper-pagination-fraction {
    bottom: 0;
    position: absolute;
}

// Swiper Pagination 

.rbt-dot-bottom-center {
    padding-bottom: 60px;

    @media #{$sm-layout} {
        padding-bottom: 32px;
    }

    .rbt-swiper-pagination {
        position: absolute;
        bottom: 0;
        left: 50%;
        width: max-content;
        transform: translateX(-50%);

        &.has-hide-dot-swipe {
            padding: 10px 0;
        }

        &.swiper-pagination-fraction {
            color: var(--heading-opacity);
            font-size: 18px;
            font-weight: var(--f-medium);
            letter-spacing: 3px;
        }
    }
}

.rbt-dot-top-right {
    padding-top: 60px;

    @media #{$sm-layout} {
        padding-top: 32px;
    }

    .rbt-swiper-pagination {
        position: absolute;
        top: 0;
        right: 0;
        width: max-content;
        left: unset;
        bottom: unset;
    }
}



// Swiper Progress 

.rbt-progress-bottom {
    padding-bottom: 40px;

    .swiper-pagination-progressbar {
        position: absolute;
        bottom: 0;
        left: 0;
        top: unset;
    }
}

.rbt-swiper-progress {
    &.swiper-pagination-progressbar.swiper-pagination-horizontal {
        border-radius: 40px;
        background-color: var(--color-gray-200);
        height: 6px;
        overflow: hidden;

        .swiper-pagination-progressbar-fill {
            border-radius: 40px;
            background-color: var(--color-gray-400);
        }
    }
}







.rbt-single-product-media-area {

    .product-single-slider-two-thumb-activation,
    .rbt-thumb-slide-part {
        .swiper-slide {
            button {
                outline: none;
                border: 0;
                padding: 0;
                position: relative;
            }
        }
    }

    &.rbt-single-product-media-has-folder-shape {

        .product-single-slider-two-thumb-activation,
        .rbt-product-thumb-slider-activation {
            .swiper-slide {
                button {
                    border: none;
                    padding: 0;
                    background: transparent;
                    opacity: 0.9;

                    &::before {
                        content: '';
                        position: absolute;
                        width: 100%;
                        height: 100%;
                        top: 0;
                        left: 0;
                        background: url(../images/system/product-single/sm-prd-bg-01-back.svg);
                        background-size: cover;
                        background-position: center;
                        background-repeat: no-repeat;
                        visibility: hidden;
                        opacity: 0;
                        transition: var(--transition);
