                        mask-image: url(../images/system/product-single/sm-prd-bg-01-front.svg);
                        position: relative;
                        z-index: 1;
                        @extend %bgImagePosition;
                        -webkit-mask-position: 0% 0%;
                        -webkit-mask-size: contain;
                        -webkit-mask-repeat: no-repeat;
                        border: 0;
                        display: block;
                    }
                }
            }

            .swiper-slide-thumb-active {
                &.swiper-slide {
                    button {
                        opacity: 1;
                    }

                    button::before {
                        visibility: visible;
                        opacity: 1;
                    }
