            mask-image: url(../images/system/product-single/lg-prd-bg-front.svg);
            position: relative;
            z-index: 1;
            @extend %bgImagePosition;
            -webkit-mask-position: 0% 0%;
            -webkit-mask-size: contain;
            -webkit-mask-repeat: no-repeat;
            border: 0;
        }
    }

}


.rbt-swiper-pagination {
    .swiper-pagination-bullet {
        width: 8px;
        height: 8px;
        display: inline-block;
        opacity: 1;
        border-radius: var(--radius-full);
        background: transparent;
        box-shadow: inset 0 0 0 5px var(--color-gray-300);
        transition: all 0.3s cubic-bezier(0.645, 0.045, 0.355, 1);
        margin: 0 8px !important;

        @media #{$sm-layout} {
            margin: 0 8px !important;
        }

        &.swiper-pagination-bullet-active {
            background: transparent;
            box-shadow: inset 0 0 0 1px var(--color-primary);
            transform: scale(2);
            opacity: 1;
        }
    }

    &.rbt-swiper-pagination-var-one {
        .swiper-pagination-bullet {
            width: 12px;
            height: 12px;
            box-shadow: inset 0 0 0 7px var(--color-gray-200);
            transition: var(--transition);

            // @media #{$sm-layout} {
            //     width: 8px;
            //     height: 8px;
            // }

            &:hover {
                box-shadow: inset 0 0 0 7px rgba(33, 90, 218, 0.5);
            }

            &.swiper-pagination-bullet-active {
                box-shadow: inset 0 0 0 1px rgba(33, 90, 218, 0.50);

                &::before {
                    content: '';
                    position: absolute;
                    height: 6px;
                    width: 6px;
                    background: var(--color-primary);
                    border-radius: var(--radius-full);
                    left: 50%;
                    top: 50%;
                    transform: translate(-50%, -50%);
                }
            }
        }
    }
}


.bg-gradient-3 {
    .rbt-swiper-pagination {
        .swiper-pagination-bullet {
            box-shadow: inset 0 0 0 5px var(--color-white);

            &.swiper-pagination-bullet-active {
                box-shadow: inset 0 0 0 1px var(--color-white);
            }
        }
    }
}


/*---------------------------
    Slick Arrow Styles  
-----------------------------*/

.rbt-default-modal {
    @media #{$sm-layout} {
        .rbt-arrow-between .rbt-swiper-arrow {
            display: none !important;
        }
    }
}

.rbt-arrow-between {
    position: relative;

    .rbt-swiper-arrow {
        position: absolute;
        top: 50%;
        transform: translateY(-50%);
        z-index: 2;
        transition: 0.5s;
        opacity: 0;
        width: 45px;
        height: 45px;
        line-height: 45px;
        border-radius: var(--radius-full);
        color: var(--color-body);
        background-color: var(--color-white);
        z-index: 3;
        text-align: center;

        @media #{$sm-layout} {
            opacity: 0 !important;
            visibility: visible;
        }

        .custom-overflow {
            position: relative;
            width: 100%;
            height: 100%;
            left: 0;
            top: 0;
            overflow: hidden;
        }

        i {
            position: absolute;
            top: 50%;
            left: 50%;
            overflow: hidden;
            margin-top: -9px;
            margin-left: -7px;
            z-index: 1;
            font-size: var(--font-size-b1);
            line-height: 1;

            &.rbt-icon {
                transition: var(--transition);
                transition: transform .4s cubic-bezier(.785, .135, .15, .86), -webkit-transform .4s cubic-bezier(.785, .135, .15, .86);
            }

            &.rbt-icon-top {
                position: absolute;
                transition: transform 0.4s cubic-bezier(0.785, 0.135, 0.15, 0.86), -webkit-transform 0.4s cubic-bezier(0.785, 0.135, 0.15, 0.86);
                transform: translateX(300%);
            }

        }

        &:active {
            scale: 0.95;
        }

        &::after {
            transition: var(--transition);
            content: "";
            width: 100%;
            height: 100%;
            background-color: var(--color-white);
            border-radius: var(--radius-full);
            position: absolute;
            top: 0;
            left: 0;
            -webkit-transform: translateY(0);
            transform: translateY(0);
            opacity: 1;
            z-index: -1;
        }

        &.rbt-arrow-tranparent {
            background: transparent;
            border: 2px solid var(--color-white);
            color: white;

            &::after {
                background: transparent;
            }

            &:hover {
                color: var(--color-white);
                border-color: var(--color-primary);

                &::after {
                    background-color: var(--color-primary);
                }
            }
        }

        &.rbt-arrow-gray {
            color: var(--color-heading);

            &::after {
                background-color: var(--color-extra-four);
            }
        }

        &.rbt-arrow-brand {
            color: var(--color-primary);

            &::after {
                background-color: var(--color-brand-300);
            }

            &:hover {
                color: var(--color-white);

                &::after {
                    background-color: var(--color-primary);
                }
            }
        }

        &.rbt-arrow-lg {
            height: 60px;
            width: 60px;
            font-size: 18px;
            line-height: 1.5;

            i {
                margin-top: -9px;
                margin-left: -7px;
                font-size: 18px;
                line-height: 1;
            }

            @media #{$smlg-device} {
                height: 45px;
                width: 45px;
                font-size: 16px;
            }
        }

        &.rbt-arrow-md {
            height: 56px;
            width: 56px;
            font-size: 18px;

            @media #{$md-layout,$sm-layout} {
                height: 36px;
                width: 36px;
                font-size: 16px;
            }

            @media #{$lg-layout} {
                height: 40px;
                width: 40px;
                font-size: 16px;
            }
        }

        &:hover {
            background: transparent;
            border-color: transparent;
            color: var(--color-primary);

            &::after {
                transform: scale(1.1);
            }

            i {
                &.rbt-icon {
                    transform: translateX(-300%);
                }

                &.rbt-icon-top {
                    transform: translateX(0);
                }
            }
        }

        &:active {
            &::after {
                transform: scale(0.9);
            }
        }

        &.rbt-arrow-left,
        &.rbt-modal-arrow-left {
            left: 24px;

            @media #{$sm-layout} {
                left: 20px;
            }
        }

        &.rbt-arrow-right,
        &.rbt-modal-arrow-right {
            left: auto;
            right: 24px;

            i {
                &.rbt-icon-top {
                    transform: translateX(-300%);
                }
            }

            &:hover {
                i {
                    &.rbt-icon {
                        transform: translateX(300%);
                    }

                    &.rbt-icon-top {
                        transform: translateX(0);
                    }
                }
            }

            @media #{$sm-layout} {
                left: auto;
                right: 20px;
            }
        }

        &.swiper-button-disabled {
            cursor: not-allowed;
            opacity: 0;
        }
    }

    &:hover {
        .rbt-swiper-arrow {
            @media #{$sm-layout} {
                opacity: 1 !important;
                visibility: visible;
            }
        }
    }

    &.rbt-arrow--top-right {
        .rbt-swiper-arrow {
            top: -60px;

            &.rbt-arrow-left {
                left: unset;
                right: 60px;
            }

            &.rbt-arrow-right {
                right: 0;
            }
        }

        &.rbt-arrow-lg {
            .rbt-swiper-arrow {
                top: -60px;

                &.rbt-arrow-left {
                    left: unset;
                    right: 80px;
                }

                &.rbt-arrow-right {
                    right: 0;
                }
            }
        }
    }

    .rbt-swiper-arrow-wrapper-style-one {
        @media #{$sm-layout} {
            display: none;
        }
    }

    &.rbt-dot-bottom-center {
        .rbt-swiper-arrow {
            margin-top: -29px;
        }
    }


    &.icon-bg-gray {
        .rbt-swiper-arrow {
            background: var(--color-gray-lighter);

            &::after {
                background: var(--color-gray-lighter);
            }
        }
    }

    &.rbt-arrow-bg-brand {
        .rbt-swiper-arrow {
            background: var(--color-brand-400);
            color: var(--color-primary);

            &::after {
                background: var(--color-brand-400);
                color: var(--color-white);
            }
        }
    }


    &.icon-bg-primary {
        .rbt-swiper-arrow {
            background: var(--color-primary);
            color: var(--color-white);

            &::after {
                background: var(--color-primary);
            }
        }
    }

    &.md-size {
        .rbt-swiper-arrow {
            width: 40px;
            height: 40px;
        }
    }

    &.arrow-right-bottom {
        .rbt-swiper-arrow {
            position: absolute;
            top: auto;
            transform: none;
            bottom: 0;
            right: 0;
            opacity: 1;
        }
    }

    &.rbt-arrow-show-dfl {
        .rbt-swiper-arrow {
            opacity: 1;

            &.swiper-button-disabled {
                opacity: 0.5 !important;
            }
        }
    }

    &.rbt-arrow-bottom-right {
        .rbt-swiper-arrow {
            top: 92%;

            &.rbt-arrow-left {
                right: 82px;
                left: auto;
            }

            &.rbt-arrow-right {
                right: 24px;
            }
        }
    }

    &.rbt-arrow-bottom {
        .rbt-swiper-arrow {
            top: 92%;
        }
    }

    &.rbt-arrow-bottom-between {
        .rbt-swiper-arrow {
            top: 92%;
        }

        .rbt-arrow-left {
            left: 16px;
        }

        .rbt-arrow-right {
            right: 16px;
        }
    }

    &.rbt-swiper-arrow-transparent {
        .rbt-swiper-arrow {
            background: transparent;

            &::after {
                background: transparent;
            }

            &:hover {
                box-shadow: var(--shadow-8);

                &::after {
                    background: var(--color-white);
                }
            }
        }
    }

    &.rbt-swiper-right-bottom-one {
        .rbt-swiper-arrow {
            bottom: 8px;
            left: 50%;
            top: auto;
            right: auto;
            transform: translate(-50%);

            @media #{$sm-layout,$md-layout} {
                bottom: 8px;
                left: auto;
                top: 50%;
                right: 0;
                transform: translateY(-50%) rotate(270deg);
            }
        }
    }

    &:hover {
        .rbt-swiper-arrow {
            opacity: 1;

            &.swiper-button-disabled {
                opacity: 0.5 !important;
            }
        }
    }
}

