/*------------------------------------
    Swiper Slider pagination bar
--------------------------------------*/

.rbt-swiper-pagination-dot-extend {
    &.swiper-pagination {
        bottom: 10px;
    }

    .swiper-pagination-bullet {
        width: 92px;
        height: 4px;
        border-radius: 0;
        position: relative;
        overflow: hidden;
        background: unset;
        opacity: 1;

        @media #{$laptop-device} {
            width: 60px;
        }

        @media #{$sm-layout, $md-layout, $lg-layout} {
            width: 40px;
        }

        &::before {
            content: "";
            display: block;
            position: absolute;
            top: 0;
            right: 0;
            bottom: 0;
            left: 0;
            z-index: 2;
        }

        &::after {
            content: "";
            display: block;
            position: absolute;
            top: 0;
            right: 0;
            bottom: 0;
            left: 0;
            background: var(--color-white);
            opacity: 0.4;
            z-index: 1;
        }

        &:first-child {
            border-radius: 0 0 0 var(--radius-12);
        }

        &:last-child {
            border-radius: 0 0 var(--radius-12) 0;
        }
    }

    .swiper-pagination-bullet-active {
        &::before {
            background-color: var(--color-primary);
            animation: rbt-slide-progress-anim 3s ease-out forwards;

            .swiper-paused & {
                animation-play-state: paused;
            }
        }
    }
}

.rbt-swiper-pagination-center {
    .rbt-swiper-pagination {
        width: fit-content;
        left: 50%;
        transform: translateX(-50%);
    }
}



// scroll Text Swiper
