        line-height: var(--line-height-b3);
        font-weight: var(--f-medium);
        display: flex;
        gap: 8px;
        align-items: center;
        white-space: nowrap;
    }

    .rbt-catagory-icon {
        display: inline-block;
        height: 14px;
        min-width: 14px;
        border-radius: var(--radius-full);
        border: 2px solid var(--color-white);
    }
}


