@use "../default/variables" as *; // Importing all the variables
@use "../default/extend" as *; // Importing all the extend
@use "../default/mixins" as *; // Importing all the mixins

/*===================
Catagory Styles
====================*/

.wrapper,
.container-fluid,
.rbt-fullwidth-wrapper {
    margin: 0 auto;
    max-width: 2560px;
    width: 100%;
}

.rbt-cat-box {
    position: relative;
    transition: var(--transition);
    height: 100%;
    overflow: hidden;

    .rbt-image-portion {
        img {
            transition: all 0.3s ease-in-out;
            object-fit: cover;
        }
    }

    &:hover {
        .rbt-image-portion {
            img {
                transform: scale(1.04);
            }
        }

        .rbt-icon-overlay-link-btn {
            i {
                color: var(--color-white);

                &.rbt-icon {
                    transform: translateY(-300%) translateX(300%);
                }

                &.rbt-icon-bottom {
                    transform: translateY(0) translateX(0) scale(1.04);
                }
            }

            &::after {
                transform: scale(1);
                background: var(--color-primary);
                border-color: var(--color-primary);
                color: var(--color-white);
            }

            &:hover {
                background: transparent !important;
                border-color: transparent !important;

                &::after {
                    transform: scale(0.9) !important;
                }
            }
        }
    }

    &.rbt-cat-box-1 {
        .content {
            margin-top: 16px;

            @media #{$small-mobile} {
                margin-top: 4px;
            }

            .title {
                font-size: var(--font-size-b1);
                line-height: var(--line-height-b1);
                margin-bottom: 0;
                font-weight: var(--f-medium);

                @media #{$small-mobile} {
                    font-size: 12px;
                }
            }
        }

        &:hover {
            .rbt-image-portion {
                img {
                    transform: scale(1.04);
                }
            }
        }

        &.rbt-cat-box-1-rounded {
            .inner {
                display: grid;
                justify-content: center;
            }

            .rbt-image-portion {
                height: 100%;
                width: 100%;
                border-radius: var(--radius-full);
                position: relative;
                overflow: hidden;
            }
        }

        &.rbt-cat-box-1-lg {
            .inner {
                display: flex;
                flex-direction: column;
                align-items: center;
            }

            .rbt-image-portion {
                height: 100%;
                width: 100%;
            }
        }
    }

    &.rbt-cat-box-2 {
        padding: 32px;
        border-radius: 12px;
        background: var(--color-brand-200);
        display: block;

        @media #{$sm-layout} {
            padding: 16px 8px;
            border-radius: 4px;
        }

        &.text-center {
            .inner {
                display: flex;
                flex-direction: column;
                align-items: center;
            }
        }

        .rbt-image-portion {
            height: 173px;
            width: 173px;
            border-radius: var(--radius-full);
            overflow: hidden;

            @media #{$sm-layout} {
                height: 80px;
                width: 80px;
            }

            img {
                transition: var(--transition);
                transform: scale(1.04);
            }
        }

        .content {
            margin-top: 16px;

            @media #{$sm-layout} {
                margin-top: 8px;
            }

            .title {
                font-size: var(--font-size-b1);
                line-height: var(--line-height-b1);
                margin-bottom: 0;
                font-weight: var(--f-medium);

                @media #{$sm-layout} {
                    font-size: var(--font-size-b4);
                    line-height: var(--line-height-b4);
                }
            }
        }

        &:hover {
            .rbt-image-portion {
                img {
                    transform: scale(1);
                }
            }
        }
    }

    &.rbt-cat-box-3 {
        overflow: unset;

        .inner {
            text-align: center;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
        }

        .rbt-image-portion {
            height: 100%;
            width: 100%;
            border-radius: var(--radius-full);
            position: relative;
            overflow: hidden;

            a {
                img {
                    transform: scale(1.04);
                    height: 100%;
                    width: 100%;
                }
            }
        }

        .content {
            margin-top: -22px;
        }

        .rbt-btn {
            @media #{$small-mobile} {
                height: 28px;
                line-height: 28px;
                font-size: 10px;
            }

            i {
                @media #{$small-mobile} {
                    font-size: 10px;
                }
            }
        }

        &:hover {
            .rbt-image-portion {
                a {
                    img {
                        transform: scale(1);
                    }
                }
            }
        }

        &.cat-var-two {
            .rbt-image-portion {
                max-width: 320px;
            }
        }
    }

    &.rbt-cat-box-4 {
        padding: 24px;
        padding-top: 32px;
        border-radius: 12px;
        background: var(--color-brand-50);
        border: 2px solid var(--color-brand-50);
        display: block;
        transition: var(--transition-3);

        @media #{$sm-layout} {
            padding: 8px;
            padding-top: 16px;
            border-radius: 4px;
        }

        &:hover {
            background: var(--color-brand-200);
            border-color: var(--color-primary);
        }

        .content {
            .title {
                font-size: var(--font-size-b1);
                line-height: var(--line-height-b1);
                margin-bottom: 0;
                font-weight: 600;
            }

            .quick-link-list {
                margin: 0;
                padding: 0;
                list-style: none;
                display: flex;
                flex-direction: column;
                gap: 12px;
                margin-top: 16px;

                @media #{$sm-layout} {
                    gap: 4px;
                    margin-top: 8px;
                }

                li {
                    margin: 0;
                    font-size: var(--font-size-b3);
                    line-height: var(--line-height-b3);
                }
            }
        }

        .rbt-image-portion {
            margin-top: 16px;
        }
    }

    &.rbt-cat-box-5 {
        border-radius: unset;

        .rbt-image-portion {
            border-radius: 24px;
            position: relative;
            overflow: hidden;

            @media #{$sm-layout,$md-layout} {
                border-radius: 8px;
            }

            @media #{$lg-layout} {
                border-radius: 12px;
            }
        }

        .inner {
            transition: var(--transition);

            .rbt-image-portion {
                a {
                    display: block;
                    transition: var(--transition);
                    position: relative;
                    overflow: hidden;
                    border-radius: 12px;

                    @media #{$sm-layout,$md-layout} {
                        border-radius: 8px;
                    }

                    @media #{$lg-layout} {
                        border-radius: 12px;
                    }

                    img {
                        width: 100%;
                        object-fit: cover;
                        min-height: 305px;

                        @media #{$sm-layout} {
                            min-height: 220px;
                        }
                    }
                }
            }

            .rbt-btn {
                position: absolute;
                bottom: 24px;
                left: 50%;
                transform: translateX(-50%);
                width: 80%;
                word-break: break-all;
                text-wrap: auto;
                height: auto;
                padding: 5px 15px;
                line-height: 1.5;
                min-height: 40px;
                display: flex;
                justify-content: center;
                align-items: center;

                @media #{$laptop-device,} {
                    padding: 5px 20px;
                }
            }
        }

        .rbt-right-corner-portion {
            --box-size: 40px;
            position: absolute;
            z-index: 2;
            right: -20px;
            top: -20px;
            opacity: 0;
            visibility: hidden;
            transition: var(--transition-short);

            .rbt-corner-portion-wrapper {
                position: relative;
                padding: 0 0 10px 10px;
                background: var(--color-white);
                border-radius: 0 0 0 24px;

                &::before,
                &:after {
                    content: "";
                    position: absolute;
                    height: var(--box-size);
                    width: var(--box-size);
                    background: transparent;
                    border-radius: var(--radius-full);
                    box-shadow: 13px -13px 0 0 #fff;
                }

                &::before {
                    top: 0;
                    right: 100%;
                }

                &::after {
                    top: 100%;
                    right: 0;
                }

                .rbt-card-link-btn {
                    height: 56px;
                    width: 56px;
                    border-radius: var(--radius-full);
                    background: var(--color-primary);
                    font-size: 20px;
                    line-height: 56px;
                    text-align: center;
                    color: var(--color-white);
                    display: inline-block;
                    transform: scale(1);
                    transition: var(--transition);

                    &:hover {
                        transform: scale(0.9);
                    }

                    @media #{$sm-layout} {
                        height: 44px;
                        width: 44px;
                        line-height: 44px;
                        font-size: 16px;
                    }
                }
            }

            &.bottom--position {
                bottom: -20px;
                top: unset;

                .rbt-corner-portion-wrapper {
                    padding: 10px 0 0 10px;
                    background: var(--color-white);
                    border-radius: 24px 0 0 0;

                    &::before,
                    &:after {
                        box-shadow: 15px 15px 0 0 #fff;
                    }

                    &::before {
                        bottom: 0;
                        right: 100%;
                        top: unset;
                    }

                    &::after {
                        bottom: 100%;
                        right: 0;
                        top: unset;
                    }

                    .rbt-card-link-btn {
                        height: 56px;
                        width: 56px;
                        border-radius: var(--radius-full);
                        background: var(--color-primary);
                        font-size: 20px;
                        line-height: 56px;
                        text-align: center;
                        color: var(--color-white);
                        display: inline-block;

                        @media #{$sm-layout} {
                            height: 44px;
                            width: 44px;
                            line-height: 44px;
                            font-size: 16px;
                        }
                    }
                }
            }
        }

        &.wider-coloumn {
            max-width: none;

            .rbt-image-portion {
                img {
                    min-height: 242px;
                }
            }

            .content {
                position: absolute;
                top: 32px;
                left: 32px;
                bottom: 24px;
                display: flex;
                flex-direction: column;
                justify-content: space-between;

                .subtitle {
                    margin-top: 16px;
                    margin-bottom: 0;
                    font-size: var(--font-size-b4);
                    line-height: var(--line-height-b4);
                    font-weight: var(--f-medium);
                    color: var(--color-heading);
                }

                .title {
                    margin: 0;
                    font-weight: 400;
                    color: var(--color-heading);

                    .rbt-bold--text {
                        font-weight: 700;
                    }
                }

                .bottom-content {
                    >.rbt-btn {
                        position: static;
                        transform: none;
                        top: 0;
                        left: 0;
                        width: unset;
                        display: flex;

                        &.rbt-marquee-btn {
                            width: 180px;
                            text-wrap: nowrap;
                            word-wrap: normal;
                            position: relative;
                        }
                    }
                }
            }
        }

        &.variation-two {
            .content {
                position: absolute;
                bottom: 0;
                left: 50%;
                transform: translateX(-50%);
                display: flex;
                flex-direction: column;
                width: 100%;
                padding: 24px;
                text-align: left;

                @media #{$sm-layout} {
                    padding: 12px;
                }

                .rbt-btn {
                    position: static;
                    width: unset;
                    transform: none;
                    text-align: center;
                }

                .title {
                    color: var(--color-white);
                    margin-bottom: 12px;
                    width: 75%;

                    @media #{$sm-layout} {
                        width: 100%;
                    }
                }
            }
        }

        &:hover {
            .rbt-icon-overlay-link-btn {
                height: 50px;
                width: 50px;
                line-height: 50px;
                font-size: 20px;
                display: block;

                &::after {
                    transform: scale(1);
                    background: var(--color-primary);
                    border-color: var(--color-primary);
                    color: var(--color-white);
                }

                i {
                    margin-top: -10px;
                    margin-left: -5px;
                    color: var(--color-white);

                    &.rbt-icon {
                        transform: translateY(-300%) translateX(300%);
                    }

                    &.rbt-icon-bottom {
                        transform: translateY(0) translateX(0) scale(1.04);
                    }
                }
            }

            .rbt-right-corner-portion {
                opacity: 1;
                visibility: visible;
                right: 0;
                top: 0;

                .rbt-card-link-btn {
                    &:hover {
                        background: var(--color-primary);
                    }
                }

                &.bottom--position {
                    top: unset;
                    bottom: 0;
                }
            }
        }

        &.variation-one {
            border-radius: unset;

            .content {
                .title {
                    margin-top: 16px;
                    margin-bottom: 0;
                    font-size: var(--font-size-b2);
                    line-height: var(--line-height-b2);
                    font-weight: var(--f-medium);

                    a {
                        display: block;
                    }
                }
            }

            .rbt-image-portion {
                border-radius: 12px;
            }
        }

        &.variation-three {
            .inner {
                height: 100%;
            }

            .rbt-image-portion {
                border-radius: var(--radius-10);
                height: 100%;

                a {
                    height: 100%;

                    &::before {
                        content: "";
                        position: absolute;
                        width: 100%;
                        height: 100%;
                        top: 50%;
                        left: 50%;
                        transform: translate(-50%, -50%);
                        z-index: 1;
                        border-radius: 10px;
                        background: linear-gradient(180deg, rgba(0, 0, 0, 0.00) 23.85%, rgba(0, 0, 0, 0.60) 100%);
                    }

                    img {
                        transform: scale(1);
                        height: 100%;
                    }
                }
            }

            .content {
                position: absolute;
                width: 100%;
                bottom: 24px;
                padding: 0 12px;
                z-index: 2;
            }

            &:hover {
                .rbt-image-portion {
                    img {
                        transform: scale(1.02);
                    }
                }
            }
        }

        &.variation-four {
            .inner {
                .rbt-image-portion {
                    a {
                        img {
                            min-height: unset;
                        }
                    }
                }
            }

            .inner {
                .content {
                    .title {
                        margin-top: 16px;
                    }
                }
            }
        }
    }

    &.rbt-cat-box-6 {
        background: var(--color-brand-200);
        border-radius: 16px;
        padding: 32px 40px;

        @media #{$sm-layout} {
            padding: 12px 16px;
        }

        .title {
            font-weight: 700;
            margin-bottom: 0;
        }

        .rbt-image-portion {
            margin-top: 16px;

            @media #{$sm-layout} {
                margin-top: 12px;
            }
        }

        .quick-button-list {
            margin: 0;
            padding: 0;
            list-style: none;
            display: flex;
            flex-direction: column;
            margin-top: 24px;
            gap: 16px;

            @media #{$sm-layout} {
                margin-top: 12px;
                gap: 8px;
            }

            li {
                margin: 0;

                .rbt-btn {
                    display: block;
                    padding: 0 10px;

                    @media #{$sm-layout} {
                        height: 28px;
                        line-height: 28px;
                    }
                }
            }
        }

        .rbt-image-portion {
            a {
                img {
                    max-height: 150px;

                    @media #{$sm-layout} {
                        max-height: 80px;
                    }
                }
            }
        }
    }

    &.rbt-cat-box-7 {
        border-radius: 16px;
        border: 1px solid var(--color-extra-four);
        background: var(--color-white);

        @media #{$sm-layout} {
            border-radius: var(--radius);
        }

        .inner {
            display: flex;

            @media #{$sm-layout} {
                padding: 8px 12px;
                padding-bottom: 52px;
                position: relative;
                flex-direction: column-reverse;
                align-items: flex-start;
            }
        }

        .content {
            padding: 24px;
            padding-right: 0;
            flex-basis: 70%;

            @media #{$sm-layout} {
                padding: 0;
                flex-basis: 100%;
            }

            .title {
                font-size: var(--font-size-b1);
                line-height: 1;
                margin-bottom: 0;
                font-weight: 600;
            }

            .quick-link-list {
                margin: 0;
                padding: 0;
                list-style: none;
                display: flex;
                flex-direction: column;
                gap: 8px;
                margin-top: 16px;

                li {
                    margin: 0;
                    font-size: var(--font-size-b3);
                    line-height: 1.1;
                    font-weight: 400;

                    a {
                        color: var(--color-gray-600);

                        &:hover {
                            color: var(--color-primary);
                        }
                    }
                }
            }
        }

        .rbt-icon-overlay-link-btn {
            @media #{$sm-layout} {
                position: absolute;
                bottom: 8px;
                left: 12px;
            }
        }

        .rbt-image-portion {
            text-align: center;

            a {
                img {
                    max-width: 93px;
                    height: auto;

                    @media #{$sm-layout} {
                        max-width: 64px;
                        margin-bottom: 4px;
                    }
                }
            }
        }
    }

    &.rbt-cat-box-8 {
        padding: 32px;
        overflow: hidden;
        border-radius: 16px;
        min-height: 260px;

        .inner {
            display: flex;
            flex-direction: column;
            justify-content: end;
            height: 100%;
        }

        .content {
            position: relative;
            z-index: 2;
            width: fit-content;

            .rbt-badge {
                margin-bottom: 12px;
            }

            .subtitle {
                margin: 0;
                color: var(--color-white);
                font-size: var(--font-size-b4);
                line-height: var(--line-height-b4);
            }

            .title {
                color: var(--color-white);
                margin-bottom: 20px;

                a {
                    &:hover {
                        color: var(--color-primary);
                    }
                }
            }

            .qty-text {
                color: var(--color-gray-100);
                margin-bottom: 0;
            }

            .rbt-btn {
                background: rgba(255, 255, 255, 0.20);
                color: var(--color-white);

                &:hover {
                    background: var(--color-primary);
                }
            }
        }

        .rbt-image-portion {
            position: absolute;
            height: 100%;
            width: 100%;
            left: 0;
            top: 0;
            z-index: 1;

            img {
                transform: scale(1.04);
                min-height: 100%;
                width: 100%;
            }
        }

        .has-rbt-sectioin-overlay {
            position: relative;
            height: 100%;
            display: block;

            &::after {
                content: '';
                position: absolute;
                height: 100%;
                width: 100%;
                left: 0;
                top: 0;
                background: linear-gradient(rgba(118, 65, 31, 0.1) 0%, rgba(49, 19, 0, 0.7) 100%);
                opacity: 0.9;
            }

            &.rbt-sectioin-overlay-black {
                &::after {
                    opacity: 0.7;
                    background: linear-gradient(180deg, #000 0%, rgba(0, 0, 0, 0.00) 100%);
                }
            }

            &.rbt-sectioin-overlay-white {
                &::after {
                    opacity: 0.7;
                    background: linear-gradient(180deg, rgba(0, 0, 0, 0.1) 0%, rgba(0, 0, 0, 0.50) 100%);
                }
            }

            &.rbt-sectioin-overlay-black-reverse {
                &::after {
                    opacity: 1;
                    background: linear-gradient(180deg, rgba(3, 14, 3, 0.00) 22.08%, rgba(3, 14, 3, 0.80) 86.53%);
                }
            }
        }

        &.rbt-curved-style-box {
            mask-image: url(../images/system/catagory-8-curved-top-mask.webp);
            -webkit-mask-image: url(../images/system/catagory-8-curved-top-mask.webp);
            background-image: url(../images/system/catagory-8-curved-top-mask.webp);
        }

        &:hover {
            .rbt-image-portion {
                img {
                    transform: scale(1);
                }
            }
        }

        &.rbt-cat-box-8-var-one {
            min-height: 630px;

            @media #{$xl-layout} {
                min-height: 464px;
            }

            @media #{$md-layout, $lg-layout} {
                min-height: 400px;
            }

            @media #{$sm-layout} {
                min-height: 324px;
            }

            .subtitle {
                font-size: 20px;
                line-height: 1.5;
            }
        }

        &.rbt-cat-box-8-var-two {
            padding: 0;

            .content {
                position: absolute;
            }

            .rbt-image-portion {
                position: static;
            }

            .inner {
                justify-content: center;
                align-items: center;
                text-align: center;
            }

            .title {
                margin-bottom: 0;
            }
        }

        &.rbt-cat-box-8-var-three {
            min-height: 416px;

            @media #{$sm-layout} {
                padding: 16px;
                min-height: 250px;
            }

            .rbt-btn {
                display: block;
                text-align: center;
                backdrop-filter: blur(12px);
            }

            .title {
                width: 75%;

                @media #{$sm-layout} {
                    width: 100%;
                    margin-bottom: 8px;
                }
            }
        }

        &.rbt-cat-box-8-var-four {
            padding: 0;

            .inner {
                flex-direction: column-reverse;
            }

            .rbt-image-portion {
                position: static;
                border-radius: var(--radius-12);
                overflow: hidden;
            }

            .content {
                text-align: center;
                padding-top: 24px;
                width: unset;

                @media #{$sm-layout} {
                    padding-top: 16px;
                }

                .subtitle {
                    color: var(--color-gray-400);
                    font-weight: var(--f-medium);
                    font-size: var(--font-size-b2);
                }

                .title {
                    color: var(--color-black);
                }

                .rbt-btn {
                    background: var(--color-primary);
                }
            }
        }

        &.h-650 {
            min-height: 650px;
        }
    }

    &.rbt-cat-box-9 {
        background: var(--color-gray-light);
        border-radius: var(--radius-12);

        .inner {
            padding: 32px;
            min-height: 204px;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            flex-grow: 1;
        }

        .content {
            position: relative;
            z-index: 1;
            flex-grow: 1;
            display: flex;
            flex-direction: column;
            justify-content: space-between;

            .top-content {
                .rbt-badge {
                    position: absolute;
                    right: -8px;
                    top: -8px
                }

                .title {
                    margin-bottom: 8px;
                }
            }
        }

        .rbt-image-portion {
            position: absolute;
            width: 100%;
            height: 100%;
            top: 0;
            right: 0;
            display: flex;
            justify-content: end;
            align-items: center;

            img {
                max-height: 204px;
            }
        }

        &.rbt-cat-box-9-var-two {
            border-radius: var(--radius-md);
            overflow: visible;
            transition: var(--transition);

            .inner {
