/*------------------------------
    Category Update Style  
--------------------------------*/
.rbt-category-update {
    position: relative;
    height: 44px !important;
    z-index: 2;

    &:hover {
        border-radius: 6px 6px 0 0;
    }

    .rbt-category-btn {
        display: flex;
        align-items: center;
        font-size: 14px;
        height: 100%;
        font-style: normal;
        font-weight: 400;
        line-height: 14px;
        gap: 8px;
        padding: 12px 16px;
        min-width: 280px;
        border-radius: var(--radius);
        background: var(--color-primary);
        color: var(--color-white);
        position: relative;
        cursor: pointer;
        transition: var(--transition);

        @media #{$laptop-device} {
            min-width: 180px;
        }

        .fa-chevron-down {
            position: absolute;
            right: 16px;
            font-size: 12px;
            line-height: 12px;
            top: 50%;
            transform: translateY(-50%);
        }
    }

    .rbt-update-category-dropdown {
        position: absolute;
        left: 0;
        top: 105%;
        cursor: default;
        visibility: hidden;
        opacity: 0;
        transition: 0s ease;
        background: #fff;
        box-shadow: 0px 4px 30px 10px rgba(0, 0, 0, 0.05);
        border-radius: 0 0 0 6px;
        z-index: 1;
        width: 100%;

        .inner {
            max-width: 100%;

            .rbt-dropdown-parent-wrapper {
                @extend %liststyle;

                .dropdown-parent-list {
                    margin: 0;
                    position: relative;

                    &+.dropdown-parent-list {
                        border-top: 2px solid var(--color-gray-light);
                    }

                    &>a {
                        font-weight: var(--f-medium);
                        padding: 12px 16px;
                        font-size: var(--font-size-b3);
                        line-height: var(--line-height-b3);
                        gap: 8px;
                        display: flex;
                        align-items: center;
                        position: relative;
                        color: var(--color-heading);
                        margin: 0;
                        border-radius: 3px;

                        .rbt-chevron-right {
                            position: absolute;
                            top: 50%;
                            transform: translateY(-50%);
                            right: 16px;
                        }

                        &:hover {
                            color: var(--color-primary);
                            background: var(--color-gray-light);
                        }
                    }

                    .rbt-dropdown-child-wrapper {
                        position: absolute;
                        top: 0;
                        left: 100%;
                        display: flex;
                        flex-wrap: wrap;
                        justify-content: space-between;
                        align-items: flex-start;
                        background-color: var(--color-white);
                        opacity: 0;
                        visibility: hidden;
                        transition: 0.3s ease;
                        min-width: 415px;
                        min-height: 100%;
                        z-index: 1;
                        border-radius: 0px 8px 8px 8px;
                        box-shadow: var(--shadow-1);
                        overflow: hidden;

                        .rbt-child-inner {
                            display: flex;
                            flex-wrap: wrap;
                            width: 100%;
                            justify-content: space-between;
                            align-items: flex-start;
                            align-self: flex-start;

                            .dropdown-child-list {
                                position: relative;
                                width: 50%;
                                z-index: 100;
                                margin: 0;

                                a {
                                    font-size: 15px;
                                    line-height: 18px;
                                    text-transform: none;
                                    font-weight: 300;
                                    display: block;
                                    color: var(--color-heading);
                                    display: block;
                                    padding: 9px 10px;
                                    transition: 0.4s;

                                    &:hover {
                                        color: var(--color-primary);
                                    }
                                }
                            }

                            .rbt-megamenu-wrapper {
                                margin-top: 0;
                            }

                            .rbt-megamenu {

                                .rbt-short-title,
                                .rbt-short-title {
                                    margin-bottom: 0;
                                    padding: 12px;
                                    border-bottom: 2px solid var(--color-gray-100);
                                }

                                .rbt-small-title {
                                    font-weight: 700;
                                    color: var(--color-black);
                                }

                                .mega-menu-item {
                                    padding: 0;
                                    margin: 0;
                                    height: 100%;
                                    margin-top: 8px;
                                    list-style: none;

                                    li {
                                        margin: 4px 0;

                                        a {
                                            font-weight: var(--f-medium);
                                            padding: 4px 12px;
                                            font-size: var(--font-size-b1);
                                            line-height: var(--line-height-b1);
                                            display: block;
                                            color: var(--color-gray-700);
                                            margin: 0;
                                            border-radius: 4px;
                                            transition: var(--transition);
                                            display: flex;
                                            align-items: center;

                                            .rbt-badge-card {
                                                margin-left: 10px;
                                            }

                                            &:hover,
                                            &.active {
                                                color: var(--color-primary) !important;
                                                background: var(--color-gray-100);
                                            }
                                        }
                                    }
                                }

                                .rbt-mega-menu-img img {
                                    border-radius: var(--radius);
                                }

                                .rbt-quick-info-tag {
                                    margin-top: 20px;
                                }

                                .rbt-ads-wrapper {
                                    img {
                                        width: 100%;
                                        object-fit: cover;
                                        border-radius: 4px;

                                    }
                                }
                            }
                        }

                        &.rbt-dropdown-child-wrapper-lg {
                            min-width: 734px;
                        }

                        &.rbt-dropdown-child-wrapper-left-align {
                            right: 100%;
                            left: unset;
                            border-radius: 8px 0 8px 8px;
                        }
                    }

                    &:hover {
                        .rbt-dropdown-child-wrapper {
                            opacity: 1;
                            visibility: visible;
                        }
                    }

                    &.active {
                        &>a {
                            color: var(--color-primary);
                            background: var(--color-brand-100);
                        }

                        .rbt-dropdown-child-wrapper {
                            opacity: 1;
                            visibility: visible;
                        }

                        .rbt-dropdown-child-wrapper {
                            display: block !important;
                        }
                    }
                }
            }
        }

    }

    &:hover {
        .rbt-update-category-dropdown {
            opacity: 1;
            visibility: visible;
            transition: .3s ease;
            top: 100%;
        }

        .rbt-category-btn {
            border-radius: 6px 6px 0 0;
        }
    }

    &.rbt-category-menu-wrapper-var-one {
        text-align: left;
        height: 36px !important;

        .rbt-category-btn {
            padding: 8px 16px;
            background: rgba(255, 255, 255, 0.15);
        }

        &:hover {
            .rbt-category-btn {
                border-radius: 6px 6px 0 0;
            }
        }
    }
}

