.rbt-cat-cat-box-1 {
    position: relative;
    display: flex;
    align-items: center;
    gap: 4px;
    padding: 8px;
    border-radius: 4px;
    transition: var(--transition);
    z-index: 1;

    .rbt-cat-icon {
        font-size: 18px;
        line-height: 1;
        color: var(--color-primary);
        transition: var(--transition);
    }

    .title {
        font-size: var(--font-size-b3);
        line-height: var(--line-height-b3);
        color: var(--color-heading);
        font-weight: 500;
        transition: var(--transition);
    }

    &::after {
        content: '';
        position: absolute;
        left: 50%;
        top: 50%;
        height: 100%;
        width: 100%;
        border-radius: 4px;
        transform: translate(-50%, -50%) scale(0.85);
        background: var(--color-primary);
        opacity: 0;
        visibility: hidden;
        transition: var(--transition);
        z-index: -1;
    }

    &:hover {
        color: var(--color-white);

        .title,
        .rbt-cat-icon {
            color: var(--color-white);
        }

        &::after {
            transform: translate(-50%, -50%) scale(1);
            visibility: visible;
            opacity: 1;
        }
    }
}


